BOOK.add({
  subject: "cg",
  id: "cg-25",
  title: "छत्तीसगढ़ — पंचायती राज, नगरीय निकाय, पेसा एवं स्थानीय शासन (विस्तृत अभ्यास)",
  notes: "\n    <h3>1. पंचायती राज की संवैधानिक पृष्ठभूमि</h3>\n    <table>\n      <tr><th>वर्ष</th><th>घटना / समिति</th><th>मुख्य बिंदु</th></tr>\n      <tr><td>1950</td><td>अनुच्छेद 40 (नीति-निदेशक तत्त्व)</td><td>राज्य ग्राम पंचायतों का संगठन करेगा और उन्हें स्वशासन की इकाई के रूप में शक्तियाँ देगा</td></tr>\n      <tr><td>2 अक्टूबर 1952</td><td>सामुदायिक विकास कार्यक्रम</td><td>1953 में राष्ट्रीय विस्तार सेवा; दोनों की समीक्षा हेतु बलवंत राय मेहता समिति</td></tr>\n      <tr><td>1957</td><td>बलवंत राय मेहता समिति</td><td>त्रिस्तरीय व्यवस्था, \"लोकतांत्रिक विकेंद्रीकरण\"; ज़िला परिषद का अध्यक्ष कलेक्टर</td></tr>\n      <tr><td>2 अक्टूबर 1959</td><td>नागौर (राजस्थान)</td><td>पं. नेहरू द्वारा पंचायती राज का उद्घाटन; उसी वर्ष बाद में आंध्र प्रदेश</td></tr>\n      <tr><td>1963</td><td>के. संथानम समिति</td><td>पंचायतों के वित्त (कर लगाने की शक्ति) पर</td></tr>\n      <tr><td>1977–78</td><td>अशोक मेहता समिति</td><td>द्विस्तरीय व्यवस्था — मंडल पंचायत व ज़िला परिषद; राजनीतिक दलों की भागीदारी</td></tr>\n      <tr><td>1985</td><td>जी.वी.के. राव समिति</td><td>ज़िला स्तर को नियोजन व विकास की मुख्य इकाई बनाने की सिफ़ारिश</td></tr>\n      <tr><td>1986</td><td>एल.एम. सिंघवी समिति</td><td>पंचायतों को संवैधानिक दर्जा, न्याय पंचायतें</td></tr>\n      <tr><td>1989</td><td>64वाँ संशोधन विधेयक</td><td>लोकसभा में पारित, राज्यसभा में गिर गया</td></tr>\n      <tr><td>1992–93</td><td>73वाँ संविधान संशोधन</td><td>राष्ट्रपति की अनुमति 20 अप्रैल 1993; 24 अप्रैल 1993 से लागू (राष्ट्रीय पंचायती राज दिवस)</td></tr>\n      <tr><td>1 जून 1993</td><td>74वाँ संविधान संशोधन लागू</td><td>नगरपालिकाएँ — भाग IXक, 12वीं अनुसूची</td></tr>\n      <tr><td>24 दिसंबर 1996</td><td>पेसा अधिनियम लागू</td><td>दिलीप सिंह भूरिया समिति की सिफ़ारिश</td></tr>\n      <tr><td>27 मई 2004</td><td>पंचायती राज मंत्रालय</td><td>केंद्र में पृथक मंत्रालय बना</td></tr>\n    </table>\n\n    <h3>2. भाग IX — पंचायतें (अनु. 243 से 243-O)</h3>\n    <table>\n      <tr><th>अनुच्छेद</th><th>विषय</th></tr>\n      <tr><td>243</td><td>परिभाषाएँ — ग्राम सभा = ग्राम स्तर की पंचायत क्षेत्र के ग्राम की मतदाता सूची में दर्ज व्यक्तियों का निकाय</td></tr>\n      <tr><td>243A</td><td>ग्राम सभा — राज्य विधानमंडल द्वारा दी गई शक्तियाँ</td></tr>\n      <tr><td>243B</td><td>त्रिस्तरीय पंचायतें; 20 लाख से अनधिक जनसंख्या वाले राज्य में मध्यवर्ती स्तर आवश्यक नहीं</td></tr>\n      <tr><td>243C</td><td>संरचना; मध्यवर्ती व ज़िला पंचायत के अध्यक्ष निर्वाचित सदस्यों द्वारा और उनमें से चुने जाएँगे</td></tr>\n      <tr><td>243D</td><td>आरक्षण — SC/ST जनसंख्या अनुपात में; महिलाओं हेतु कम से कम 1/3; अध्यक्ष पदों का आरक्षण; पिछड़े वर्गों हेतु राज्य विधि से</td></tr>\n      <tr><td>243E</td><td>कार्यकाल 5 वर्ष (प्रथम बैठक से); विघटन पर 6 माह में चुनाव</td></tr>\n      <tr><td>243F</td><td>अयोग्यताएँ — 21 वर्ष पूर्ण होने पर आयु के आधार पर अयोग्य नहीं</td></tr>\n      <tr><td>243G</td><td>शक्तियाँ व उत्तरदायित्व — 11वीं अनुसूची (29 विषय)</td></tr>\n      <tr><td>243H</td><td>कर लगाने की शक्ति व पंचायत निधि</td></tr>\n      <tr><td>243I</td><td>राज्य वित्त आयोग — राज्यपाल द्वारा, प्रत्येक 5 वर्ष पर</td></tr>\n      <tr><td>243J</td><td>लेखा-परीक्षा</td></tr>\n      <tr><td>243K</td><td>राज्य निर्वाचन आयोग — राज्यपाल द्वारा नियुक्त; उच्च न्यायालय के न्यायाधीश की भाँति ही हटाया जा सकता है</td></tr>\n      <tr><td>243L</td><td>संघ राज्य क्षेत्रों पर लागू होना</td></tr>\n      <tr><td>243M</td><td>कुछ क्षेत्रों पर लागू नहीं — अनुसूचित क्षेत्र, जनजातीय क्षेत्र, नागालैंड, मेघालय, मिज़ोरम आदि (संसद विस्तार कर सकती है — इसी से पेसा)</td></tr>\n      <tr><td>243N</td><td>पुराने विधियों का अधिकतम 1 वर्ष तक जारी रहना</td></tr>\n      <tr><td>243O</td><td>निर्वाचन मामलों में न्यायालयों के हस्तक्षेप का वर्जन</td></tr>\n    </table>\n    <div class=\"tip\">ट्रिक: 243-<b>K</b> = <b>K</b>aun chunav karayega (निर्वाचन आयोग); 243-<b>I</b> = <b>I</b>ncome/वित्त आयोग। नगरीय निकाय में यही 243ZA (निर्वाचन) और 243Y (वित्त) हैं।</div>\n\n    <h3>3. ग्यारहवीं अनुसूची — 29 विषय (अनु. 243G)</h3>\n    <ol>\n      <li>कृषि (कृषि विस्तार सहित)</li><li>भूमि सुधार, भू-संरक्षण</li><li>लघु सिंचाई, जल प्रबंधन, जलग्रहण क्षेत्र विकास</li><li>पशुपालन, डेयरी, कुक्कुट पालन</li><li>मत्स्य पालन</li><li>सामाजिक वानिकी व फ़ार्म वानिकी</li><li>लघु वनोपज</li><li>लघु उद्योग (खाद्य प्रसंस्करण सहित)</li><li>खादी, ग्राम एवं कुटीर उद्योग</li><li>ग्रामीण आवास</li><li>पेयजल</li><li>ईंधन और चारा</li><li>सड़कें, पुलिया, पुल, घाट, जलमार्ग</li><li>ग्रामीण विद्युतीकरण</li><li>गैर-पारंपरिक ऊर्जा स्रोत</li><li>गरीबी उन्मूलन कार्यक्रम</li><li>शिक्षा (प्राथमिक व माध्यमिक विद्यालय)</li><li>तकनीकी प्रशिक्षण व व्यावसायिक शिक्षा</li><li>प्रौढ़ व अनौपचारिक शिक्षा</li><li>पुस्तकालय</li><li>सांस्कृतिक क्रियाकलाप</li><li>बाज़ार और मेले</li><li>स्वास्थ्य व स्वच्छता (अस्पताल, PHC, औषधालय)</li><li>परिवार कल्याण</li><li>महिला एवं बाल विकास</li><li>समाज कल्याण (दिव्यांग व मानसिक मंद सहित)</li><li>कमज़ोर वर्गों, विशेषतः SC/ST का कल्याण</li><li>सार्वजनिक वितरण प्रणाली</li><li>सामुदायिक परिसंपत्तियों का अनुरक्षण</li>\n    </ol>\n    <p>छत्तीसगढ़ पंचायत राज अधिनियम की <b>अनुसूची IV</b> (धारा 53) में यही 29 विषय दोहराए गए हैं।</p>\n\n    <h3>4. छत्तीसगढ़ पंचायत राज अधिनियम, 1993 — मुख्य प्रावधान</h3>\n    <p>अधिनियम क्रमांक 1 सन् 1994; राज्यपाल की अनुमति 24 जनवरी 1994 (मूलतः मध्यप्रदेश का अधिनियम, राज्य गठन 2000 के बाद छत्तीसगढ़ में अनुकूलित)। अनुसूचित क्षेत्रों पर यह अध्याय 14-क के अपवादों सहित लागू है।</p>\n    <table>\n      <tr><th>धारा</th><th>प्रावधान</th></tr>\n      <tr><td>2</td><td>ग्राम सभा — ग्राम पंचायत क्षेत्र के राजस्व ग्राम या वन ग्राम की मतदाता सूची में दर्ज व्यक्ति; \"एक चक्रानुक्रम\" = लगातार दो आम चुनाव (2015 में जोड़ा)</td></tr>\n      <tr><td>3</td><td>राज्यपाल अधिसूचना द्वारा ग्राम/ग्रामों का समूह विनिर्दिष्ट करता है</td></tr>\n      <tr><td>6</td><td>ग्राम सभा की बैठक — <b>हर तीन माह में कम से कम एक</b>; 1/3 से अधिक सदस्यों की लिखित माँग या जनपद/ज़िला पंचायत/कलेक्टर के कहने पर 30 दिन में; गणपूर्ति (कोरम) <b>कुल सदस्यों का 1/10</b>, जिसमें कम से कम 1/3 महिलाएँ; अध्यक्षता सरपंच, अनुपस्थिति में उप-सरपंच; बैठक न बुलाने पर सरपंच अयोग्य</td></tr>\n      <tr><td>7</td><td>ग्राम सभा के कार्य — योजनाओं का अनुमोदन, हितग्राहियों का चयन, बजट पर विचार, अंकेक्षण प्रतिवेदन पर विचार, निधियों के उपयोग का प्रमाणन; <b>वार्षिक बैठक</b> अगले वित्तीय वर्ष के आरंभ से कम से कम 3 माह पहले</td></tr>\n      <tr><td>8</td><td>ग्राम हेतु ग्राम पंचायत, खंड (ब्लॉक) हेतु जनपद पंचायत, ज़िले हेतु ज़िला पंचायत</td></tr>\n      <tr><td>9</td><td>कार्यकाल 5 वर्ष (प्रथम बैठक की नियत तिथि से); विघटन पर 6 माह में चुनाव</td></tr>\n      <tr><td>10</td><td>राज्यपाल ज़िले को खंडों में बाँटता है; जनपद पंचायत का नाम खंड के नाम पर; नगर निगम/नगर पालिका/नगर पंचायत क्षेत्र अलग प्रशासनिक इकाई</td></tr>\n      <tr><td>12</td><td>ग्राम पंचायत में <b>कम से कम 10 वार्ड</b>; 1000 से अधिक जनसंख्या पर <b>अधिकतम 20</b>; वार्ड कलेक्टर निर्धारित करता है; प्रत्येक वार्ड एक-सदस्यीय</td></tr>\n      <tr><td>13</td><td>ग्राम पंचायत = निर्वाचित पंच + सरपंच; SC/ST आरक्षण जनसंख्या अनुपात में; <b>महिलाओं हेतु आधे पद</b> (C.G. अधिनियम 13, 2008 — 23 मई 2008 से \"एक-तिहाई\" के स्थान पर \"आधा\")</td></tr>\n      <tr><td>17</td><td>सरपंच — ग्राम पंचायत के मतदाताओं द्वारा प्रत्यक्ष; सांसद, विधायक, सहकारी समिति का अध्यक्ष/उपाध्यक्ष सरपंच नहीं बन सकता; सरपंच पदों का आरक्षण <b>खंड (ब्लॉक) स्तर</b> पर; उप-सरपंच निर्वाचित पंचों द्वारा; सरपंच SC/ST/OBC का न हो तो उप-सरपंच इन वर्गों से</td></tr>\n      <tr><td>20</td><td>ग्राम पंचायत की प्रथम बैठक निर्वाचन प्रकाशन से 30 दिन के भीतर</td></tr>\n      <tr><td>21</td><td>सरपंच/उप-सरपंच के विरुद्ध <b>अविश्वास प्रस्ताव</b> — उपस्थित व मत देने वाले पंचों का कम से कम <b>3/4</b> बहुमत, जो कुल पंचों के <b>2/3 से अधिक</b> हो; पद ग्रहण से 1 वर्ष तक, कार्यकाल के अंतिम 6 माह में, और पिछला प्रस्ताव गिरने से 1 वर्ष तक नहीं; विवाद 7 दिन में कलेक्टर को</td></tr>\n      <tr><td>21-क</td><td>सरपंच को <b>वापस बुलाना</b> — ग्राम सभा के कुल सदस्यों के आधे से अधिक बहुमत से गुप्त मतदान; प्रस्ताव पर कम से कम 1/3 सदस्यों के हस्ताक्षर; पद ग्रहण से ढाई वर्ष तक नहीं</td></tr>\n      <tr><td>22</td><td>जनपद पंचायत = निर्वाचित सदस्य + खंड से पूर्णतः/अंशतः जुड़े विधानसभा सदस्य + <b>1/5 सरपंच</b> (एक वर्ष हेतु लॉटरी से चक्रानुक्रम में)</td></tr>\n      <tr><td>23</td><td>जनपद निर्वाचन क्षेत्र — लगभग <b>5,000</b> जनसंख्या; 50,000 से कम जनसंख्या वाले खंड में कम से कम 10; अधिकतम <b>25</b></td></tr>\n      <tr><td>25</td><td>जनपद अध्यक्ष/उपाध्यक्ष — निर्वाचित सदस्यों द्वारा व उनमें से; अध्यक्ष पदों का आरक्षण <b>ज़िला स्तर</b> पर</td></tr>\n      <tr><td>28</td><td>जनपद अध्यक्ष के विरुद्ध अविश्वास — 3/4 (उपस्थित) व 2/3 से अधिक (कुल); विवाद 10 दिन में संचालक, पंचायत को</td></tr>\n      <tr><td>29</td><td>ज़िला पंचायत = निर्वाचित सदस्य + लोकसभा सदस्य + राज्यसभा सदस्य (जिनका नाम ज़िले की ग्राम पंचायत मतदाता सूची में हो) + विधायक + <b>सभी जनपद अध्यक्ष</b></td></tr>\n      <tr><td>30</td><td>ज़िला निर्वाचन क्षेत्र — लगभग <b>50,000</b> जनसंख्या; 5 लाख से कम जनसंख्या वाले ज़िले में कम से कम 10; अधिकतम <b>35</b></td></tr>\n      <tr><td>32</td><td>ज़िला पंचायत अध्यक्ष पदों का आरक्षण <b>राज्य स्तर</b> पर; अध्यक्ष निर्वाचित सदस्यों द्वारा</td></tr>\n      <tr><td>35</td><td>ज़िला अध्यक्ष के विरुद्ध अविश्वास — विवाद 15 दिन में राज्य सरकार को (45 दिन में निर्णय)</td></tr>\n      <tr><td>36</td><td>अयोग्यताएँ — दिवालिया, विकृत-चित्त, लाभ का पद, पंचायत से अनुबंध में हित, विदेशी नागरिकता आदि; 25 से कम आयु पर अयोग्य नहीं यदि 21 वर्ष पूर्ण; लगातार 3 बैठकों में अनुपस्थिति पर पद रिक्त; भू-राजस्व संहिता के अंतर्गत \"पटेल\" नियुक्त होना अयोग्यता नहीं</td></tr>\n      <tr><td>39</td><td>निलंबन — आदेश 10 दिन में राज्य सरकार को; 90 दिन में पुष्टि न होने पर निष्प्रभावी</td></tr>\n      <tr><td>40</td><td>पदाधिकारी को हटाना (कदाचार) — हटाया गया व्यक्ति <b>6 वर्ष</b> तक चुनाव हेतु अयोग्य</td></tr>\n      <tr><td>41</td><td>एक से अधिक पद पर चुने जाने पर 10 दिन में विकल्प; न देने पर वरीयता — ज़िला सदस्य &gt; जनपद सदस्य &gt; सरपंच &gt; पंच</td></tr>\n      <tr><td>42</td><td>पंचायत चुनाव व मतदाता सूची का अधीक्षण, निर्देशन, नियंत्रण — राज्य निर्वाचन आयोग</td></tr>\n      <tr><td>44</td><td>गणपूर्ति — ज़िला व जनपद पंचायत <b>1/3</b>, ग्राम पंचायत <b>1/2</b>; पंचायत की बैठक <b>प्रति माह कम से कम एक</b>; 50% से अधिक सदस्यों की माँग पर 7 दिन में विशेष बैठक</td></tr>\n      <tr><td>45</td><td>निपटाए गए विषय पर 6 माह में पुनर्विचार नहीं (जब तक 3/4 सदस्यों की सहमति न हो)</td></tr>\n      <tr><td>46</td><td>ग्राम पंचायत — <b>अधिकतम 5</b> स्थायी समितियाँ; एक व्यक्ति 2 से अधिक समितियों में नहीं; 2 विशेषज्ञ सहयोजित (मताधिकार नहीं)</td></tr>\n      <tr><td>47</td><td>जनपद व ज़िला पंचायत की <b>5 स्थायी समितियाँ</b> (नीचे तालिका)</td></tr>\n      <tr><td>69</td><td>ग्राम पंचायत सचिव (एक या अधिक ग्राम पंचायतों हेतु) — राज्य सरकार/विहित प्राधिकारी; जनपद व ज़िला पंचायत में मुख्य कार्यपालन अधिकारी (CEO) — राज्य सरकार द्वारा; सचिव किसी पदाधिकारी का संबंधी नहीं हो सकता</td></tr>\n      <tr><td>74</td><td>भू-राजस्व पर <b>उपकर</b> — प्रत्येक रुपये पर 50 पैसे; ज़िला पंचायत संकल्प द्वारा 10 रुपये तक बढ़ा सकती है</td></tr>\n      <tr><td>75</td><td>खंड के भीतर अचल संपत्ति के विक्रय, दान, बंधक पर स्टाम्प शुल्क में <b>1% अतिरिक्त</b></td></tr>\n      <tr><td>76</td><td>\"ज़िला पंचायत राज निधि\"; बढ़े हुए उपकर में से 25% जनपद, 25% ज़िला, 50% ग्राम पंचायत</td></tr>\n      <tr><td>77</td><td>अनुसूची I के अनिवार्य कर; अनुसूची II के वैकल्पिक कर; जनपद पंचायत कृषि भूमि पर <b>विकास कर</b> लगा सकती है</td></tr>\n      <tr><td>121–122</td><td>निर्वाचन मामलों में न्यायालय का हस्तक्षेप वर्जित; चुनाव याचिका</td></tr>\n      <tr><td>129</td><td>पंचायतों के लेखों की लेखा-परीक्षा हेतु पृथक व स्वतंत्र अंकेक्षण संगठन</td></tr>\n      <tr><td>129-क से 129-च</td><td>अध्याय 14-क — अनुसूचित क्षेत्रों की पंचायतों हेतु विशेष उपबंध (पेसा के अनुरूप)</td></tr>\n    </table>\n\n    <h4>जनपद व ज़िला पंचायत की स्थायी समितियाँ (धारा 47)</h4>\n    <table>\n      <tr><th>समिति</th><th>विषय</th><th>सभापति</th></tr>\n      <tr><td>सामान्य प्रशासन समिति</td><td>स्थापना, योजना, बजट, लेखा, कराधान</td><td>अध्यक्ष (पदेन); सभी स्थायी समितियों के सभापति इसके सदस्य</td></tr>\n      <tr><td>कृषि समिति</td><td>कृषि, पशुपालन, भू-संरक्षण, मत्स्य, बीज वितरण</td><td>सदस्यों में से निर्वाचित</td></tr>\n      <tr><td>शिक्षा समिति</td><td>शिक्षा, प्रौढ़ शिक्षा, महिला-बाल कल्याण, अस्पृश्यता निवारण, आपदा राहत, मद्य-निषेध, स्वास्थ्य</td><td>उपाध्यक्ष (पदेन); कम से कम एक महिला व एक SC/ST सदस्य अनिवार्य</td></tr>\n      <tr><td>संचार एवं संकर्म समिति</td><td>संचार, लघु सिंचाई, ग्रामीण आवास, ग्रामीण जल प्रदाय, लोक निर्माण</td><td>सदस्यों में से निर्वाचित</td></tr>\n      <tr><td>सहकारिता एवं उद्योग समिति</td><td>सहकारिता, लघु बचत, कुटीर व ग्रामोद्योग, बाज़ार, सांख्यिकी</td><td>सदस्यों में से निर्वाचित</td></tr>\n    </table>\n    <p>जनपद पंचायत का सदस्य विधायक उसकी प्रत्येक समिति का पदेन सदस्य; ज़िला पंचायत का सदस्य सांसद अपनी पसंद की दो समितियों का पदेन सदस्य। एक व्यक्ति सामान्य प्रशासन समिति के अतिरिक्त 3 से अधिक समितियों में नहीं।</p>\n\n    <h4>ग्राम पंचायत के कर (अनुसूची I-क — अनिवार्य)</h4>\n    <ul>\n      <li>भूमि/भवन पर संपत्ति कर (पूँजी मूल्य 6,000 रुपये से अधिक; शासकीय, धार्मिक व शैक्षणिक भवन मुक्त)</li>\n      <li>निजी शौचालयों पर कर (पंचायत द्वारा सफ़ाई होने पर), प्रकाश कर (प्रकाश व्यवस्था होने पर)</li>\n      <li>व्यवसाय/व्यापार पर कर, बाज़ार शुल्क, बाज़ार में बिके पशुओं के पंजीयन पर शुल्क</li>\n      <li>जनपद पंचायत का अनिवार्य कर (अनुसूची I-ख) — नाट्य प्रदर्शन व सार्वजनिक मनोरंजन पर कर</li>\n      <li>वैकल्पिक (अनुसूची II) — जल दर, जल-निकास शुल्क, पशुओं पर कर, बैलगाड़ी/साइकिल/रिक्शा पर कर, चराई शुल्क, विशेष लोकोपयोगी कार्यों हेतु अस्थायी कर</li>\n    </ul>\n\n    <h3>5. पेसा अधिनियम 1996 व अनुसूचित क्षेत्र</h3>\n    <p>पूरा नाम — पंचायत उपबंध (अनुसूचित क्षेत्रों पर विस्तार) अधिनियम, 1996 (अधिनियम सं. 40, 1996); 24 दिसंबर 1996 से लागू; 10 राज्यों के पाँचवीं अनुसूची क्षेत्रों पर। छत्तीसगढ़ ने इसके क्रियान्वयन हेतु <b>पेसा नियम, 2022</b> अधिसूचित किए।</p>\n    <table>\n      <tr><th>पेसा धारा 4 का प्रावधान</th><th>सार</th></tr>\n      <tr><td>4(a), 4(d)</td><td>राज्य विधि रूढ़िजन्य विधि, सामाजिक-धार्मिक प्रथाओं व सामुदायिक संसाधनों के पारंपरिक प्रबंधन के अनुरूप; ग्राम सभा परंपराओं, सांस्कृतिक पहचान व विवाद निपटान की रूढ़िगत रीति की रक्षा में सक्षम</td></tr>\n      <tr><td>4(b)</td><td>\"ग्राम\" = सामान्यतः एक बसाहट या बसाहटों का समूह, या एक टोला या टोलों का समूह जिसमें एक समुदाय रहता हो और परंपरा अनुसार कार्य चलाता हो</td></tr>\n      <tr><td>4(e), 4(f)</td><td>विकास योजनाओं का अनुमोदन व हितग्राहियों की पहचान ग्राम सभा द्वारा; निधि उपयोग का प्रमाणपत्र ग्राम सभा से</td></tr>\n      <tr><td>4(g)</td><td>ST आरक्षण कम से कम आधी सीटें; <b>सभी स्तरों पर अध्यक्ष पद ST हेतु</b></td></tr>\n      <tr><td>4(h)</td><td>मध्यवर्ती/ज़िला स्तर पर अप्रतिनिधित्व वाली जनजातियों का नामांकन — निर्वाचित सदस्यों के 1/10 से अधिक नहीं</td></tr>\n      <tr><td>4(i)</td><td>विकास परियोजनाओं हेतु भूमि अधिग्रहण व विस्थापितों के पुनर्वास से पहले परामर्श</td></tr>\n      <tr><td>4(j)</td><td>लघु जलाशयों का नियोजन व प्रबंधन उपयुक्त स्तर की पंचायत को</td></tr>\n      <tr><td>4(k), 4(l)</td><td>गौण खनिजों के पूर्वेक्षण अनुज्ञप्ति/खनन पट्टे व नीलामी द्वारा रियायत से पहले ग्राम सभा/पंचायत की सिफ़ारिश अनिवार्य</td></tr>\n      <tr><td>4(m)</td><td>मादक पदार्थों का निषेध/नियमन; लघु वनोपज का स्वामित्व; भूमि हस्तांतरण रोकना व अवैध हस्तांतरित भूमि वापस दिलाना; ग्राम बाज़ार प्रबंधन; ST को साहूकारी ऋण पर नियंत्रण; सामाजिक क्षेत्र की संस्थाओं व जनजातीय उप-योजना पर नियंत्रण</td></tr>\n      <tr><td>4(o)</td><td>ज़िला स्तर पर छठी अनुसूची के प्रतिरूप पर प्रशासनिक व्यवस्था का प्रयास</td></tr>\n    </table>\n    <h4>छत्तीसगढ़ पंचायत राज अधिनियम — अध्याय 14-क (अनुसूचित क्षेत्र)</h4>\n    <ul>\n      <li>ग्राम सभा की गणपूर्ति — कुल सदस्यों का <b>1/3</b> (सामान्य क्षेत्र में 1/10), जिसमें कम से कम 1/3 महिलाएँ</li>\n      <li>ग्राम सभा की अध्यक्षता — ग्राम सभा का <b>अनुसूचित जनजाति का सदस्य, जो सरपंच, उप-सरपंच या पंचायत सदस्य न हो</b></li>\n      <li>सभी स्तरों पर सरपंच/अध्यक्ष पद ST हेतु; ST सीटें कम से कम आधी; अप्रतिनिधित्व वाली जनजातियों का नामांकन ≤ 1/10</li>\n      <li>OBC आरक्षण इस प्रकार कि SC+ST+OBC मिलाकर कुल सीटों के 3/4 से अधिक न हो</li>\n      <li>जनपद/ज़िला पंचायत — निर्दिष्ट क्षेत्रफल तक के लघु जलाशयों का नियोजन, स्वामित्व व प्रबंधन</li>\n      <li>ग्राम सभा ग्राम बाज़ार व मेले (पशु मेले सहित) ग्राम पंचायत के माध्यम से प्रबंधित करती है</li>\n    </ul>\n    <h4>पाँचवीं अनुसूची (अनु. 244(1))</h4>\n    <ul>\n      <li>अनुसूचित क्षेत्र राष्ट्रपति आदेश द्वारा घोषित; छत्तीसगढ़ हेतु — अनुसूचित क्षेत्र (छत्तीसगढ़, झारखंड और मध्यप्रदेश राज्य) आदेश, 2003</li>\n      <li>राज्यपाल प्रतिवर्ष या राष्ट्रपति के माँगने पर अनुसूचित क्षेत्रों के प्रशासन की रिपोर्ट राष्ट्रपति को देता है</li>\n      <li>जनजाति सलाहकार परिषद — अधिकतम 20 सदस्य, लगभग 3/4 विधानसभा के ST सदस्य</li>\n      <li>राज्यपाल संसद/राज्य विधि को अनुसूचित क्षेत्र में लागू न होने या संशोधन सहित लागू होने का निर्देश दे सकता है; भूमि हस्तांतरण व साहूकारी पर विनियम बना सकता है (राष्ट्रपति की अनुमति से)</li>\n    </ul>\n\n    <h3>6. नगरीय निकाय — 74वाँ संशोधन (भाग IXक, अनु. 243P से 243ZG)</h3>\n    <table>\n      <tr><th>अनुच्छेद</th><th>विषय</th></tr>\n      <tr><td>243P</td><td>परिभाषाएँ; महानगर क्षेत्र = 10 लाख या अधिक जनसंख्या</td></tr>\n      <tr><td>243Q</td><td>नगर पंचायत (संक्रमणशील क्षेत्र), नगर पालिका परिषद (लघुतर नगरीय क्षेत्र), नगर निगम (वृहत्तर नगरीय क्षेत्र); औद्योगिक नगरी को छूट</td></tr>\n      <tr><td>243R</td><td>संरचना — प्रत्यक्ष निर्वाचन; विशेष ज्ञान वाले मनोनीत सदस्य (मताधिकार नहीं), सांसद/विधायक</td></tr>\n      <tr><td>243S</td><td>वार्ड समितियाँ — 3 लाख या अधिक जनसंख्या वाली नगरपालिका में</td></tr>\n      <tr><td>243T</td><td>आरक्षण — SC/ST, महिलाएँ कम से कम 1/3</td></tr>\n      <tr><td>243U</td><td>कार्यकाल 5 वर्ष</td></tr>\n      <tr><td>243W</td><td>शक्तियाँ — 12वीं अनुसूची (18 विषय)</td></tr>\n      <tr><td>243X / 243Y / 243Z</td><td>कर / वित्त आयोग / लेखा-परीक्षा</td></tr>\n      <tr><td>243ZA</td><td>नगरपालिकाओं के चुनाव — राज्य निर्वाचन आयोग</td></tr>\n      <tr><td>243ZD</td><td>ज़िला योजना समिति — कम से कम 4/5 सदस्य ज़िला पंचायत व नगरपालिकाओं के निर्वाचित सदस्यों द्वारा, ग्रामीण-नगरीय जनसंख्या के अनुपात में</td></tr>\n      <tr><td>243ZE</td><td>महानगर योजना समिति — कम से कम 2/3 सदस्य निर्वाचित</td></tr>\n    </table>\n    <p><b>12वीं अनुसूची (18 विषय):</b> नगर योजना; भूमि उपयोग व भवन निर्माण का विनियमन; आर्थिक-सामाजिक विकास योजना; सड़कें व पुल; जल प्रदाय; लोक स्वास्थ्य, स्वच्छता, ठोस अपशिष्ट; अग्निशमन; नगरीय वानिकी व पर्यावरण; कमज़ोर वर्गों के हितों की रक्षा; गंदी बस्ती सुधार; नगरीय गरीबी उन्मूलन; पार्क-उद्यान-खेल मैदान; सांस्कृतिक-शैक्षिक-सौंदर्यपरक पहलू; अंत्येष्टि, कब्रिस्तान, विद्युत शवदाह गृह; कांजी हाउस व पशु-क्रूरता निवारण; जन्म-मृत्यु पंजीकरण; मार्ग-प्रकाश, पार्किंग, बस स्टॉप; वधशालाओं व चर्मशोधनशालाओं का विनियमन।</p>\n\n    <h3>7. छत्तीसगढ़ नगर पालिक निगम अधिनियम, 1956 व नगर पालिका अधिनियम, 1961</h3>\n    <table>\n      <tr><th>विषय</th><th>नगर पालिक निगम अधिनियम 1956 (अधिनियम सं. 23, 1956)</th></tr>\n      <tr><td>गठन</td><td>\"वृहत्तर नगरीय क्षेत्र\" — राज्यपाल अधिसूचना द्वारा (जनसंख्या, घनत्व, राजस्व, गैर-कृषि रोज़गार आदि के आधार पर)</td></tr>\n      <tr><td>संरचना</td><td>प्रत्यक्ष निर्वाचित महापौर + वार्डों से निर्वाचित पार्षद + राज्य सरकार द्वारा मनोनीत (वार्डों की संख्या के 15% तक, नगर प्रशासन के विशेष ज्ञान वाले) + सांसद/विधायक; मनोनीत व सांसद/विधायक को निगम की बैठकों में मताधिकार नहीं</td></tr>\n      <tr><td>वार्ड</td><td>न्यूनतम 40, अधिकतम 70; प्रत्येक वार्ड से एक पार्षद</td></tr>\n      <tr><td>आयु</td><td>महापौर हेतु न्यूनतम <b>25 वर्ष</b>; पार्षद हेतु <b>21 वर्ष</b></td></tr>\n      <tr><td>महापौर पद आरक्षण</td><td>राज्य के सभी नगर निगमों को मिलाकर, निगम क्षेत्रों की SC/ST जनसंख्या अनुपात में; लगभग 50% महिलाओं हेतु</td></tr>\n      <tr><td>सभापति (Speaker)</td><td>महापौर व निर्वाचित पार्षद, निर्वाचन अधिसूचना के 15 दिन में, निर्वाचित पार्षदों में से चुनते हैं; बैठक कलेक्टर बुलाता व अध्यक्षता करता है; सभापति निगम की बैठकों की अध्यक्षता करता है</td></tr>\n      <tr><td>सभापति पर अविश्वास</td><td>उपस्थित व मत देने वाले निर्वाचित पार्षदों का 2/3 बहुमत, जो कुल का आधे से अधिक हो; पद ग्रहण से 2 वर्ष तक नहीं; गुप्त मतदान; बैठक कलेक्टर बुलाता है</td></tr>\n      <tr><td>महापौर को वापस बुलाना</td><td>कम से कम 3/4 निर्वाचित पार्षदों के हस्ताक्षर से प्रस्ताव संभागायुक्त को; पद ग्रहण से 2 वर्ष तक नहीं; पूरे कार्यकाल में एक बार; निगम क्षेत्र के मतदाता गुप्त मतदान से (डाले गए मतों का आधे से अधिक) — मतदान राज्य निर्वाचन आयोग कराता है</td></tr>\n      <tr><td>महापौर-परिषद (Mayor-in-Council)</td><td>महापौर + <b>कम से कम 5, अधिकतम 10</b> सदस्य — सभी महापौर द्वारा निर्वाचित पार्षदों में से मनोनीत; कम से कम एक SC/ST, एक OBC, एक महिला; सभापति के चुनाव के 7 दिन में गठन; सदस्य महापौर के प्रसादपर्यंत; महापौर पदेन अध्यक्ष; गणपूर्ति आधे सदस्य</td></tr>\n      <tr><td>वार्ड समितियाँ</td><td>3 लाख या अधिक जनसंख्या वाले निगम में अनिवार्य; संख्या = जनसंख्या ÷ 1 लाख; सभापति के चुनाव से 30 दिन में; प्रत्येक वार्ड समिति में संबंधित पार्षद + महापौर द्वारा मनोनीत 2 निवासी (मताधिकार नहीं); इसके अतिरिक्त मोहल्ला समितियाँ</td></tr>\n      <tr><td>आयुक्त</td><td>राज्य सरकार द्वारा अधिकतम 5 वर्ष (नवीकरणीय) हेतु; निगम का प्रधान कार्यपालक अधिकारी; बैठक में बोल सकता है पर मत नहीं दे सकता; कुल निर्वाचित पार्षदों के 3/4 के मत से हटाया जा सकता है</td></tr>\n      <tr><td>पार्षद को हटाना</td><td>संभागायुक्त; महापौर/सभापति को हटाना — राज्य सरकार; महापौर अपना त्यागपत्र राज्य सरकार को देता है</td></tr>\n    </table>\n    <p><b>नगर पालिका अधिनियम, 1961 (अधिनियम सं. 37, 1961):</b> नगर पालिका परिषद (लघुतर नगरीय क्षेत्र) और नगर पंचायत (संक्रमणशील क्षेत्र) का संचालन; निर्वाचित प्रमुख <b>अध्यक्ष</b>; कार्यकारी निकाय <b>अध्यक्ष-परिषद (President-in-Council)</b>; प्रशासनिक प्रमुख <b>मुख्य नगर पालिका अधिकारी (CMO)</b>। महापौर-परिषद/अध्यक्ष-परिषद के कार्य-संचालन हेतु नियम, 1998।</p>\n\n    <h3>8. महापौर/अध्यक्ष का निर्वाचन — छत्तीसगढ़ का क्रम</h3>\n    <table>\n      <tr><th>नगरीय निकाय आम चुनाव</th><th>महापौर/अध्यक्ष का चुनाव</th></tr>\n      <tr><td>दिसंबर 2004 (राज्य गठन के बाद प्रथम)</td><td>प्रत्यक्ष (जनता द्वारा)</td></tr>\n      <tr><td>दिसंबर 2009</td><td>प्रत्यक्ष</td></tr>\n      <tr><td>दिसंबर 2014</td><td>प्रत्यक्ष</td></tr>\n      <tr><td>दिसंबर 2019</td><td><b>अप्रत्यक्ष</b> — 2019 के संशोधन से पार्षदों द्वारा अपने में से</td></tr>\n      <tr><td>फ़रवरी 2025</td><td>पुनः <b>प्रत्यक्ष</b> — दिसंबर 2024 के अध्यादेश से नगर पालिक निगम अधिनियम 1956 व नगर पालिका अधिनियम 1961 में संशोधन; नगरीय निकायों का मतदान 11 फ़रवरी 2025 (एक चरण), त्रिस्तरीय पंचायत चुनाव 17, 20, 23 फ़रवरी 2025 (तीन चरण)</td></tr>\n    </table>\n    <p>पंचायत आम चुनाव (राज्य गठन के बाद): 2005 (प्रथम), 2010, 2015, 2020 (जनवरी–फ़रवरी), 2025। पंचायत चुनाव दलीय चुनाव-चिह्न पर नहीं होते, जबकि नगरीय निकाय चुनाव दलीय आधार पर होते हैं।</p>\n\n    <h3>9. राज्य निर्वाचन आयोग व राज्य वित्त आयोग</h3>\n    <table>\n      <tr><th>बिंदु</th><th>राज्य निर्वाचन आयोग</th><th>राज्य वित्त आयोग</th></tr>\n      <tr><td>अनुच्छेद</td><td>243K (पंचायत), 243ZA (नगरपालिका)</td><td>243I (पंचायत), 243Y (नगरपालिका)</td></tr>\n      <tr><td>गठन/नियुक्ति</td><td>राज्यपाल द्वारा राज्य निर्वाचन आयुक्त</td><td>राज्यपाल द्वारा, प्रत्येक 5 वर्ष पर</td></tr>\n      <tr><td>हटाना/रिपोर्ट</td><td>उच्च न्यायालय के न्यायाधीश की रीति और आधारों पर ही; नियुक्ति के बाद सेवा-शर्तें अलाभकारी नहीं की जा सकतीं</td><td>राज्यपाल रिपोर्ट व की गई कार्रवाई का ज्ञापन विधानमंडल के समक्ष रखवाता है</td></tr>\n      <tr><td>कार्य</td><td>मतदाता सूची तैयार कराना व चुनावों का अधीक्षण, निर्देशन, नियंत्रण</td><td>राज्य व स्थानीय निकायों में करों का बँटवारा, अनुदान, वित्तीय स्थिति सुधार के उपाय</td></tr>\n    </table>\n    <p>अनु. 280(3)(bb) व (c) — केंद्रीय वित्त आयोग राज्य वित्त आयोग की सिफ़ारिशों के आधार पर पंचायतों/नगरपालिकाओं के संसाधन बढ़ाने हेतु राज्य की संचित निधि बढ़ाने के उपाय सुझाता है।</p>\n\n    <h3>10. ग्रामीण विकास योजनाएँ (स्थिर तथ्य)</h3>\n    <table>\n      <tr><th>योजना</th><th>आरंभ</th><th>तथ्य</th></tr>\n      <tr><td>प्रधानमंत्री ग्राम सड़क योजना</td><td>25 दिसंबर 2000</td><td>असंबद्ध बसाहटों को बारहमासी सड़क</td></tr>\n      <tr><td>राष्ट्रीय ग्रामीण रोज़गार गारंटी अधिनियम</td><td>अधिनियम 2005; 2 फ़रवरी 2006 से (अनंतपुर, आंध्र प्रदेश)</td><td>2 अक्टूबर 2009 से \"महात्मा गांधी\" नाम जुड़ा; मूल अधिनियम में प्रति परिवार 100 दिन रोज़गार की गारंटी</td></tr>\n      <tr><td>राष्ट्रीय ग्रामीण आजीविका मिशन</td><td>जून 2011</td><td>छत्तीसगढ़ में नाम \"बिहान\"; स्व-सहायता समूह आधारित</td></tr>\n      <tr><td>दीनदयाल उपाध्याय ग्रामीण कौशल्य योजना</td><td>25 सितंबर 2014</td><td>ग्रामीण युवाओं का कौशल व प्लेसमेंट</td></tr>\n      <tr><td>सांसद आदर्श ग्राम योजना</td><td>11 अक्टूबर 2014</td><td>जयप्रकाश नारायण जयंती पर</td></tr>\n      <tr><td>स्वच्छ भारत मिशन (ग्रामीण)</td><td>2 अक्टूबर 2014</td><td>खुले में शौच मुक्त गाँव</td></tr>\n      <tr><td>श्यामा प्रसाद मुखर्जी रूर्बन मिशन</td><td>21 फ़रवरी 2016</td><td>कुरुभाट (राजनांदगाँव ज़िला, छत्तीसगढ़) से शुभारंभ</td></tr>\n      <tr><td>प्रधानमंत्री आवास योजना — ग्रामीण</td><td>1 अप्रैल 2016 से प्रभावी (शुभारंभ 20 नवंबर 2016, आगरा)</td><td>पूर्ववर्ती इंदिरा आवास योजना का पुनर्गठन</td></tr>\n      <tr><td>जल जीवन मिशन</td><td>15 अगस्त 2019</td><td>हर घर नल से जल</td></tr>\n      <tr><td>स्वामित्व योजना व ई-ग्राम स्वराज</td><td>24 अप्रैल 2020</td><td>ड्रोन से ग्रामीण आबादी भूमि का सर्वेक्षण व संपत्ति कार्ड</td></tr>\n    </table>\n  ",
  extra: "\n    <h3>गहन तथ्य — जो सामान्य पाठक नहीं जानता</h3>\n    <ul>\n      <li><b>तीन अलग गणपूर्तियाँ:</b> सामान्य ग्राम सभा 1/10 (उसमें 1/3 महिलाएँ); अनुसूचित क्षेत्र की ग्राम सभा 1/3 (उसमें 1/3 महिलाएँ); ग्राम पंचायत की बैठक 1/2; जनपद व ज़िला पंचायत की बैठक 1/3; महापौर-परिषद 1/2।</li>\n      <li><b>ग्राम सभा की अध्यक्षता:</b> सामान्य क्षेत्र में सरपंच (फिर उप-सरपंच); अनुसूचित क्षेत्र में ST सदस्य जो सरपंच/उप-सरपंच/पंच न हो — यह पेसा की \"पारंपरिक नेतृत्व\" भावना है।</li>\n      <li><b>आरक्षण की इकाई तीन स्तर पर:</b> सरपंच पद — खंड (ब्लॉक) स्तर पर; जनपद अध्यक्ष पद — ज़िला स्तर पर; ज़िला पंचायत अध्यक्ष पद — राज्य स्तर पर; महापौर पद — सभी नगर निगमों को मिलाकर राज्य स्तर पर।</li>\n      <li><b>अविश्वास प्रस्ताव का दोहरा बहुमत:</b> पंचायत के तीनों स्तरों पर \"उपस्थित व मत देने वालों का 3/4\" और \"कुल का 2/3 से अधिक\" — दोनों शर्तें। जबकि नगर निगम सभापति पर \"उपस्थित का 2/3\" और \"कुल का आधे से अधिक\"।</li>\n      <li><b>अविश्वास विवाद किसके पास:</b> सरपंच — 7 दिन में कलेक्टर; जनपद अध्यक्ष — 10 दिन में संचालक पंचायत; ज़िला अध्यक्ष — 15 दिन में राज्य सरकार (7-10-15 का क्रम याद रखें)।</li>\n      <li><b>निर्वाचन क्षेत्र का गणित:</b> ग्राम पंचायत 10–20 वार्ड; जनपद ~5,000 जनसंख्या पर एक, अधिकतम 25; ज़िला ~50,000 पर एक, अधिकतम 35; नगर निगम 40–70 वार्ड। (10-20, 25, 35, 40-70)</li>\n      <li><b>पदेन सदस्य:</b> जनपद पंचायत में विधायक और 1/5 सरपंच (एक वर्ष, लॉटरी से; एक बार सदस्य रहा सरपंच दोबारा नहीं); ज़िला पंचायत में सांसद (लोकसभा व राज्यसभा), विधायक और सभी जनपद अध्यक्ष। जो विधायक/सांसद का निर्वाचन क्षेत्र पूर्णतः नगरीय हो, वे सदस्य नहीं।</li>\n      <li><b>सरपंच स्वयं पंच माना जाता है</b> (धारा 17(8)); सरपंच बनते ही यदि कोई विधायक/सांसद या सहकारी समिति अध्यक्ष बन जाए तो पद स्वतः रिक्त।</li>\n      <li><b>\"एक चक्रानुक्रम\" (rotation):</b> लगातार दो आम चुनाव — अर्थात आरक्षित सीट सामान्यतः दो चुनावों तक उसी वर्ग में रहती है; परिसीमन के बाद का चुनाव पहला माना जाता है।</li>\n      <li><b>छत्तीसगढ़ में महिलाओं को 50%:</b> 2008 के संशोधन (23 मई 2008 से) से पंचायतों में \"एक-तिहाई\" के स्थान पर \"आधा\"। देश में पंचायतों में 50% महिला आरक्षण देने वाला पहला राज्य बिहार (2006) था।</li>\n      <li><b>पंचायत की आय के अनोखे स्रोत:</b> भू-राजस्व पर 50 पैसे प्रति रुपया उपकर; खंड के भीतर अचल संपत्ति के हस्तांतरण पर 1% अतिरिक्त स्टाम्प शुल्क (जनपद पंचायतों को अनुदान रूप में); जनपद पंचायत द्वारा कृषि भूमि पर विकास कर; जनपद का अनिवार्य कर — मनोरंजन/नाट्य प्रदर्शन कर।</li>\n      <li><b>शिक्षा समिति का विशेष नियम:</b> सभापति पदेन उपाध्यक्ष; कम से कम एक महिला और एक SC/ST सदस्य अनिवार्य। सामान्य प्रशासन समिति के सभापति पदेन अध्यक्ष और उसमें सभी समितियों के सभापति।</li>\n      <li><b>महापौर बनाम सभापति:</b> महापौर कार्यपालिका (महापौर-परिषद) का प्रमुख; सभापति निगम की सामान्य सभा की बैठकों का पीठासीन अधिकारी — विधानसभा अध्यक्ष जैसी भूमिका। आयुक्त प्रशासनिक प्रमुख।</li>\n      <li><b>वापस बुलाने (Recall) की तुलना:</b> सरपंच — ग्राम सभा के कुल सदस्यों का आधे से अधिक, ढाई वर्ष बाद; महापौर — 3/4 पार्षदों का प्रस्ताव, फिर निगम क्षेत्र के मतदाताओं का मतदान, 2 वर्ष बाद, कार्यकाल में केवल एक बार।</li>\n      <li><b>पेसा बनाम छठी अनुसूची:</b> छठी अनुसूची (असम, मेघालय, त्रिपुरा, मिज़ोरम) में स्वायत्त ज़िला परिषदें; पेसा पाँचवीं अनुसूची क्षेत्रों में ग्राम सभा-केंद्रित स्वशासन। पेसा धारा 4(o) ज़िला स्तर पर छठी अनुसूची जैसा ढाँचा अपनाने का प्रयास कहती है।</li>\n      <li><b>243M की छूट:</b> भाग IX अनुसूचित क्षेत्रों पर स्वतः लागू नहीं — इसलिए संसद ने 1996 में पेसा द्वारा उसे \"विस्तार\" दिया; इसीलिए नाम \"पंचायत उपबंध (अनुसूचित क्षेत्रों पर विस्तार)\"।</li>\n      <li><b>ज़िला योजना समिति (243ZD)</b> भाग IXक (74वाँ संशोधन) में है, भाग IX में नहीं — यद्यपि यह ग्रामीण व नगरीय दोनों योजनाओं को समेकित करती है।</li>\n      <li><b>श्यामा प्रसाद मुखर्जी रूर्बन मिशन</b> का राष्ट्रीय शुभारंभ छत्तीसगढ़ के कुरुभाट (राजनांदगाँव) से 21 फ़रवरी 2016 को हुआ — राज्य से जुड़ा महत्त्वपूर्ण स्थिर तथ्य।</li>\n    </ul>\n    <div class=\"tip\">ट्रिक \"सा-कृ-शि-सं-स\": जनपद/ज़िला पंचायत की पाँच स्थायी समितियाँ — <b>सा</b>मान्य प्रशासन, <b>कृ</b>षि, <b>शि</b>क्षा, <b>सं</b>चार-संकर्म, <b>स</b>हकारिता-उद्योग।</div>\n  ",
  questions: [
    {"q":"छत्तीसगढ़ पंचायत राज अधिनियम के अनुसार सामान्य (गैर-अनुसूचित) क्षेत्र में ग्राम सभा की बैठक की गणपूर्ति (कोरम) कितनी है?","o":["कुल सदस्यों का 1/3","कुल सदस्यों का 1/10","कुल सदस्यों का 1/2","कुल सदस्यों का 1/5"],"a":1,"e":"धारा 6(2) — कुल सदस्यों का कम से कम 1/10, जिसमें कम से कम 1/3 महिलाएँ हों। अनुसूचित क्षेत्र की ग्राम सभा में कोरम 1/3 है।"},
    {"q":"छत्तीसगढ़ में ग्राम सभा की बैठक कम से कम कितने अंतराल पर आयोजित होना अनिवार्य है?","o":["हर माह","हर छह माह","हर तीन माह","वर्ष में एक बार"],"a":2,"e":"धारा 6(1) — प्रत्येक तीन माह में कम से कम एक बैठक। ग्राम पंचायत की बैठक प्रति माह कम से कम एक बार होती है (धारा 44)।"},
    {"q":"छत्तीसगढ़ पंचायत राज अधिनियम के अनुसार ग्राम पंचायत क्षेत्र को न्यूनतम कितने वार्डों में बाँटा जाता है?","o":["5","8","15","10"],"a":3,"e":"धारा 12 — कम से कम 10 वार्ड; 1000 से अधिक जनसंख्या होने पर भी वार्डों की संख्या 20 से अधिक नहीं। वार्ड कलेक्टर निर्धारित करता है।"},
    {"q":"छत्तीसगढ़ में किसी ग्राम पंचायत में वार्डों की अधिकतम संख्या कितनी हो सकती है?","o":["20","25","15","30"],"a":0,"e":"धारा 12 के परंतुक के अनुसार वार्ड 20 से अधिक नहीं होंगे। प्रत्येक वार्ड एक-सदस्यीय होता है।"},
    {"q":"ग्राम पंचायत के वार्डों का निर्धारण कौन करता है?","o":["राज्य निर्वाचन आयोग","कलेक्टर","जनपद पंचायत CEO","ग्राम सभा"],"a":1,"e":"धारा 12 — वार्डों की संख्या कलेक्टर निर्धारित करता है। चुनाव कराने का कार्य राज्य निर्वाचन आयोग का है।"},
    {"q":"छत्तीसगढ़ में सरपंच के विरुद्ध अविश्वास प्रस्ताव पारित होने के लिए उपस्थित एवं मत देने वाले पंचों का न्यूनतम कितना बहुमत आवश्यक है?","o":["साधारण बहुमत","दो-तिहाई","तीन-चौथाई","चार-पाँचवाँ"],"a":2,"e":"धारा 21 — उपस्थित व मत देने वालों का कम से कम 3/4, और यह बहुमत कुल पंचों के 2/3 से अधिक होना चाहिए।"},
    {"q":"सरपंच के विरुद्ध अविश्वास प्रस्ताव, सरपंच के पद ग्रहण करने की तिथि से कितनी अवधि तक नहीं लाया जा सकता?","o":["छह माह","दो वर्ष","ढाई वर्ष","एक वर्ष"],"a":3,"e":"धारा 21(3) — पद ग्रहण से 1 वर्ष तक, कार्यकाल के अंतिम 6 माह में और पिछला प्रस्ताव अस्वीकृत होने से 1 वर्ष तक अविश्वास प्रस्ताव नहीं।"},
    {"q":"सरपंच के विरुद्ध पारित अविश्वास प्रस्ताव की वैधता को चुनौती देने के लिए विवाद किसे भेजा जाता है?","o":["कलेक्टर","राज्य निर्वाचन आयोग","उच्च न्यायालय","संचालक, पंचायत"],"a":0,"e":"धारा 21(4) — 7 दिन के भीतर कलेक्टर को; कलेक्टर यथासंभव 30 दिन में निर्णय देता है और उसका निर्णय अंतिम होता है।"},
    {"q":"छत्तीसगढ़ में जनपद पंचायत के लिए प्रत्येक निर्वाचन क्षेत्र की जनसंख्या यथासंभव लगभग कितनी रखी जाती है?","o":["1,000","5,000","10,000","50,000"],"a":1,"e":"धारा 23 — लगभग 5,000 जनसंख्या पर एक निर्वाचन क्षेत्र; एक खंड में अधिकतम 25 निर्वाचन क्षेत्र। ज़िला पंचायत में लगभग 50,000 पर एक।"},
    {"q":"एक जनपद पंचायत में निर्वाचन क्षेत्रों की अधिकतम संख्या कितनी हो सकती है?","o":["20","35","25","40"],"a":2,"e":"धारा 23 — अधिकतम 25; 50,000 से कम जनसंख्या वाले खंड में कम से कम 10। ज़िला पंचायत में अधिकतम 35।"},
    {"q":"एक ज़िला पंचायत में निर्वाचन क्षेत्रों की अधिकतम संख्या कितनी हो सकती है?","o":["25","50","30","35"],"a":3,"e":"धारा 30 — प्रत्येक निर्वाचन क्षेत्र लगभग 50,000 जनसंख्या का; कुल 35 से अधिक नहीं; 5 लाख से कम जनसंख्या वाले ज़िले में कम से कम 10।"},
    {"q":"छत्तीसगढ़ में जनपद पंचायत में सरपंचों का प्रतिनिधित्व किस प्रकार होता है?","o":["1/5 सरपंच, एक वर्ष हेतु लॉटरी द्वारा चक्रानुक्रम से","सभी सरपंच पदेन सदस्य","1/3 सरपंच, पाँच वर्ष हेतु","सरपंचों का कोई प्रतिनिधित्व नहीं"],"a":0,"e":"धारा 22(1)(iv) — खंड के 1/5 सरपंच, एक वर्ष के लिए लॉटरी से; एक बार सदस्य रहा सरपंच दोबारा पात्र नहीं और वह धारा 47 की समितियों का सदस्य नहीं बनता।"},
    {"q":"छत्तीसगढ़ में ज़िला पंचायत का सदस्य निम्न में से कौन पदेन होता है?","o":["सभी सरपंच","ज़िले के सभी जनपद पंचायत अध्यक्ष","ज़िले के सभी नगर निगम महापौर","ज़िला कलेक्टर"],"a":1,"e":"धारा 29 — ज़िले के सभी जनपद अध्यक्ष, लोकसभा व राज्यसभा सदस्य (शर्तों सहित) और विधायक ज़िला पंचायत के सदस्य होते हैं; जनपद अध्यक्ष धारा 47 की समितियों के सदस्य नहीं होते।"},
    {"q":"छत्तीसगढ़ में सरपंच पदों का आरक्षण (SC/ST) किस इकाई की जनसंख्या के अनुपात में निर्धारित होता है?","o":["ग्राम पंचायत","ज़िला","खंड (ब्लॉक)","संपूर्ण राज्य"],"a":2,"e":"धारा 17(2) — खंड में SC/ST जनसंख्या के अनुपात में खंड के सरपंच पद आरक्षित। जनपद अध्यक्ष पद ज़िला स्तर पर और ज़िला अध्यक्ष पद राज्य स्तर पर आरक्षित होते हैं।"},
    {"q":"छत्तीसगढ़ में ज़िला पंचायत अध्यक्ष के पदों का आरक्षण किस स्तर पर किया जाता है?","o":["खंड स्तर","संभाग स्तर","ज़िला स्तर","राज्य स्तर"],"a":3,"e":"धारा 32 — राज्य की SC/ST जनसंख्या के अनुपात में राज्य के ज़िला पंचायत अध्यक्ष पद आरक्षित; कम से कम आधे पद महिलाओं हेतु।"},
    {"q":"छत्तीसगढ़ पंचायत राज अधिनियम में महिलाओं हेतु आरक्षण \"एक-तिहाई\" से बढ़ाकर \"आधा\" किस वर्ष के संशोधन से किया गया?","o":["2008","2000","2004","2015"],"a":0,"e":"C.G. अधिनियम क्र. 13, 2008 (23 मई 2008 से) द्वारा धारा 13, 17, 23, 25, 30, 32 में \"एक-तिहाई\" के स्थान पर \"आधा\" किया गया।"},
    {"q":"छत्तीसगढ़ पंचायत राज अधिनियम में \"एक चक्रानुक्रम\" (one rotation) से क्या अभिप्रेत है?","o":["एक आम चुनाव","लगातार दो आम चुनाव","लगातार तीन आम चुनाव","दस वर्ष या दो उपचुनाव"],"a":1,"e":"धारा 2(xiii-a) (2015 में जोड़ी गई) — लगातार दो आम चुनाव एक चक्रानुक्रम हैं; परिसीमन के बाद का चुनाव पहला माना जाता है।"},
    {"q":"छत्तीसगढ़ में उप-सरपंच के निर्वाचन के संबंध में सही कथन कौन-सा है?","o":["ग्राम सभा द्वारा प्रत्यक्ष","सरपंच द्वारा मनोनीत","यदि सरपंच SC/ST/OBC का न हो तो उप-सरपंच इन वर्गों के पंचों में से चुना जाता है","जनपद पंचायत द्वारा नियुक्त"],"a":2,"e":"धारा 17(5), (6) — उप-सरपंच निर्वाचित सदस्यों द्वारा अपने में से चुना जाता है; सरपंच इन वर्गों का न हो तो उप-सरपंच SC/ST/OBC पंचों में से।"},
    {"q":"छत्तीसगढ़ में निम्न में से कौन सरपंच निर्वाचित होने के लिए पात्र नहीं है?","o":["21 वर्ष का मतदाता","महिला पंच","भू-राजस्व संहिता के अंतर्गत नियुक्त पटेल","सहकारी समिति का अध्यक्ष"],"a":3,"e":"धारा 17(1) — सांसद, विधायक तथा सहकारी समिति के अध्यक्ष/उपाध्यक्ष सरपंच नहीं बन सकते। पटेल नियुक्त होना धारा 36 के अंतर्गत अयोग्यता नहीं है।"},
    {"q":"छत्तीसगढ़ पंचायत राज अधिनियम के अनुसार ग्राम पंचायत की बैठक की गणपूर्ति कितनी है?","o":["कुल सदस्यों का 1/2","कुल सदस्यों का 1/3","कुल सदस्यों का 1/10","कुल सदस्यों का 2/3"],"a":0,"e":"धारा 44(3) — ग्राम पंचायत 1/2; जनपद व ज़िला पंचायत 1/3। ग्राम सभा का कोरम 1/10 है।"},
    {"q":"जनपद पंचायत की बैठक की गणपूर्ति कितनी है?","o":["1/2","1/3","1/4","1/10"],"a":1,"e":"धारा 44(3) — ज़िला पंचायत व जनपद पंचायत की बैठक की गणपूर्ति 1/3 सदस्य।"},
    {"q":"छत्तीसगढ़ में ग्राम पंचायत अधिकतम कितनी स्थायी समितियाँ गठित कर सकती है?","o":["तीन","सात","पाँच","दस"],"a":2,"e":"धारा 46 (2004 के संशोधन के बाद) — अधिकतम पाँच; कोई व्यक्ति दो से अधिक समितियों का सदस्य नहीं; दो विशेषज्ञ सहयोजित किए जा सकते हैं जिन्हें मताधिकार नहीं।"},
    {"q":"जनपद पंचायत और ज़िला पंचायत की सामान्य प्रशासन समिति का पदेन सभापति कौन होता है?","o":["मुख्य कार्यपालन अधिकारी","उपाध्यक्ष","कलेक्टर","अध्यक्ष"],"a":3,"e":"धारा 47(5) — अध्यक्ष सामान्य प्रशासन समिति का और उपाध्यक्ष शिक्षा समिति का पदेन सभापति होता है।"},
    {"q":"जनपद/ज़िला पंचायत की शिक्षा समिति का पदेन सभापति कौन होता है?","o":["उपाध्यक्ष","अध्यक्ष","ज़िला शिक्षा अधिकारी","सदस्यों द्वारा निर्वाचित"],"a":0,"e":"धारा 47(5)(ii) — उपाध्यक्ष। शिक्षा समिति में कम से कम एक महिला और एक SC/ST सदस्य होना अनिवार्य है।"},
    {"q":"निम्नलिखित में से कौन-सी जनपद/ज़िला पंचायत की धारा 47 में वर्णित स्थायी समिति नहीं है?","o":["कृषि समिति","वित्त एवं अंकेक्षण समिति","संचार एवं संकर्म समिति","सहकारिता एवं उद्योग समिति"],"a":1,"e":"पाँच स्थायी समितियाँ — सामान्य प्रशासन, कृषि, शिक्षा, संचार एवं संकर्म, सहकारिता एवं उद्योग। बजट/लेखा सामान्य प्रशासन समिति के अंतर्गत आते हैं।"},
    {"q":"छत्तीसगढ़ में ग्राम पंचायत सचिव की नियुक्ति कौन करता है?","o":["सरपंच","ग्राम सभा","राज्य सरकार या विहित प्राधिकारी","राज्य लोक सेवा आयोग"],"a":2,"e":"धारा 69(1) — राज्य सरकार या विहित प्राधिकारी एक ग्राम पंचायत या दो-अधिक ग्राम पंचायतों के समूह हेतु सचिव नियुक्त कर सकता है; सचिव किसी पदाधिकारी का संबंधी नहीं हो सकता।"},
    {"q":"छत्तीसगढ़ पंचायत राज अधिनियम के अनुसार भू-राजस्व पर पंचायत उपकर की मूल दर क्या है?","o":["प्रत्येक रुपये पर 10 पैसे","प्रत्येक रुपये पर 25 पैसे","प्रत्येक रुपये पर 1 रुपया","प्रत्येक रुपये पर 50 पैसे"],"a":3,"e":"धारा 74 — प्रत्येक रुपये पर 50 पैसे; ज़िला पंचायत संकल्प द्वारा इसे 10 रुपये तक बढ़ा सकती है।"},
    {"q":"खंड (ब्लॉक) के भीतर अचल संपत्ति के विक्रय, दान या बंधक पर पंचायतों के लिए स्टाम्प शुल्क में कितनी वृद्धि का प्रावधान है?","o":["1 प्रतिशत","2 प्रतिशत","0.5 प्रतिशत","5 प्रतिशत"],"a":0,"e":"धारा 75 — भारतीय स्टाम्प अधिनियम 1899 के शुल्क में संपत्ति मूल्य का 1% अतिरिक्त; यह राशि जनपद पंचायतों को अनुदान के रूप में दी जाती है।"},
    {"q":"छत्तीसगढ़ में कृषि भूमि पर \"विकास कर\" लगाने की शक्ति किस संस्था को है?","o":["ग्राम पंचायत","जनपद पंचायत","ज़िला पंचायत","नगर पंचायत"],"a":1,"e":"धारा 77(3) — जनपद पंचायत कृषि भूमि पर विकास कर लगा सकती है, जो भू-राजस्व की भाँति वसूल होता है।"},
    {"q":"छत्तीसगढ़ पंचायत राज अधिनियम की अनुसूची I के अनुसार निम्न में से कौन-सा कर ग्राम पंचायत का अनिवार्य कर है?","o":["जल दर","चराई शुल्क","प्रकाश कर (प्रकाश व्यवस्था होने पर)","पशुओं पर कर"],"a":2,"e":"अनुसूची I-क के अनिवार्य कर — संपत्ति कर, निजी शौचालय कर, प्रकाश कर, व्यवसाय कर, बाज़ार शुल्क, पशु पंजीयन शुल्क। जल दर, चराई शुल्क, पशु कर वैकल्पिक (अनुसूची II) हैं।"},
    {"q":"छत्तीसगढ़ पंचायत राज अधिनियम के अनुसार जनपद पंचायत का अनिवार्य कर कौन-सा है?","o":["संपत्ति कर","व्यवसाय कर","बाज़ार शुल्क","नाट्य प्रदर्शन व सार्वजनिक मनोरंजन पर कर"],"a":3,"e":"अनुसूची I-ख — जनपद पंचायत द्वारा थिएटर/नाट्य प्रदर्शन व अन्य सार्वजनिक मनोरंजन पर कर। संपत्ति कर ग्राम पंचायत का अनिवार्य कर है।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. छत्तीसगढ़ में ग्राम सभा की बैठक की अध्यक्षता सामान्यतः सरपंच करता है।<br>2. अनुसूचित क्षेत्र की ग्राम सभा की अध्यक्षता भी सरपंच ही करता है।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":0,"e":"कथन 1 सही — धारा 6(4), सरपंच, अनुपस्थिति में उप-सरपंच।<br>कथन 2 गलत — धारा 129-ख: अनुसूचित क्षेत्र में ग्राम सभा का ST सदस्य जो सरपंच, उप-सरपंच या पंचायत सदस्य न हो।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. छत्तीसगढ़ में ज़िला पंचायत अध्यक्ष का निर्वाचन ज़िले के मतदाता प्रत्यक्ष रूप से करते हैं।<br>2. जनपद पंचायत अध्यक्ष का निर्वाचन निर्वाचित सदस्यों द्वारा अपने में से होता है।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":1,"e":"कथन 1 गलत — ज़िला अध्यक्ष भी निर्वाचित सदस्यों द्वारा अपने में से चुना जाता है (धारा 32(3); अनु. 243C(5))।<br>कथन 2 सही — धारा 25(3)।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. छत्तीसगढ़ में जनपद पंचायत का निर्वाचित सदस्य विधायक उसकी प्रत्येक स्थायी समिति का पदेन सदस्य होता है।<br>2. ज़िला पंचायत का सदस्य सांसद अपनी पसंद की दो समितियों का पदेन सदस्य होता है।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":2,"e":"कथन 1 सही — धारा 47(4-A)(a)।<br>कथन 2 सही — धारा 47(4-A)(b); ज़िला पंचायत की प्रत्येक समिति अधिकतम दो विधायकों को सहयोजित कर सकती है।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. सरपंच के विरुद्ध अविश्वास प्रस्ताव पर चर्चा वाली बैठक की अध्यक्षता उप-सरपंच करता है।<br>2. अविश्वास प्रस्ताव कार्यकाल समाप्ति के पूर्व के अंतिम एक वर्ष में नहीं लाया जा सकता।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":3,"e":"कथन 1 गलत — ऐसी बैठक की अध्यक्षता विहित प्राधिकारी द्वारा नियुक्त शासकीय अधिकारी करता है (धारा 21(2))।<br>कथन 2 गलत — प्रतिबंध अंतिम छह माह का है, एक वर्ष का नहीं।"},
    {"q":"सूची-I को सूची-II से सुमेलित कीजिए —<br>(A) ग्राम सभा (सामान्य क्षेत्र) (B) ग्राम पंचायत की बैठक (C) ज़िला पंचायत की बैठक (D) अनुसूचित क्षेत्र की ग्राम सभा<br>1. 1/2 2. 1/3 (उसमें 1/3 महिलाएँ) 3. 1/10 4. 1/3<br>(गणपूर्ति)","o":["A-3, B-1, C-4, D-2","A-3, B-4, C-1, D-2","A-2, B-1, C-4, D-3","A-1, B-3, C-2, D-4"],"a":0,"e":"ग्राम सभा 1/10 (धारा 6); ग्राम पंचायत 1/2 व ज़िला पंचायत 1/3 (धारा 44); अनुसूचित क्षेत्र की ग्राम सभा 1/3 जिसमें 1/3 महिलाएँ (धारा 129-ख)।"},
    {"q":"सूची-I (अविश्वास प्रस्ताव) को सूची-II (विवाद भेजने का प्राधिकारी) से सुमेलित कीजिए —<br>(A) सरपंच (B) जनपद अध्यक्ष (C) ज़िला पंचायत अध्यक्ष<br>1. राज्य सरकार (15 दिन में) 2. कलेक्टर (7 दिन में) 3. संचालक, पंचायत (10 दिन में)","o":["A-3, B-2, C-1","A-2, B-3, C-1","A-2, B-1, C-3","A-1, B-3, C-2"],"a":1,"e":"सरपंच — कलेक्टर, 7 दिन (धारा 21(4)); जनपद अध्यक्ष — संचालक पंचायत, 10 दिन (धारा 28(4)); ज़िला अध्यक्ष — राज्य सरकार, 15 दिन, 45 दिन में निर्णय (धारा 35(4))।"},
    {"q":"सूची-I (स्थायी समिति) को सूची-II (विषय) से सुमेलित कीजिए —<br>(A) कृषि समिति (B) शिक्षा समिति (C) संचार एवं संकर्म समिति (D) सहकारिता एवं उद्योग समिति<br>1. लघु बचत, कुटीर उद्योग, बाज़ार 2. ग्रामीण जल प्रदाय, लघु सिंचाई 3. बीज वितरण, मत्स्य, भू-संरक्षण 4. अस्पृश्यता निवारण, मद्य-निषेध","o":["A-1, B-4, C-2, D-3","A-3, B-2, C-4, D-1","A-3, B-4, C-2, D-1","A-4, B-3, C-1, D-2"],"a":2,"e":"धारा 47(1) — कृषि: बीज, मत्स्य, भू-संरक्षण; शिक्षा: अस्पृश्यता निवारण, मद्य-निषेध, आपदा राहत; संचार-संकर्म: लघु सिंचाई, ग्रामीण जल प्रदाय, आवास; सहकारिता-उद्योग: लघु बचत, कुटीर उद्योग, बाज़ार, सांख्यिकी।"},
    {"q":"अभिकथन (A): छत्तीसगढ़ में ग्राम सभा की बैठक बुलाने में विफल रहने पर सरपंच पद के लिए अयोग्य हो सकता है।<br>कारण (R): पंचायत राज अधिनियम ग्राम सभा की बैठक नियमित अंतराल पर बुलाने का दायित्व सरपंच पर डालता है।","o":["A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है, R गलत है","A गलत है, R सही है","A और R दोनों सही हैं तथा R, A की सही व्याख्या है"],"a":3,"e":"धारा 6(3) — बैठक बुलाने का दायित्व सरपंच का; विफलता पर वह अयोग्य हो जाता है (सुनवाई का अवसर देकर)। अतः R ही A का कारण है।"},
    {"q":"अभिकथन (A): छत्तीसगढ़ की जनपद पंचायतों में विधायक सदस्य होते हैं।<br>कारण (R): जिस विधायक का निर्वाचन क्षेत्र पूर्णतः नगरीय क्षेत्र में हो, वह भी जनपद पंचायत का सदस्य होता है।","o":["A सही है, R गलत है","A और R दोनों सही हैं तथा R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A गलत है, R सही है"],"a":0,"e":"A सही — धारा 22(1)(iii), खंड से पूर्णतः/अंशतः जुड़े विधायक सदस्य।<br>R गलत — परंतुक के अनुसार पूर्णतः नगरीय क्षेत्र वाला विधायक सदस्य नहीं होता।"},
    {"q":"छत्तीसगढ़ में कोई व्यक्ति एक से अधिक पंचायत पदों पर चुना जाए और 10 दिन में विकल्प न दे, तो उसे सबसे पहले किस पद का विकल्प चुना हुआ माना जाता है?","o":["सरपंच","ज़िला पंचायत सदस्य","जनपद पंचायत सदस्य","पंच"],"a":1,"e":"धारा 41(2) — वरीयता क्रम: ज़िला पंचायत सदस्य > जनपद पंचायत सदस्य > सरपंच > पंच। यदि उसने किसी पंचायत की बैठक में भाग ले लिया हो तो वही पद चुना माना जाता है।"},
    {"q":"छत्तीसगढ़ पंचायत राज अधिनियम की धारा 40 के अंतर्गत पद से हटाया गया पदाधिकारी कितने वर्षों तक निर्वाचन हेतु अयोग्य रहता है?","o":["2 वर्ष","5 वर्ष","6 वर्ष","10 वर्ष"],"a":2,"e":"धारा 40(2) — हटाया गया व्यक्ति अन्य पंचायत की सदस्यता भी खो देता है और 6 वर्ष तक निर्वाचन हेतु अयोग्य रहता है।"},
    {"q":"पंचायत पदाधिकारी के निलंबन आदेश की राज्य सरकार द्वारा पुष्टि न होने पर वह कितने दिनों बाद निष्प्रभावी हो जाता है?","o":["90 दिन","30 दिन","60 दिन","180 दिन"],"a":0,"e":"धारा 39(2) — निलंबन आदेश 10 दिन में राज्य सरकार को भेजा जाता है; 90 दिन में पुष्टि न होने पर आदेश समाप्त माना जाता है।"},
    {"q":"छत्तीसगढ़ में पंचायत का पदाधिकारी बिना अनुमति लगातार कितनी बैठकों से अनुपस्थित रहने पर पद खो देता है?","o":["दो","पाँच","छह","तीन"],"a":3,"e":"धारा 36(2)(c) — लगातार तीन बैठकों में, या छह माह की आधी बैठकों में बिना अनुमति अनुपस्थिति पर पद रिक्त। रिक्ति का निर्णय ग्राम/जनपद हेतु कलेक्टर करता है।"},
    {"q":"छत्तीसगढ़ में ग्राम पंचायत की प्रथम बैठक निर्वाचन परिणामों के प्रकाशन से कितने दिनों के भीतर होनी चाहिए?","o":["15 दिन","30 दिन","45 दिन","60 दिन"],"a":1,"e":"धारा 20(1) — 30 दिन के भीतर, विहित प्राधिकारी द्वारा बुलाई जाती है। जनपद (धारा 27) व ज़िला पंचायत (धारा 34) के लिए भी 30 दिन।"},
    {"q":"पंचायत के आधे से अधिक सदस्यों द्वारा लिखित माँग करने पर सरपंच/अध्यक्ष को कितने दिनों में विशेष बैठक बुलानी होती है?","o":["3 दिन","15 दिन","7 दिन","30 दिन"],"a":2,"e":"धारा 44(6) — 7 दिन में; न बुलाने पर माँग करने वाले सदस्य स्वयं बैठक बुला सकते हैं। तीन बार ऐसी विफलता पर अध्यक्ष/सरपंच धारा 40 में हटाया जा सकता है।"},
    {"q":"पंचायत द्वारा अंतिम रूप से निपटाए गए विषय पर छह माह के भीतर पुनर्विचार के लिए कितने सदस्यों की लिखित सहमति आवश्यक है?","o":["कम से कम 3/4","कम से कम 1/2","कम से कम 2/3","कम से कम 1/3"],"a":0,"e":"धारा 45 — मत देने के हकदार सदस्यों के कम से कम 3/4 की सहमति, या विहित प्राधिकारी का निर्देश।"},
    {"q":"ग्राम सभा की वार्षिक बैठक अगले वित्तीय वर्ष के आरंभ से कम से कम कितने समय पहले होनी चाहिए?","o":["एक माह","छह माह","पंद्रह दिन","तीन माह"],"a":3,"e":"धारा 7(2) — कम से कम तीन माह पहले; इसमें वार्षिक लेखा, प्रशासन प्रतिवेदन, आगामी कार्यक्रम, अंकेक्षण टिप्पणी और वार्षिक बजट/योजना रखे जाते हैं।"},
    {"q":"ग्राम सभा के कुल सदस्यों के कितने से अधिक भाग की लिखित माँग पर 30 दिन के भीतर ग्राम सभा की बैठक बुलानी होती है?","o":["1/10","1/3","1/2","1/5"],"a":1,"e":"धारा 6(1) का परंतुक — 1/3 से अधिक सदस्यों की लिखित माँग, या जनपद/ज़िला पंचायत/कलेक्टर की अपेक्षा पर 30 दिन में बैठक।"},
    {"q":"छत्तीसगढ़ पंचायत राज अधिनियम के प्रयोजन हेतु \"ग्राम\" को सार्वजनिक अधिसूचना द्वारा कौन विनिर्दिष्ट करता है?","o":["कलेक्टर","राज्य निर्वाचन आयोग","राज्यपाल","मुख्यमंत्री"],"a":2,"e":"धारा 3 — राज्यपाल ग्राम या ग्रामों के समूह को अधिसूचित करता है। धारा 10(2) के अंतर्गत राज्यपाल ही ज़िले को खंडों में बाँटता है।"},
    {"q":"छत्तीसगढ़ पंचायत राज अधिनियम के अनुसार \"ग्राम\" शब्द में क्या सम्मिलित है?","o":["राजस्व ग्राम और वन ग्राम दोनों","केवल राजस्व ग्राम","केवल वन ग्राम","केवल नगर पंचायत से सटे ग्राम"],"a":0,"e":"धारा 2(xxix) का स्पष्टीकरण — ग्राम में राजस्व ग्राम और वन ग्राम दोनों शामिल हैं; ग्राम सभा इन्हीं की मतदाता सूची से बनती है।"},
    {"q":"छत्तीसगढ़ में किसी जनपद पंचायत का नाम किसके नाम पर रखा जाता है?","o":["ज़िला मुख्यालय","सबसे बड़ी ग्राम पंचायत","तहसील","खंड (ब्लॉक)"],"a":3,"e":"धारा 10(2) — प्रत्येक खंड के लिए एक जनपद पंचायत होगी जो उस खंड के नाम से जानी जाएगी।"},
    {"q":"छत्तीसगढ़ पंचायत राज अधिनियम के अनुसार आम चुनाव में निर्वाचित सरपंच को वापस बुलाने (Recall) की प्रक्रिया उसके पद ग्रहण से कितनी अवधि तक आरंभ नहीं की जा सकती?","o":["एक वर्ष","ढाई वर्ष","दो वर्ष","तीन वर्ष"],"a":1,"e":"धारा 21-क — ढाई वर्ष तक नहीं; वापसी ग्राम सभा के कुल सदस्यों के आधे से अधिक बहुमत से गुप्त मतदान द्वारा।"},
    {"q":"सरपंच को वापस बुलाने की प्रक्रिया आरंभ करने हेतु सूचना पर ग्राम सभा के कम से कम कितने सदस्यों के हस्ताक्षर आवश्यक हैं?","o":["1/10","1/2","1/3","3/4"],"a":2,"e":"धारा 21-क(1) — कम से कम 1/3 सदस्यों के हस्ताक्षर से सूचना विहित प्राधिकारी को; वापसी पर विवाद 7 दिन में कलेक्टर को।"},
    {"q":"छत्तीसगढ़ पंचायत राज अधिनियम के अनुसार ग्राम सभा के कार्यों के संबंध में विचार कीजिए —<br>1. ग्राम पंचायत के वार्षिक बजट पर विचार कर सिफ़ारिश करना<br>2. ग्राम पंचायत के अंकेक्षण प्रतिवेदन पर विचार करना<br>3. ग्राम पंचायत सचिव की नियुक्ति करना<br>सही कथन हैं —","o":["केवल 1 और 2","केवल 2 और 3","केवल 1 और 3","1, 2 और 3"],"a":0,"e":"कथन 1, 2 सही — धारा 7(1)(c), (d)।<br>कथन 3 गलत — सचिव की नियुक्ति राज्य सरकार/विहित प्राधिकारी करता है (धारा 69)।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. छत्तीसगढ़ में ग्राम, जनपद और ज़िला पंचायत निगमित निकाय हैं, जिनका शाश्वत उत्तराधिकार और सामान्य मुद्रा होती है।<br>2. ज़िले में स्थित नगर निगम का क्षेत्र ज़िला पंचायत की प्रशासनिक इकाई का भाग होता है।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":0,"e":"कथन 1 सही — धारा 11।<br>कथन 2 गलत — धारा 10(3) के परंतुक अनुसार प्रत्येक नगर निगम, नगर पालिका परिषद व नगर पंचायत पृथक प्रशासनिक इकाई है।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. एक ग्राम पंचायत सचिव को दो या अधिक ग्राम पंचायतों के समूह के लिए नियुक्त किया जा सकता है।<br>2. ज़िला पंचायत में CEO के अतिरिक्त अपर CEO और उप CEO भी नियुक्त किए जा सकते हैं।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":2,"e":"कथन 1 सही — धारा 69(1)।<br>कथन 2 सही — धारा 69(3), राज्य सरकार अपर CEO, उप CEO व कार्यपालन अधिकारी नियुक्त कर सकती है।"},
    {"q":"सूची-I (धारा) को सूची-II (प्रावधान) से सुमेलित कीजिए —<br>(A) धारा 74 (B) धारा 75 (C) धारा 77(3) (D) धारा 129<br>1. पृथक व स्वतंत्र अंकेक्षण संगठन 2. भू-राजस्व पर उपकर 3. अतिरिक्त स्टाम्प शुल्क 4. कृषि भूमि पर विकास कर","o":["A-2, B-3, C-1, D-4","A-3, B-2, C-4, D-1","A-2, B-3, C-4, D-1","A-4, B-1, C-2, D-3"],"a":2,"e":"धारा 74 — भू-राजस्व पर 50 पैसे/रुपया उपकर; धारा 75 — 1% अतिरिक्त स्टाम्प शुल्क; धारा 77(3) — जनपद द्वारा कृषि भूमि पर विकास कर; धारा 129 — पंचायत लेखों का स्वतंत्र अंकेक्षण।"},
    {"q":"ज़िला पंचायत द्वारा बढ़ाए गए भू-राजस्व उपकर की प्राप्त राशि में ग्राम पंचायत का हिस्सा कितना है?","o":["25%","33%","75%","50%"],"a":3,"e":"धारा 76-क(2) — बढ़े उपकर में से 25% जनपद पंचायत, 25% ज़िला पंचायत और शेष 50% ग्राम पंचायत को।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. 21 वर्ष पूर्ण कर चुका व्यक्ति पंचायत चुनाव के लिए इस आधार पर अयोग्य नहीं होगा कि उसकी आयु 25 वर्ष से कम है।<br>2. पंचायत की ओर से वेतनभोगी विधि व्यवसायी के रूप में नियोजित व्यक्ति पंचायत पदाधिकारी बनने के लिए पात्र है।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":0,"e":"कथन 1 सही — धारा 36(1)(k) का परंतुक (अनु. 243F के अनुरूप)।<br>कथन 2 गलत — धारा 36(1)(g) के अनुसार ऐसा व्यक्ति अयोग्य है।"},
    {"q":"अभिकथन (A): छत्तीसगढ़ में ज़िले के भीतर स्थित नगर निगम का क्षेत्र ज़िला पंचायत के कार्यक्षेत्र से बाहर रहता है।<br>कारण (R): पंचायत राज अधिनियम के अनुसार प्रत्येक नगर निगम, नगर पालिका परिषद या नगर पंचायत अपने क्षेत्र के लिए पृथक प्रशासनिक इकाई है।","o":["A और R दोनों सही हैं तथा R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है, R गलत है","A गलत है, R सही है"],"a":0,"e":"धारा 10(3) का परंतुक नगरीय निकायों को पृथक प्रशासनिक इकाई बनाता है — इसीलिए वे ज़िला पंचायत क्षेत्र से बाहर हैं। R, A की सीधी व्याख्या है।"},
    {"q":"निम्नलिखित को कालक्रमानुसार व्यवस्थित कीजिए —<br>1. छत्तीसगढ़ पंचायतों में महिलाओं को 50% आरक्षण (C.G. अधिनियम 13)<br>2. पंचायत राज अधिनियम 1993 को राज्यपाल की अनुमति<br>3. 73वें संविधान संशोधन का प्रवर्तन<br>4. अधिनियम में \"एक चक्रानुक्रम\" की परिभाषा जोड़ा जाना","o":["3, 2, 1, 4","2, 3, 1, 4","3, 2, 4, 1","2, 3, 4, 1"],"a":0,"e":"73वाँ संशोधन — 24 अप्रैल 1993; अधिनियम को अनुमति — 24 जनवरी 1994; महिला 50% — 23 मई 2008; \"एक चक्रानुक्रम\" — 21 जनवरी 2015 (C.G. अधिनियम 4, 2015)।"},
    {"q":"निम्नलिखित में से कौन-सा युग्म सही सुमेलित नहीं है?","o":["ग्राम पंचायत — 10 से 20 वार्ड","जनपद पंचायत — प्रति निर्वाचन क्षेत्र लगभग 5,000 जनसंख्या","ज़िला पंचायत — अधिकतम 25 निर्वाचन क्षेत्र","नगर पालिक निगम — 40 से 70 वार्ड"],"a":2,"e":"ज़िला पंचायत में अधिकतम 35 निर्वाचन क्षेत्र (धारा 30); 25 की सीमा जनपद पंचायत की है (धारा 23)। शेष युग्म सही हैं।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. सरपंच का पद आकस्मिक रूप से रिक्त होने पर पंच अपने में से कार्यवाहक सरपंच चुनते हैं।<br>2. यदि सरपंच का पद किसी आरक्षित वर्ग का है, तो कार्यवाहक सरपंच उसी वर्ग के सदस्यों में से चुना जाता है।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":2,"e":"कथन 1 सही — धारा 38(1)(b), सचिव 15 दिन में विशेष बैठक बुलाता है।<br>कथन 2 सही — परंतुक के अनुसार कार्यवाहक सरपंच उसी आरक्षित वर्ग से।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. पंचायत पदाधिकारी के निलंबन आदेश की सूचना 30 दिन में राज्य सरकार को भेजी जाती है।<br>2. राज्य सरकार द्वारा 90 दिन में पुष्टि न होने पर निलंबन आदेश निष्प्रभावी हो जाता है।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":1,"e":"कथन 1 गलत — सूचना 10 दिन में भेजी जाती है (धारा 39(2))।<br>कथन 2 सही — 90 दिन में पुष्टि न होने पर आदेश समाप्त।"},
    {"q":"संविधान के अनुसार ग्राम स्तर की पंचायत के अध्यक्ष (सरपंच) का निर्वाचन किस प्रकार होगा?","o":["अनिवार्यतः प्रत्यक्ष निर्वाचन से","अनिवार्यतः अप्रत्यक्ष निर्वाचन से","राज्यपाल द्वारा मनोनयन से","राज्य विधानमंडल की विधि में उपबंधित रीति से"],"a":3,"e":"अनु. 243C(5)(a) — ग्राम स्तर के अध्यक्ष का निर्वाचन राज्य विधि के अनुसार; मध्यवर्ती व ज़िला स्तर के अध्यक्ष निर्वाचित सदस्यों द्वारा अपने में से। छत्तीसगढ़ में सरपंच प्रत्यक्ष चुना जाता है।"},
    {"q":"संविधान का भाग IX (पंचायतें) अनुच्छेद 243M के अंतर्गत निम्न में से किस राज्य पर लागू नहीं होता?","o":["मिज़ोरम","छत्तीसगढ़","ओडिशा","सिक्किम"],"a":0,"e":"अनु. 243M — नागालैंड, मेघालय, मिज़ोरम, अनुसूचित क्षेत्रों, जनजातीय क्षेत्रों तथा मणिपुर के ज़िला परिषद वाले पहाड़ी क्षेत्रों पर लागू नहीं।"},
    {"q":"73वें संशोधन से पूर्व के पंचायत संबंधी असंगत राज्य कानून संशोधन के बाद अधिकतम कितने समय तक प्रभावी रह सकते थे?","o":["छह माह","एक वर्ष","दो वर्ष","पाँच वर्ष"],"a":1,"e":"अनु. 243N — असंगत विधियाँ संशोधित या निरसित होने तक, किंतु प्रारंभ से अधिकतम एक वर्ष तक प्रभावी।"},
    {"q":"पंचायत के निर्वाचन संबंधी मामलों में न्यायालयों के हस्तक्षेप का वर्जन किस अनुच्छेद में है?","o":["अनुच्छेद 243M","अनुच्छेद 243N","अनुच्छेद 243O","अनुच्छेद 243L"],"a":2,"e":"अनु. 243O — परिसीमन/आवंटन संबंधी विधि को न्यायालय में चुनौती नहीं; चुनाव केवल चुनाव याचिका से प्रश्नगत। नगरपालिकाओं हेतु अनु. 243ZG।"},
    {"q":"सूची-I (अनुच्छेद) को सूची-II (विषय) से सुमेलित कीजिए —<br>(A) 243G (B) 243H (C) 243J (D) 243A<br>1. ग्राम सभा 2. लेखाओं की संपरीक्षा 3. कर लगाने की शक्ति व निधियाँ 4. शक्तियाँ, प्राधिकार व उत्तरदायित्व","o":["A-4, B-2, C-3, D-1","A-1, B-3, C-2, D-4","A-3, B-4, C-1, D-2","A-4, B-3, C-2, D-1"],"a":3,"e":"243G — शक्तियाँ (11वीं अनुसूची); 243H — कर व निधियाँ; 243J — लेखा-परीक्षा; 243A — ग्राम सभा।"},
    {"q":"संविधान के अनुसार राज्य निर्वाचन आयुक्त को उसके पद से किस प्रकार हटाया जा सकता है?","o":["राज्यपाल की इच्छा पर","उच्च न्यायालय के न्यायाधीश को हटाने की रीति और आधारों पर ही","विधानसभा के साधारण बहुमत से","मुख्यमंत्री की सलाह पर राष्ट्रपति द्वारा"],"a":1,"e":"अनु. 243K(2) — उच्च न्यायालय के न्यायाधीश की भाँति ही; नियुक्ति के बाद उसकी सेवा-शर्तें उसके लिए अलाभकारी नहीं की जा सकतीं।"},
    {"q":"संविधान के अनुसार पहला राज्य वित्त आयोग 73वें संशोधन अधिनियम के प्रारंभ से कितने समय के भीतर गठित किया जाना था?","o":["एक वर्ष","छह माह","दो वर्ष","पाँच वर्ष"],"a":0,"e":"अनु. 243I(1) — प्रारंभ से एक वर्ष के भीतर और उसके बाद प्रत्येक पाँच वर्ष की समाप्ति पर।"},
    {"q":"राज्य वित्त आयोग की सिफ़ारिशें व उन पर की गई कार्रवाई का स्पष्टीकारक ज्ञापन राज्य विधानमंडल के समक्ष कौन रखवाता है?","o":["मुख्यमंत्री","वित्त मंत्री","राज्यपाल","विधानसभा अध्यक्ष"],"a":2,"e":"अनु. 243I(4) — राज्यपाल प्रत्येक सिफ़ारिश व की गई कार्रवाई का ज्ञापन विधानमंडल के समक्ष रखवाता है।"},
    {"q":"केंद्रीय वित्त आयोग द्वारा राज्य वित्त आयोग की सिफ़ारिशों के आधार पर पंचायतों के संसाधन बढ़ाने हेतु राज्य की संचित निधि बढ़ाने के उपाय सुझाने का प्रावधान कहाँ है?","o":["अनुच्छेद 243-I(1)","अनुच्छेद 266(1)","अनुच्छेद 275(1)","अनुच्छेद 280(3)(bb)"],"a":3,"e":"73वें संशोधन ने अनु. 280(3)(bb) (पंचायतें) और 74वें ने 280(3)(c) (नगरपालिकाएँ) जोड़ा।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. राज्य निर्वाचन आयुक्त की नियुक्ति राष्ट्रपति करते हैं।<br>2. राज्य निर्वाचन आयुक्त को राज्यपाल अपनी इच्छा से कभी भी हटा सकता है।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":3,"e":"कथन 1 गलत — नियुक्ति राज्यपाल करता है (अनु. 243K(1))।<br>कथन 2 गलत — हटाना केवल उच्च न्यायालय के न्यायाधीश की रीति से।"},
    {"q":"निम्नलिखित को कालक्रमानुसार व्यवस्थित कीजिए —<br>1. पी.के. थुंगन समिति<br>2. के. संथानम समिति<br>3. जी.वी.के. राव समिति<br>4. सामुदायिक विकास कार्यक्रम का आरंभ","o":["2, 4, 3, 1","4, 2, 1, 3","4, 2, 3, 1","4, 3, 2, 1"],"a":2,"e":"सामुदायिक विकास कार्यक्रम — 1952; संथानम समिति — 1963; जी.वी.के. राव — 1985; थुंगन समिति — 1988 (पंचायतों को संवैधानिक मान्यता की सिफ़ारिश)।"},
    {"q":"के. संथानम समिति (1963) का संबंध पंचायती राज के किस पहलू से था?","o":["न्याय पंचायतें","पंचायतों का वित्त","राजनीतिक दलों की भागीदारी","ज़िला स्तरीय नियोजन"],"a":1,"e":"संथानम समिति ने पंचायतों के वित्तीय संसाधनों व कर लगाने की शक्तियों पर विचार किया।"},
    {"q":"अशोक मेहता समिति (1977–78) ने ज़िला परिषद के नीचे निचले स्तर की इकाई का क्या नाम सुझाया था?","o":["न्याय पंचायत","क्षेत्र पंचायत","ग्राम परिषद","मंडल पंचायत"],"a":3,"e":"अशोक मेहता समिति — द्विस्तरीय व्यवस्था: ज़िला परिषद और मंडल पंचायत (कई गाँवों का समूह)।"},
    {"q":"पंचायतों को संवैधानिक दर्जा देने वाला 64वाँ संविधान संशोधन विधेयक (1989) कानून क्यों नहीं बन सका?","o":["राज्यसभा में पारित नहीं हो सका","लोकसभा में पारित नहीं हो सका","राष्ट्रपति ने अनुमति नहीं दी","सर्वोच्च न्यायालय ने रद्द कर दिया"],"a":0,"e":"राजीव गांधी सरकार का 64वाँ संशोधन विधेयक लोकसभा में पारित हुआ, पर राज्यसभा में गिर गया। बाद में 73वाँ संशोधन (1992) पारित हुआ।"},
    {"q":"केंद्र में पृथक पंचायती राज मंत्रालय का गठन किस वर्ष हुआ?","o":["1993","2004","1999","2010"],"a":1,"e":"पंचायती राज मंत्रालय मई 2004 में बना। 24 अप्रैल को राष्ट्रीय पंचायती राज दिवस मनाया जाता है।"},
    {"q":"बलवंत राय मेहता समिति ने ज़िला परिषद का अध्यक्ष किसे बनाने की सिफ़ारिश की थी?","o":["ज़िला प्रमुख (निर्वाचित)","स्थानीय सांसद","कलेक्टर","विधायक"],"a":2,"e":"मेहता समिति ने ज़िला परिषद को सलाहकारी निकाय मानकर कलेक्टर को उसका अध्यक्ष सुझाया; पंचायत समिति को मुख्य कार्यकारी स्तर माना।"},
    {"q":"ग्यारहवीं अनुसूची का पहला विषय कौन-सा है?","o":["भूमि सुधार","पेयजल","लघु सिंचाई","कृषि, जिसके अंतर्गत कृषि विस्तार है"],"a":3,"e":"11वीं अनुसूची का क्रम: 1. कृषि (कृषि विस्तार सहित), 2. भूमि सुधार, 3. लघु सिंचाई… छत्तीसगढ़ अधिनियम की अनुसूची IV में यही क्रम है।"},
    {"q":"ग्यारहवीं अनुसूची का अंतिम (29वाँ) विषय कौन-सा है?","o":["सामुदायिक परिसंपत्तियों का अनुरक्षण","सार्वजनिक वितरण प्रणाली","परिवार कल्याण","पुस्तकालय"],"a":0,"e":"28वाँ — सार्वजनिक वितरण प्रणाली; 29वाँ — सामुदायिक परिसंपत्तियों का अनुरक्षण।"},
    {"q":"निम्न में से कौन-सा विषय ग्यारहवीं अनुसूची में नहीं है?","o":["ईंधन और चारा","अग्निशमन सेवाएँ","गैर-पारंपरिक ऊर्जा स्रोत","बाज़ार और मेले"],"a":1,"e":"अग्निशमन सेवाएँ 12वीं अनुसूची (नगरपालिकाएँ) का विषय है। शेष तीनों 11वीं अनुसूची में हैं।"},
    {"q":"निम्न में से कौन-सा विषय बारहवीं अनुसूची में है, किंतु ग्यारहवीं अनुसूची में नहीं?","o":["पेयजल","पुस्तकालय","जन्म-मृत्यु पंजीकरण सहित महत्त्वपूर्ण आँकड़े","बाज़ार और मेले"],"a":2,"e":"जन्म-मृत्यु पंजीकरण सहित महत्त्वपूर्ण आँकड़े 12वीं अनुसूची में है। पेयजल, पुस्तकालय, बाज़ार-मेले 11वीं अनुसूची के विषय हैं।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. लघु वनोपज ग्यारहवीं अनुसूची का विषय है।<br>2. सार्वजनिक वितरण प्रणाली बारहवीं अनुसूची का विषय है।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":0,"e":"कथन 1 सही — 11वीं अनुसूची का 7वाँ विषय।<br>कथन 2 गलत — सार्वजनिक वितरण प्रणाली 11वीं अनुसूची (28वाँ विषय) में है, 12वीं में नहीं।"},
    {"q":"अनुच्छेद 243Q के अनुसार \"वृहत्तर नगरीय क्षेत्र\" के लिए किस नगरीय निकाय का गठन किया जाता है?","o":["नगर पंचायत","नगर निगम","नगर पालिका परिषद","छावनी बोर्ड"],"a":1,"e":"अनु. 243Q — संक्रमणशील क्षेत्र हेतु नगर पंचायत, लघुतर नगरीय क्षेत्र हेतु नगर पालिका परिषद, वृहत्तर नगरीय क्षेत्र हेतु नगर निगम।"},
    {"q":"अनुच्छेद 243Q के परंतुक के अनुसार किस प्रकार के नगरीय क्षेत्र में नगरपालिका का गठन न करने का प्रावधान है, जहाँ नगरीय सेवाएँ कोई औद्योगिक प्रतिष्ठान उपलब्ध कराता हो?","o":["छावनी क्षेत्र","अधिसूचित क्षेत्र","पर्यटन नगरी","औद्योगिक नगरी"],"a":3,"e":"राज्यपाल किसी क्षेत्र को \"औद्योगिक नगरी\" घोषित कर सकता है; वहाँ नगरपालिका आवश्यक नहीं। छत्तीसगढ़ नगर पालिक निगम अधिनियम की धारा 7 में भी यही परंतुक है।"},
    {"q":"74वें संशोधन के अनुसार \"महानगर क्षेत्र\" के लिए न्यूनतम जनसंख्या कितनी है?","o":["10 लाख या अधिक","5 लाख या अधिक","3 लाख या अधिक","40 लाख या अधिक"],"a":0,"e":"अनु. 243P(c) — 10 लाख या अधिक जनसंख्या वाला क्षेत्र; ऐसे क्षेत्र हेतु महानगर योजना समिति (अनु. 243ZE)।"},
    {"q":"ज़िला योजना समिति (अनु. 243ZD) के कम से कम कितने सदस्य ज़िला पंचायत व नगरपालिकाओं के निर्वाचित सदस्यों द्वारा अपने में से निर्वाचित होने चाहिए?","o":["आधे","दो-तिहाई","चार-पाँचवें","तीन-चौथाई"],"a":2,"e":"अनु. 243ZD — कम से कम 4/5 सदस्य, ज़िले की ग्रामीण व नगरीय जनसंख्या के अनुपात में निर्वाचित।"},
    {"q":"महानगर योजना समिति (अनु. 243ZE) के कम से कम कितने सदस्य नगरपालिकाओं के निर्वाचित सदस्यों और पंचायत अध्यक्षों द्वारा निर्वाचित होते हैं?","o":["आधे","दो-तिहाई","चार-पाँचवें","तीन-चौथाई"],"a":1,"e":"अनु. 243ZE(2)(c) — कम से कम 2/3 सदस्य निर्वाचित; ज़िला योजना समिति में यह अनुपात 4/5 है।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. ज़िला योजना समिति का प्रावधान 73वें संशोधन द्वारा जोड़े गए भाग IX में है।<br>2. ज़िला योजना समिति पंचायतों और नगरपालिकाओं की योजनाओं को समेकित कर ज़िले की विकास योजना का प्रारूप तैयार करती है।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":1,"e":"कथन 1 गलत — अनु. 243ZD भाग IXक (74वाँ संशोधन) में है।<br>कथन 2 सही — यही उसका मुख्य कार्य है।"},
    {"q":"74वें संशोधन के अनुसार नगरपालिका में मनोनीत, नगर प्रशासन का विशेष ज्ञान रखने वाले व्यक्तियों के संबंध में सही कथन है —","o":["वे महापौर का चुनाव लड़ सकते हैं","उन्हें सभी बैठकों में मताधिकार है","उनकी संख्या निर्वाचित पार्षदों के बराबर होती है","उन्हें नगरपालिका की बैठकों में मत देने का अधिकार नहीं होता"],"a":3,"e":"अनु. 243R(2)(a) — ऐसे मनोनीत व्यक्तियों को बैठकों में मताधिकार नहीं। छत्तीसगढ़ नगर पालिक निगम अधिनियम धारा 9(3) भी यही कहती है।"},
    {"q":"बारहवीं अनुसूची का पहला विषय कौन-सा है?","o":["नगरीय योजना, जिसके अंतर्गत नगर योजना है","जल प्रदाय","सड़कें और पुल","अग्निशमन सेवाएँ"],"a":0,"e":"12वीं अनुसूची: 1. नगरीय योजना (नगर योजना सहित), 2. भूमि उपयोग व भवन निर्माण का विनियमन, 3. आर्थिक-सामाजिक विकास योजना…"},
    {"q":"बारहवीं अनुसूची का अंतिम (18वाँ) विषय कौन-सा है?","o":["गंदी बस्ती सुधार","जन्म-मृत्यु पंजीकरण","वधशालाओं और चर्मशोधनशालाओं का विनियमन","नगरीय गरीबी उन्मूलन"],"a":2,"e":"17वाँ — मार्ग-प्रकाश, पार्किंग, बस स्टॉप आदि जनसुविधाएँ; 18वाँ — वधशालाओं और चर्मशोधनशालाओं का विनियमन।"},
    {"q":"निम्न में से कौन-सा विषय बारहवीं अनुसूची में नहीं है?","o":["गंदी बस्ती सुधार","लघु वनोपज","कांजी हाउस; पशुओं के प्रति क्रूरता का निवारण","नगरीय वानिकी, पर्यावरण संरक्षण"],"a":1,"e":"लघु वनोपज 11वीं अनुसूची (पंचायत) का विषय है। शेष तीनों 12वीं अनुसूची में हैं।"},
    {"q":"छत्तीसगढ़ नगर पालिक निगम अधिनियम 1956 के अनुसार किसी क्षेत्र को \"वृहत्तर नगरीय क्षेत्र\" के रूप में अधिसूचित कौन करता है?","o":["राज्य निर्वाचन आयोग","नगरीय प्रशासन मंत्री","राज्यपाल","कलेक्टर"],"a":2,"e":"धारा 7(2) — राज्यपाल जनसंख्या, घनत्व, स्थानीय राजस्व, गैर-कृषि रोज़गार का प्रतिशत और आर्थिक महत्त्व देखकर अधिसूचना जारी करता है।"},
    {"q":"छत्तीसगढ़ नगर पालिक निगम अधिनियम के अनुसार किसी नगर निगम में वार्डों की संख्या कितनी हो सकती है?","o":["न्यूनतम 40, अधिकतम 70","न्यूनतम 20, अधिकतम 50","न्यूनतम 30, अधिकतम 60","न्यूनतम 50, अधिकतम 100"],"a":0,"e":"धारा 10(1) — कुल वार्ड 40 से कम और 70 से अधिक नहीं; प्रत्येक वार्ड से एक पार्षद।"},
    {"q":"छत्तीसगढ़ नगर पालिक निगम अधिनियम के अनुसार महापौर पद के प्रत्याशी की न्यूनतम आयु कितनी है?","o":["21 वर्ष","30 वर्ष","18 वर्ष","25 वर्ष"],"a":3,"e":"धारा 16(1) — महापौर हेतु 25 वर्ष और पार्षद हेतु 21 वर्ष। जो व्यक्ति महापौर व पार्षद दोनों चुना जाए उसे 7 दिन में एक पद छोड़ना होता है।"},
    {"q":"छत्तीसगढ़ नगर पालिक निगम अधिनियम के अनुसार राज्य सरकार नगर प्रशासन का विशेष ज्ञान रखने वाले कितने व्यक्तियों को निगम में मनोनीत कर सकती है?","o":["वार्डों की संख्या के 10% तक","वार्डों की संख्या के 15% तक","वार्डों की संख्या के 20% तक","अधिकतम 5 व्यक्ति"],"a":1,"e":"धारा 9(1)(c) (2015 में प्रतिस्थापित) — वार्डों की संख्या के 15% तक; वे राज्य सरकार के प्रसादपर्यंत पद धारण करते हैं और उन्हें मताधिकार नहीं।"},
    {"q":"छत्तीसगढ़ नगर पालिक निगम के संबंध में निम्नलिखित कथनों पर विचार कीजिए —<br>1. निगम क्षेत्र के लोकसभा सदस्य व विधायक निगम की बैठकों में मत दे सकते हैं।<br>2. राज्य सरकार द्वारा मनोनीत सदस्य राज्य सरकार के प्रसादपर्यंत पद धारण करते हैं।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":1,"e":"कथन 1 गलत — धारा 9(3): मनोनीत सदस्य, सांसद व विधायक पार्षद माने जाते हैं पर बैठकों में मताधिकार नहीं।<br>कथन 2 सही — धारा 9(2)।"},
    {"q":"छत्तीसगढ़ में नगर निगम के सभापति (Speaker) का निर्वाचन कौन करता है?","o":["महापौर और निर्वाचित पार्षद, निर्वाचित पार्षदों में से","नगर के मतदाता प्रत्यक्ष रूप से","महापौर द्वारा मनोनयन","राज्य सरकार द्वारा नियुक्ति"],"a":0,"e":"धारा 18(1) — निर्वाचन अधिसूचना से 15 दिन में महापौर व निर्वाचित पार्षद, निर्वाचित पार्षदों में से सभापति चुनते हैं; सभापति का कार्यकाल निगम के कार्यकाल के साथ।"},
    {"q":"नगर निगम के सभापति के चुनाव हेतु बैठक कौन बुलाता है और उसकी अध्यक्षता करता है?","o":["महापौर","आयुक्त","कलेक्टर","संभागायुक्त"],"a":2,"e":"धारा 18(3) — कलेक्टर। सभापति के विरुद्ध अविश्वास प्रस्ताव की बैठक भी कलेक्टर बुलाता व उसकी अध्यक्षता करता है।"},
    {"q":"छत्तीसगढ़ में नगर निगम की सामान्य सभा की बैठकों की अध्यक्षता कौन करता है?","o":["महापौर","सभापति","आयुक्त","नेता प्रतिपक्ष"],"a":1,"e":"धारा 18-क — सभापति निगम की बैठकों की अध्यक्षता करता है और कार्यवृत्त 7 दिन में आयुक्त को भेजता है; अनुपस्थिति हेतु वह दो पार्षदों का पैनल घोषित करता है।"},
    {"q":"नगर निगम सभापति के विरुद्ध अविश्वास प्रस्ताव पारित होने के लिए कितना बहुमत आवश्यक है?","o":["उपस्थित पार्षदों का साधारण बहुमत","कुल पार्षदों का तीन-चौथाई","उपस्थित पार्षदों का तीन-चौथाई तथा कुल का दो-तिहाई से अधिक","उपस्थित व मत देने वाले निर्वाचित पार्षदों का दो-तिहाई तथा कुल निर्वाचित पार्षदों के आधे से अधिक"],"a":3,"e":"धारा 23-क — 2/3 (उपस्थित व मतदान करने वाले) और कुल के आधे से अधिक; निर्णय गुप्त मतदान से। पंचायतों में यह 3/4 और 2/3 से अधिक है।"},
    {"q":"नगर निगम सभापति के विरुद्ध अविश्वास प्रस्ताव उसके पद ग्रहण करने से कितनी अवधि तक नहीं लाया जा सकता?","o":["एक वर्ष","छह माह","दो वर्ष","ढाई वर्ष"],"a":2,"e":"धारा 23-क — दो वर्ष तक, तथा पिछला प्रस्ताव अस्वीकृत होने से एक वर्ष तक नहीं। प्रस्ताव हेतु बैठक की माँग पर कम से कम 1/3 पार्षदों के हस्ताक्षर।"},
    {"q":"छत्तीसगढ़ नगर पालिक निगम अधिनियम के अनुसार महापौर को वापस बुलाने (Recall) का प्रस्ताव, कम से कम 3/4 निर्वाचित पार्षदों के हस्ताक्षर से किसे प्रस्तुत किया जाता है?","o":["संभागायुक्त","कलेक्टर","राज्यपाल","राज्य निर्वाचन आयोग"],"a":0,"e":"धारा 24 — संभागायुक्त सत्यापन कर राज्य सरकार को भेजता है, राज्य सरकार राज्य निर्वाचन आयोग को संदर्भित करती है, जो मतदान कराता है।"},
    {"q":"महापौर को वापस बुलाने के संबंध में निम्नलिखित कथनों पर विचार कीजिए —<br>1. वापसी की प्रक्रिया महापौर के पूरे कार्यकाल में केवल एक बार आरंभ की जा सकती है।<br>2. वापसी पर मतदान राज्य निर्वाचन आयोग कराता है।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":2,"e":"कथन 1 सही — धारा 24 का परंतुक; साथ ही पद ग्रहण से 2 वर्ष तक प्रक्रिया नहीं।<br>कथन 2 सही — धारा 24(3); डाले गए मतों के आधे से अधिक से महापौर पद रिक्त।"},
    {"q":"छत्तीसगढ़ नगर पालिक निगम अधिनियम के अनुसार महापौर-परिषद (Mayor-in-Council) में महापौर के अतिरिक्त कितने सदस्य होते हैं?","o":["3 से 7","कम से कम 5, अधिकतम 10","10 से 15","7 से 12"],"a":1,"e":"धारा 37(2) (2004 के संशोधन से) — महापौर तथा कम से कम 5 और अधिकतम 10 सदस्य।"},
    {"q":"महापौर-परिषद के सदस्यों का चयन किस प्रकार होता है?","o":["पार्षदों द्वारा निर्वाचन","राज्य सरकार द्वारा नियुक्ति","सभापति द्वारा मनोनयन","महापौर द्वारा निर्वाचित पार्षदों में से मनोनयन"],"a":3,"e":"धारा 37 — सभी सदस्य महापौर द्वारा निर्वाचित पार्षदों में से मनोनीत; वे महापौर के प्रसादपर्यंत पद धारण करते हैं और विभागों के प्रभारी बनाए जा सकते हैं।"},
    {"q":"महापौर-परिषद का गठन सभापति के निर्वाचन की तिथि से कितने दिनों के भीतर किया जाना चाहिए?","o":["7 दिन","15 दिन","30 दिन","45 दिन"],"a":0,"e":"धारा 37(1) — 7 दिन के भीतर। वार्ड समितियों का गठन सभापति के निर्वाचन से 30 दिन में होता है।"},
    {"q":"महापौर-परिषद के संबंध में निम्नलिखित कथनों पर विचार कीजिए —<br>1. इसमें कम से कम एक SC या ST, एक OBC और एक महिला सदस्य मनोनीत होना अनिवार्य है।<br>2. इसके सदस्यों को केवल पार्षदों के अविश्वास प्रस्ताव से ही हटाया जा सकता है।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":0,"e":"कथन 1 सही — धारा 37(2) का परंतुक।<br>कथन 2 गलत — सदस्य महापौर के प्रसादपर्यंत पद धारण करते हैं (धारा 37(3))।"},
    {"q":"छत्तीसगढ़ नगर पालिक निगम अधिनियम के अनुसार किसी नगर निगम में वार्ड समितियों की संख्या कैसे निर्धारित होती है?","o":["वार्डों की संख्या ÷ 5","प्रत्येक वार्ड हेतु एक","नगर निगम क्षेत्र की जनसंख्या ÷ 1 लाख","राज्य निर्वाचन आयोग के विवेक से"],"a":2,"e":"धारा 48-क(2) — जनसंख्या ÷ 1 लाख; आधे से कम भिन्न छोड़ी जाती है, आधी या अधिक अगली पूर्ण संख्या मानी जाती है।"},
    {"q":"नगर निगम में वार्ड समितियों का गठन सभापति के निर्वाचन की तिथि से कितने दिनों के भीतर होना चाहिए?","o":["15 दिन","30 दिन","60 दिन","90 दिन"],"a":1,"e":"धारा 48-क(1) — 30 दिन में। 3 लाख या अधिक जनसंख्या वाले निगम में अनिवार्य; कम जनसंख्या वाले भी बना सकते हैं।"},
    {"q":"छत्तीसगढ़ में नगर निगम की प्रत्येक वार्ड समिति में संबंधित पार्षदों के अतिरिक्त महापौर कितने निवासियों को मनोनीत करता है?","o":["पाँच","चार","एक","दो"],"a":3,"e":"धारा 48-क(5) — क्षेत्र के दो निवासी (नगर प्रशासन के विशेष ज्ञान वाले, समिति अध्यक्ष की अनुशंसा पर); इन्हें मताधिकार नहीं।"},
    {"q":"वार्ड समितियों के संबंध में निम्नलिखित कथनों पर विचार कीजिए —<br>1. 3 लाख से कम जनसंख्या वाला नगर निगम भी वार्ड समितियाँ गठित कर सकता है।<br>2. यदि सभापति किसी वार्ड समिति का सदस्य है तो वह उसका पदेन अध्यक्ष होता है।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":2,"e":"कथन 1 सही — धारा 48-क(1) का परंतुक।<br>कथन 2 सही — धारा 48-क(6) का परंतुक; अन्यथा समिति अपने निर्वाचित पार्षदों में से अध्यक्ष चुनती है।"},
    {"q":"छत्तीसगढ़ नगर पालिक निगम अधिनियम के अनुसार निगम आयुक्त को निगम की बैठक में प्रस्ताव पारित कर तत्काल हटाने हेतु कितने पार्षदों का मत आवश्यक है?","o":["कुल निर्वाचित पार्षदों का कम से कम 3/4","उपस्थित पार्षदों का 2/3","कुल निर्वाचित पार्षदों का साधारण बहुमत","उपस्थित पार्षदों का 1/2"],"a":0,"e":"धारा 54(2) — कुल निर्वाचित पार्षदों के कम से कम 3/4 के मत से; राज्य सरकार भी अक्षमता या कदाचार पर कभी भी हटा सकती है।"},
    {"q":"अभिकथन (A): नगर निगम आयुक्त निगम की बैठकों में बोल सकता है, किंतु मत नहीं दे सकता।<br>कारण (R): आयुक्त की नियुक्ति राज्य सरकार अधिकतम पाँच वर्ष की नवीकरणीय अवधि के लिए करती है।","o":["A और R दोनों सही हैं तथा R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है, R गलत है","A गलत है, R सही है"],"a":1,"e":"A सही — धारा 55, आयुक्त प्रधान कार्यपालक अधिकारी है, न मत दे सकता न प्रस्ताव रख सकता।<br>R सही — धारा 54(1); पर नियुक्ति की अवधि मताधिकार न होने का कारण नहीं है।"},
    {"q":"छत्तीसगढ़ नगर पालिक निगम अधिनियम के अनुसार किसी निर्वाचित पार्षद को पद से हटाने की शक्ति किसे है?","o":["महापौर","राज्य निर्वाचन आयोग","कलेक्टर","संभागायुक्त"],"a":3,"e":"धारा 19 — संभागायुक्त; जबकि महापौर, सभापति या समिति अध्यक्ष को हटाने की शक्ति राज्य सरकार को है (धारा 19-ख)।"},
    {"q":"छत्तीसगढ़ में नगर निगम का महापौर अपना त्यागपत्र किसे सौंपता है?","o":["सभापति","राज्य सरकार","संभागायुक्त","राज्यपाल"],"a":1,"e":"धारा 19-ग — महापौर राज्य सरकार को लिखित त्यागपत्र देता है। सभापति व पार्षद महापौर के माध्यम से संभागायुक्त को त्यागपत्र देते हैं (धारा 23)।"},
    {"q":"छत्तीसगढ़ में नगर निगम का पार्षद अपना त्यागपत्र किसे सौंपता है, जो उसे संभागायुक्त को अग्रेषित करता है?","o":["सभापति","आयुक्त","महापौर","कलेक्टर"],"a":2,"e":"धारा 23(1) — पार्षद/सभापति महापौर को त्यागपत्र देता है, जो उसे संभागायुक्त को भेजता है; चाहें तो प्रति सीधे संभागायुक्त को भी भेज सकते हैं।"},
    {"q":"छत्तीसगढ़ में महापौर का पद रिक्त होने पर, उपचुनाव होने तक महापौर के कर्तव्यों का निर्वहन कौन करता है?","o":["राज्य सरकार द्वारा मनोनीत कोई निर्वाचित पार्षद","सभापति स्वतः","नगर निगम आयुक्त","कलेक्टर"],"a":0,"e":"धारा 21(2) — राज्य सरकार किसी निर्वाचित पार्षद को मनोनीत करती है; महापौर पद आरक्षित हो तो उसी वर्ग के पार्षद को। शेष अवधि 6 माह से कम हो तो उपचुनाव नहीं होता।"},
    {"q":"छत्तीसगढ़ नगर पालिक निगम अधिनियम के अनुसार महापौर-परिषद की बैठक की गणपूर्ति कितनी है?","o":["कुल सदस्यों का 1/3","कुल सदस्यों का 1/4","कुल सदस्यों का 2/3","कुल सदस्यों का 1/2"],"a":3,"e":"धारा 49 — महापौर-परिषद या अन्य समिति की गणपूर्ति कुल सदस्यों का आधा।"},
    {"q":"नगर निगम में सभापति या किसी समिति के अध्यक्ष के चुनाव में मत बराबर होने पर परिणाम कैसे तय होता है?","o":["पीठासीन अधिकारी के निर्णायक मत से","लॉट (पर्ची) द्वारा","पुनर्मतदान द्वारा","राज्य सरकार के निर्णय से"],"a":1,"e":"धारा 50 का परंतुक — ऐसे चुनाव में पीठासीन अधिकारी निर्णायक मत नहीं देता, परिणाम लॉट से। अन्य प्रश्नों पर बराबरी में निर्णायक मत दिया जाता है।"},
    {"q":"छत्तीसगढ़ में नगर निगम महापौर पदों का SC/ST हेतु आरक्षण किस आधार पर होता है?","o":["प्रत्येक निगम की अपनी जनसंख्या","संबंधित ज़िले की जनसंख्या","राज्य के सभी नगर निगम क्षेत्रों की कुल जनसंख्या में SC/ST का अनुपात","राज्य की कुल जनसंख्या"],"a":2,"e":"धारा 11-क — सभी नगर निगमों की सीमाओं के भीतर की कुल जनसंख्या में SC व ST के अनुपात में; लगभग आधे पद महिलाओं हेतु।"},
    {"q":"सूची-I को सूची-II से सुमेलित कीजिए —<br>(A) महापौर (B) सभापति (C) निगम आयुक्त (D) संभागायुक्त<br>1. निगम का प्रधान कार्यपालक अधिकारी 2. निगम की बैठकों की अध्यक्षता 3. महापौर-परिषद का पदेन अध्यक्ष 4. पार्षद को पद से हटाना","o":["A-3, B-2, C-1, D-4","A-2, B-3, C-1, D-4","A-3, B-2, C-4, D-1","A-1, B-2, C-3, D-4"],"a":0,"e":"महापौर — महापौर-परिषद का पदेन अध्यक्ष (धारा 37(5)); सभापति — बैठकों की अध्यक्षता (18-क); आयुक्त — प्रधान कार्यपालक अधिकारी (55); संभागायुक्त — पार्षद को हटाना (19)।"},
    {"q":"छत्तीसगढ़ के स्थानीय निकायों से जुड़ी निम्नलिखित घटनाओं को कालक्रमानुसार व्यवस्थित कीजिए —<br>1. नगरीय निकाय आम चुनाव जिनमें महापौर अप्रत्यक्ष रूप से पार्षदों द्वारा चुने गए<br>2. राज्य गठन के बाद प्रथम नगरीय निकाय आम चुनाव<br>3. महापौर/अध्यक्ष के प्रत्यक्ष चुनाव की बहाली हेतु अध्यादेश<br>4. राज्य गठन के बाद प्रथम त्रिस्तरीय पंचायत आम चुनाव","o":["4, 2, 1, 3","2, 1, 4, 3","2, 4, 3, 1","2, 4, 1, 3"],"a":3,"e":"प्रथम नगरीय चुनाव — दिसंबर 2004; प्रथम पंचायत चुनाव — 2005; अप्रत्यक्ष महापौर चुनाव — दिसंबर 2019; प्रत्यक्ष चुनाव बहाली अध्यादेश — दिसंबर 2024।"},
    {"q":"दिसंबर 2019 में हुए छत्तीसगढ़ के नगरीय निकाय चुनावों में महापौर का चुनाव किस प्रकार हुआ?","o":["मतदाताओं द्वारा प्रत्यक्ष","निर्वाचित पार्षदों द्वारा अपने में से (अप्रत्यक्ष)","राज्य सरकार द्वारा मनोनयन","लॉटरी द्वारा"],"a":1,"e":"2019 के संशोधन से महापौर/अध्यक्ष का अप्रत्यक्ष चुनाव लागू हुआ; 2004, 2009 व 2014 में प्रत्यक्ष चुनाव हुआ था और 2025 में पुनः प्रत्यक्ष।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. फ़रवरी 2025 के छत्तीसगढ़ नगरीय निकाय चुनावों में महापौर का चुनाव मतदाताओं ने प्रत्यक्ष रूप से किया।<br>2. प्रत्यक्ष चुनाव की बहाली नगर पालिक निगम अधिनियम 1956 और नगर पालिका अधिनियम 1961 में संशोधन द्वारा की गई।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":2,"e":"कथन 1 सही — 11 फ़रवरी 2025 को एक चरण में मतदान।<br>कथन 2 सही — दिसंबर 2024 में मंत्रिपरिषद ने दोनों अधिनियमों में संशोधन हेतु अध्यादेश के प्रारूप अनुमोदित किए।"},
    {"q":"अभिकथन (A): छत्तीसगढ़ में पंचायत चुनावों में उम्मीदवारों को राजनीतिक दलों के चुनाव-चिह्न आवंटित नहीं किए जाते।<br>कारण (R): छत्तीसगढ़ में नगरीय निकायों के चुनाव भी दलीय आधार पर नहीं होते।","o":["A और R दोनों सही हैं तथा R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है, R गलत है","A गलत है, R सही है"],"a":2,"e":"A सही — पंचायत चुनाव गैर-दलीय आधार पर होते हैं।<br>R गलत — नगरीय निकाय (महापौर, पार्षद) चुनाव दलीय चुनाव-चिह्नों पर होते हैं।"},
    {"q":"छत्तीसगढ़ में नगर पालिका परिषद में \"महापौर-परिषद\" के समतुल्य कार्यकारी निकाय को क्या कहते हैं?","o":["स्थायी समिति","वार्ड समिति","परामर्शदात्री समिति","अध्यक्ष-परिषद (प्रेसिडेंट-इन-काउंसिल)"],"a":3,"e":"नगर पालिका अधिनियम 1961 के अंतर्गत नगर पालिका परिषद व नगर पंचायत में अध्यक्ष-परिषद होती है; दोनों हेतु कार्य-संचालन नियम 1998 में बने।"},
    {"q":"छत्तीसगढ़ नगर पालिका अधिनियम, 1961 किन नगरीय निकायों पर लागू होता है?","o":["नगर पालिका परिषद और नगर पंचायत","केवल नगर निगम","केवल नगर पंचायत","छावनी बोर्ड"],"a":0,"e":"नगर पालिका अधिनियम 1961 (अधिनियम सं. 37, 1961) नगर पालिका परिषद और नगर पंचायत पर; नगर निगम हेतु नगर पालिक निगम अधिनियम 1956।"},
    {"q":"निम्नलिखित में से कौन-सा युग्म (निकाय — प्रशासनिक अधिकारी) सही सुमेलित नहीं है?","o":["नगर पालिक निगम — आयुक्त","ग्राम पंचायत — उप-सरपंच","नगर पालिका परिषद — मुख्य नगर पालिका अधिकारी","जनपद पंचायत — मुख्य कार्यपालन अधिकारी"],"a":1,"e":"ग्राम पंचायत का प्रशासनिक अधिकारी सचिव होता है (धारा 69); उप-सरपंच निर्वाचित पदाधिकारी है। शेष युग्म सही हैं।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. 74वें संशोधन के अनुसार नगरपालिकाओं में महिलाओं के लिए कम से कम एक-तिहाई स्थान आरक्षित हैं।<br>2. छत्तीसगढ़ के नगर निगमों में महिलाओं के लिए केवल एक-तिहाई वार्ड आरक्षित हैं।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":0,"e":"कथन 1 सही — अनु. 243T।<br>कथन 2 गलत — छत्तीसगढ़ नगर पालिक निगम अधिनियम धारा 11(4) के अनुसार यथासंभव 50% वार्ड महिलाओं हेतु।"},
    {"q":"अनुच्छेद 243B के अनुसार कितनी जनसंख्या से अधिक न होने वाले राज्य में मध्यवर्ती स्तर पर पंचायत का गठन करना आवश्यक नहीं है?","o":["10 लाख","20 लाख","25 लाख","50 लाख"],"a":1,"e":"अनु. 243B(2) — 20 लाख से अधिक जनसंख्या न होने वाले राज्य में मध्यवर्ती स्तर की पंचायत का गठन वैकल्पिक है। शेष राज्यों में त्रिस्तरीय ढाँचा अनिवार्य है।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. यदि विघटित पंचायत की शेष अवधि छह माह से कम हो, तो उस अवधि के लिए नया चुनाव कराना आवश्यक नहीं है।<br>2. विघटन के बाद गठित नई पंचायत पूरे पाँच वर्ष के नए कार्यकाल तक बनी रहती है।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":0,"e":"कथन 1 सही — अनु. 243E(3) का परंतुक।<br>कथन 2 गलत — अनु. 243E(4): विघटन के बाद गठित पंचायत केवल शेष अवधि तक ही बनी रहती है।"},
    {"q":"संविधान के अनुसार पंचायत संबंधी राज्य विधि में संशोधन होने पर कार्यरत पंचायत पर क्या प्रभाव पड़ता है?","o":["पंचायत तत्काल विघटित हो जाती है","पंचायत छह माह में विघटित हो जाती है","राज्यपाल के निर्णय तक पंचायत निलंबित रहती है","पंचायत अपनी अवधि की समाप्ति तक विघटित नहीं होती"],"a":3,"e":"अनु. 243E(2) — प्रवृत्त विधि का संशोधन पंचायत को उसकी पाँच वर्ष की अवधि समाप्त होने से पहले विघटित नहीं करता। नगरपालिकाओं हेतु यही प्रावधान अनु. 243U(2) में है।"},
    {"q":"अनुच्छेद 243(b) के अनुसार \"ग्राम सभा\" से क्या अभिप्रेत है?","o":["ग्राम स्तर की पंचायत के क्षेत्र में स्थित ग्राम की मतदाता सूची में पंजीकृत व्यक्तियों का निकाय","ग्राम पंचायत के सभी निर्वाचित पंचों का निकाय","ग्राम के सभी वयस्क पुरुषों की सभा","सरपंच, उप-सरपंच और सचिव की समिति"],"a":0,"e":"अनु. 243(b) — ग्राम सभा ग्राम की निर्वाचक नामावली में पंजीकृत सभी व्यक्तियों का निकाय है। अनु. 243A के अनुसार वह राज्य विधि द्वारा दी गई शक्तियों का प्रयोग करती है।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. संविधान राज्यों के लिए पंचायतों में पिछड़े वर्गों को आरक्षण देना अनिवार्य करता है।<br>2. पंचायतों में महिलाओं के लिए आरक्षित एक-तिहाई स्थानों में SC/ST की महिलाओं के लिए आरक्षित स्थान भी सम्मिलित हैं।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":1,"e":"कथन 1 गलत — अनु. 243D(6) केवल सक्षम करने वाला (ऐच्छिक) प्रावधान है।<br>कथन 2 सही — अनु. 243D(3): महिलाओं के कम से कम 1/3 स्थानों में SC/ST महिलाओं के स्थान भी गिने जाते हैं।"},
    {"q":"सूची-I (संविधान का भाग) को सूची-II (विषय) से सुमेलित कीजिए —<br>(A) भाग IX (B) भाग IXक (C) भाग IXख (D) भाग IV<br>1. सहकारी समितियाँ 2. नगरपालिकाएँ 3. पंचायतें 4. ग्राम पंचायतों का संगठन (अनु. 40)","o":["A-3, B-1, C-2, D-4","A-2, B-3, C-1, D-4","A-3, B-2, C-1, D-4","A-3, B-2, C-4, D-1"],"a":2,"e":"भाग IX — पंचायतें (243 से 243-O, 73वाँ संशोधन); भाग IXक — नगरपालिकाएँ (243P से 243ZG, 74वाँ); भाग IXख — सहकारी समितियाँ (243ZH से 243ZT, 97वाँ संशोधन 2011); भाग IV का अनु. 40 — ग्राम पंचायतों का संगठन।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. ग्यारहवीं अनुसूची 73वें संविधान संशोधन द्वारा जोड़ी गई।<br>2. बारहवीं अनुसूची में 29 विषय हैं।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":0,"e":"कथन 1 सही — 11वीं अनुसूची (29 विषय) 73वें संशोधन से।<br>कथन 2 गलत — 74वें संशोधन से जुड़ी 12वीं अनुसूची में 18 विषय हैं।"},
    {"q":"अनुच्छेद 243ZC के अनुसार भाग IXक (नगरपालिकाएँ) की कोई बात किस परिषद के कार्यों व शक्तियों को प्रभावित नहीं करती?","o":["बोडोलैंड प्रादेशिक परिषद","लद्दाख स्वायत्त पहाड़ी विकास परिषद","दार्जिलिंग गोरखा हिल परिषद","कार्बी आंगलोंग स्वायत्त परिषद"],"a":2,"e":"अनु. 243ZC(2) — दार्जिलिंग गोरखा हिल परिषद की शक्तियाँ अप्रभावित। 243ZC(1) के अनुसार भाग IXक भी अनुसूचित व जनजातीय क्षेत्रों पर लागू नहीं होता।"},
    {"q":"निम्नलिखित पंचायती राज समितियों को कालक्रमानुसार व्यवस्थित कीजिए —<br>1. सी.एच. हनुमंत राव समिति<br>2. अशोक मेहता समिति<br>3. एल.एम. सिंघवी समिति<br>4. बलवंत राय मेहता समिति","o":["4, 2, 3, 1","4, 1, 2, 3","2, 4, 1, 3","4, 2, 1, 3"],"a":3,"e":"बलवंत राय मेहता — 1957; अशोक मेहता — 1977–78; हनुमंत राव (ज़िला स्तरीय नियोजन) — 1984; एल.एम. सिंघवी — 1986।"},
    {"q":"जी.वी.के. राव समिति (1985) ने विकास प्रक्रिया के नौकरशाहीकरण के कारण कमज़ोर हुई पंचायती राज संस्थाओं को किस उपमा से वर्णित किया?","o":["बिना जड़ की घास","कागज़ी शेर","खोखली सीढ़ी","बिना पहिये की गाड़ी"],"a":0,"e":"जी.वी.के. राव समिति (योजना आयोग, 1985) ने कहा कि नौकरशाहीकरण से पंचायती राज \"बिना जड़ की घास\" बन गया। इसने ज़िले को नियोजन की मुख्य इकाई बनाने को कहा।"},
    {"q":"जी.वी.के. राव समिति ने ज़िला परिषद के मुख्य कार्यपालक के रूप में किस नए पद के सृजन की सिफ़ारिश की थी?","o":["ज़िला प्रमुख","ज़िला विकास आयुक्त","ज़िला नियोजन अधिकारी","खंड विकास आयुक्त"],"a":1,"e":"समिति ने \"ज़िला विकास आयुक्त\" का पद सुझाया जो ज़िला परिषद का मुख्य कार्यपालक अधिकारी हो। उसने खंड विकास कार्यालय को ग्रामीण विकास की रीढ़ माना।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. बलवंत राय मेहता समिति ने पंचायत समिति को कार्यकारी निकाय और ज़िला परिषद को सलाहकारी, समन्वयकारी व पर्यवेक्षी निकाय बनाने की सिफ़ारिश की।<br>2. इस समिति ने ग्राम पंचायत को अप्रत्यक्ष रूप से निर्वाचित करने की सिफ़ारिश की।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":0,"e":"कथन 1 सही — मेहता समिति के अनुसार पंचायत समिति कार्यकारी और ज़िला परिषद सलाहकारी।<br>कथन 2 गलत — ग्राम पंचायत प्रत्यक्ष निर्वाचित; पंचायत समिति व ज़िला परिषद अप्रत्यक्ष निर्वाचित।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. अशोक मेहता समिति का गठन जनता पार्टी सरकार ने किया था।<br>2. अशोक मेहता समिति ने राज्य स्तर के नीचे लोकतांत्रिक विकेंद्रीकरण का प्रथम बिंदु ज़िले को माना।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":2,"e":"कथन 1 सही — दिसंबर 1977 में जनता सरकार ने गठित की।<br>कथन 2 सही — समिति ने ज़िले को विकेंद्रीकरण का पहला बिंदु और ज़िला परिषद को कार्यकारी निकाय माना।"},
    {"q":"अशोक मेहता समिति द्वारा प्रस्तावित \"मंडल पंचायत\" लगभग कितनी जनसंख्या वाले ग्राम-समूह के लिए होनी थी?","o":["5,000 से 10,000","50,000 से 1 लाख","15,000 से 20,000","1,000 से 2,000"],"a":2,"e":"मंडल पंचायत — 15,000 से 20,000 जनसंख्या वाले ग्रामों का समूह। समिति ने अगस्त 1978 में 132 सिफ़ारिशों वाली रिपोर्ट दी।"},
    {"q":"अशोक मेहता समिति ने अगस्त 1978 में अपनी रिपोर्ट में कुल कितनी सिफ़ारिशें की थीं?","o":["100","29","64","132"],"a":3,"e":"अशोक मेहता समिति ने 132 सिफ़ारिशें कीं, जिनमें द्विस्तरीय व्यवस्था, राजनीतिक दलों की भागीदारी और अनिवार्य कराधान शक्ति प्रमुख थीं।"},
    {"q":"सूची-I (समिति) को सूची-II (मुख्य विषय/सिफ़ारिश) से सुमेलित कीजिए —<br>(A) पी.के. थुंगन समिति (B) वी.एन. गाडगिल समिति (C) सी.एच. हनुमंत राव समिति (D) एम.एल. दांतवाला समिति<br>1. ज़िला स्तरीय नियोजन (1984) 2. प्रखंड (ब्लॉक) स्तरीय नियोजन (1978) 3. संसदीय सलाहकार समिति की उप-समिति; कलेक्टर ज़िला परिषद का CEO (1988) 4. कांग्रेस की नीति एवं कार्यक्रम समिति (1988)","o":["A-3, B-4, C-1, D-2","A-4, B-3, C-1, D-2","A-3, B-4, C-2, D-1","A-1, B-4, C-3, D-2"],"a":0,"e":"थुंगन (1988) — संवैधानिक मान्यता, कलेक्टर ZP का CEO; गाडगिल (1988) — कांग्रेस की नीति समिति, जिसके सुझाव 64वें विधेयक का आधार बने; हनुमंत राव — 1984 ज़िला नियोजन; दांतवाला — 1978 ब्लॉक नियोजन।"},
    {"q":"बलवंत राय मेहता समिति की सिफ़ारिशों को जनवरी 1958 में किस निकाय ने स्वीकार किया?","o":["योजना आयोग","संसद","अंतर-राज्य परिषद","राष्ट्रीय विकास परिषद"],"a":3,"e":"समिति ने नवंबर 1957 में रिपोर्ट दी; राष्ट्रीय विकास परिषद ने जनवरी 1958 में इसे स्वीकार किया। इसके बाद 2 अक्टूबर 1959 को नागौर से शुरुआत हुई।"},
    {"q":"1882 के स्थानीय स्वशासन संबंधी प्रस्ताव के कारण भारत में \"स्थानीय स्वशासन का जनक\" किसे कहा जाता है?","o":["लॉर्ड मेयो","लॉर्ड रिपन","लॉर्ड कर्ज़न","लॉर्ड डलहौज़ी"],"a":1,"e":"लॉर्ड रिपन का 18 मई 1882 का प्रस्ताव स्थानीय स्वशासन का \"मैग्ना कार्टा\" कहलाता है। उससे पहले 1870 में लॉर्ड मेयो ने वित्तीय विकेंद्रीकरण का प्रस्ताव दिया था।"},
    {"q":"विकेंद्रीकरण पर शाही आयोग (1907) के अध्यक्ष कौन थे?","o":["सी.ई.एच. हॉबहाउस","लॉर्ड मिंटो","सर जॉन साइमन","लॉर्ड चेम्सफ़ोर्ड"],"a":0,"e":"हॉबहाउस की अध्यक्षता वाले आयोग ने 1909 में रिपोर्ट देकर ग्राम स्तर पर पंचायतों के महत्त्व पर बल दिया।"},
    {"q":"भारत का पहला नगर निगम किस नगर में और किस वर्ष स्थापित हुआ?","o":["कलकत्ता, 1726","बंबई, 1726","दिल्ली, 1863","मद्रास, 1688"],"a":3,"e":"मद्रास नगर निगम 1688 में स्थापित हुआ (ईस्ट इंडिया कंपनी का चार्टर दिसंबर 1687) — यह भारत का सबसे पुराना नगर निगम है; बंबई और कलकत्ता में नगर निगम 1726 में बने।"},
    {"q":"निम्नलिखित को कालक्रमानुसार व्यवस्थित कीजिए —<br>1. लॉर्ड रिपन का स्थानीय स्वशासन प्रस्ताव<br>2. लॉर्ड मेयो का वित्तीय विकेंद्रीकरण प्रस्ताव<br>3. मद्रास नगर निगम की स्थापना<br>4. विकेंद्रीकरण पर शाही आयोग","o":["3, 1, 2, 4","3, 2, 1, 4","2, 3, 1, 4","3, 2, 4, 1"],"a":1,"e":"मद्रास नगर निगम — 1688; मेयो प्रस्ताव — 1870; रिपन प्रस्ताव — 1882; शाही आयोग (हॉबहाउस) — 1907।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. भारत शासन अधिनियम 1919 की द्वैध शासन व्यवस्था में स्थानीय स्वशासन \"हस्तांतरित\" विषय था, जो भारतीय मंत्रियों के अधीन था।<br>2. भारत शासन अधिनियम 1935 में स्थानीय स्वशासन को संघीय सूची में रखा गया।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":0,"e":"कथन 1 सही — 1919 में स्थानीय स्वशासन हस्तांतरित विषय बना।<br>कथन 2 गलत — 1935 के अधिनियम में यह प्रांतीय विषय था; आज भी स्थानीय शासन राज्य सूची (प्रविष्टि 5) में है।"},
    {"q":"वर्तमान संविधान में \"स्थानीय शासन\" किस सूची का विषय है?","o":["संघ सूची","समवर्ती सूची","राज्य सूची","अवशिष्ट विषय"],"a":2,"e":"सातवीं अनुसूची की राज्य सूची की प्रविष्टि 5 — स्थानीय शासन। इसलिए पंचायत राज और नगर पालिक अधिनियम राज्य विधानमंडल बनाता है।"},
    {"q":"अभिकथन (A): अनुच्छेद 40 के अंतर्गत ग्राम पंचायतों के गठन का निर्देश न्यायालय द्वारा प्रवर्तनीय नहीं है।<br>कारण (R): अनुच्छेद 40 राज्य के नीति-निदेशक तत्त्वों का भाग है, जो अनुच्छेद 37 के अनुसार किसी न्यायालय द्वारा प्रवर्तनीय नहीं हैं।","o":["A और R दोनों सही हैं तथा R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है, R गलत है","A गलत है, R सही है"],"a":0,"e":"A सही — अनु. 40 मात्र निर्देश है।<br>R सही और A का कारण — भाग IV के तत्त्व अनु. 37 के अनुसार न्यायालय में प्रवर्तनीय नहीं; इसी कमी को 73वें संशोधन ने दूर किया।"},
    {"q":"अभिकथन (A): सभी राज्य ग्यारहवीं अनुसूची के 29 विषय पंचायतों को सौंपने के लिए संवैधानिक रूप से बाध्य नहीं हैं।<br>कारण (R): अनुच्छेद 243G के अनुसार राज्य विधानमंडल विधि द्वारा पंचायतों को शक्तियाँ और प्राधिकार \"दे सकता है\"।","o":["A सही है, R गलत है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A और R दोनों सही हैं तथा R, A की सही व्याख्या है","A गलत है, R सही है"],"a":2,"e":"A सही — शक्तियों का हस्तांतरण 73वें संशोधन का ऐच्छिक प्रावधान है।<br>R सही और A की व्याख्या — 243G में \"may\" (दे सकता है) शब्द है, \"shall\" नहीं।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. पंचायतों में सांसदों और विधायकों का प्रतिनिधित्व 73वें संशोधन का अनिवार्य प्रावधान है।<br>2. प्रत्येक पाँच वर्ष पर राज्य वित्त आयोग का गठन 73वें संशोधन का अनिवार्य प्रावधान है।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":1,"e":"कथन 1 गलत — अनु. 243C(3) के अनुसार राज्य विधानमंडल \"उपबंध कर सकता है\" — यह ऐच्छिक है।<br>कथन 2 सही — अनु. 243I के अंतर्गत वित्त आयोग का गठन अनिवार्य है।"},
    {"q":"73वें संविधान संशोधन का निम्नलिखित में से कौन-सा प्रावधान ऐच्छिक (स्वैच्छिक) है?","o":["महिलाओं हेतु कम से कम एक-तिहाई आरक्षण","राज्य निर्वाचन आयोग का गठन","पिछड़े वर्गों हेतु आरक्षण","सभी स्थानों का प्रत्यक्ष निर्वाचन"],"a":2,"e":"पिछड़े वर्गों का आरक्षण (243D(6)), सांसद-विधायकों का प्रतिनिधित्व, शक्तियों व कराधान का हस्तांतरण ऐच्छिक हैं। शेष तीनों अनिवार्य प्रावधान हैं।"},
    {"q":"पंद्रहवें वित्त आयोग ने ग्रामीण स्थानीय निकायों के अनुदान को बद्ध (tied) और अबद्ध (untied) में किस अनुपात में बाँटा?","o":["50 : 50","60 : 40","40 : 60","75 : 25"],"a":1,"e":"60% बद्ध अनुदान (स्वच्छता/ODF स्थिति, पेयजल, वर्षा जल संचयन व जल पुनर्चक्रण) और 40% अबद्ध अनुदान (वेतन व स्थापना को छोड़कर स्थानीय आवश्यकताएँ)।"},
    {"q":"24 अप्रैल को \"राष्ट्रीय पंचायती राज दिवस\" पहली बार किस वर्ष मनाया गया?","o":["1993","2004","2010","2015"],"a":2,"e":"73वाँ संशोधन 24 अप्रैल 1993 को लागू हुआ; इसकी स्मृति में 2010 से प्रतिवर्ष 24 अप्रैल को राष्ट्रीय पंचायती राज दिवस मनाया जाता है।"},
    {"q":"मई 2004 में गठित केंद्रीय पंचायती राज मंत्रालय के प्रथम मंत्री कौन थे?","o":["मणिशंकर अय्यर","रघुवंश प्रसाद सिंह","जयराम रमेश","सी.पी. जोशी"],"a":0,"e":"मणिशंकर अय्यर 2004 में प्रथम पंचायती राज मंत्री बने। मंत्रालय 27 मई 2004 को ग्रामीण विकास मंत्रालय से अलग कर बनाया गया।"},
    {"q":"राष्ट्रीय ग्राम स्वराज अभियान (RGSA) का शुभारंभ 24 अप्रैल 2018 को किस स्थान से किया गया?","o":["नागौर (राजस्थान)","रामनगर, मंडला (मध्यप्रदेश)","कुरुभाट (छत्तीसगढ़)","अनंतपुर (आंध्र प्रदेश)"],"a":1,"e":"राष्ट्रीय पंचायती राज दिवस 2018 पर मंडला (म.प्र.) से RGSA का शुभारंभ हुआ; इसका उद्देश्य पंचायतों की क्षमता-वृद्धि और प्रशिक्षण है।"},
    {"q":"पंचायतों को राज्य की संचित निधि से सहायता-अनुदान देने का उपबंध संविधान के किस अनुच्छेद में है?","o":["अनुच्छेद 243G","अनुच्छेद 243J","अनुच्छेद 243K","अनुच्छेद 243H"],"a":3,"e":"अनु. 243H — कर, शुल्क, पथकर लगाने की शक्ति, राज्य द्वारा संगृहीत करों का समनुदेशन, संचित निधि से अनुदान और पंचायत निधियों का गठन।"},
    {"q":"सूची-I (अनुच्छेद) को सूची-II (नगरपालिका संबंधी विषय) से सुमेलित कीजिए —<br>(A) 243X (B) 243Y (C) 243Z (D) 243ZA<br>1. लेखाओं की संपरीक्षा 2. वित्त आयोग 3. निर्वाचन 4. कर लगाने की शक्ति व निधियाँ","o":["A-4, B-1, C-2, D-3","A-2, B-4, C-1, D-3","A-4, B-2, C-3, D-1","A-4, B-2, C-1, D-3"],"a":3,"e":"243X — कर व निधियाँ; 243Y — वित्त आयोग (243I वाला आयोग ही); 243Z — लेखा-परीक्षा; 243ZA — राज्य निर्वाचन आयोग द्वारा चुनाव।"},
    {"q":"निम्नलिखित में से कौन-सा युग्म (अनुच्छेद — विषय) सही सुमेलित नहीं है?","o":["243ZG — निर्वाचन मामलों में न्यायालयों के हस्तक्षेप का वर्जन","243ZB — संघ राज्य क्षेत्रों पर लागू होना","243W — नगरपालिका हेतु वित्त आयोग","243V — सदस्यता हेतु अयोग्यताएँ"],"a":2,"e":"243W नगरपालिकाओं की शक्तियाँ, प्राधिकार व उत्तरदायित्व (12वीं अनुसूची) से संबंधित है; वित्त आयोग 243Y में है।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. नगरपालिकाओं के चुनाव पंचायतों से अलग एक पृथक \"नगरीय निर्वाचन आयोग\" कराता है।<br>2. राज्य निर्वाचन आयोग के अनुरोध पर राज्यपाल उसे आवश्यक कर्मचारी उपलब्ध कराता है।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":1,"e":"कथन 1 गलत — अनु. 243ZA(1): नगरपालिका चुनाव भी 243K वाला राज्य निर्वाचन आयोग कराता है।<br>कथन 2 सही — अनु. 243K(3)।"},
    {"q":"अभिकथन (A): भारत निर्वाचन आयोग पंचायतों के चुनाव नहीं कराता।<br>कारण (R): पंचायत चुनावों का अधीक्षण, निर्देशन और नियंत्रण अनुच्छेद 243K के अंतर्गत राज्य निर्वाचन आयोग में निहित है।","o":["A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A और R दोनों सही हैं तथा R, A की सही व्याख्या है","A सही है, R गलत है","A गलत है, R सही है"],"a":1,"e":"A सही — भारत निर्वाचन आयोग (अनु. 324) संसद, विधानमंडल, राष्ट्रपति व उपराष्ट्रपति के चुनाव कराता है।<br>R सही और A की व्याख्या — स्थानीय निकाय चुनाव 243K/243ZA में राज्य निर्वाचन आयोग को सौंपे गए हैं।"},
    {"q":"संविधान के अनुसार पंचायत के किसी सदस्य की अयोग्यता का प्रश्न किसे निर्दिष्ट किया जाता है?","o":["उच्च न्यायालय","राज्य निर्वाचन आयोग अनिवार्यतः","ऐसे प्राधिकारी को जो राज्य विधानमंडल विधि द्वारा उपबंधित करे","राज्यपाल"],"a":2,"e":"अनु. 243F(2) — अयोग्यता का प्रश्न राज्य विधि द्वारा निर्धारित प्राधिकारी को और उसकी रीति से। अनु. 243F(1) के अनुसार विधानमंडल चुनाव की अयोग्यताएँ पंचायत पर भी लागू।"},
    {"q":"पंचायतों को संवैधानिक दर्जा देने वाला 73वाँ संविधान संशोधन अधिनियम किस प्रधानमंत्री के कार्यकाल में संसद से पारित हुआ?","o":["राजीव गांधी","वी.पी. सिंह","एच.डी. देवेगौड़ा","पी.वी. नरसिम्हा राव"],"a":3,"e":"दिसंबर 1992 में नरसिम्हा राव सरकार के समय पारित; 24 अप्रैल 1993 से लागू। राजीव गांधी सरकार का 64वाँ विधेयक (1989) राज्यसभा में गिर गया था।"},
    {"q":"देश में पंचायतों में महिलाओं को 50% आरक्षण देने वाला पहला राज्य कौन-सा था?","o":["छत्तीसगढ़","बिहार","मध्यप्रदेश","केरल"],"a":1,"e":"बिहार ने 2006 में पंचायतों में महिलाओं को 50% आरक्षण दिया। छत्तीसगढ़ में यह 2008 के संशोधन (23 मई 2008 से) से लागू हुआ।"},
    {"q":"संविधान के अनुसार किसी पंचायत का चुनाव किस माध्यम से प्रश्नगत किया जा सकता है?","o":["केवल राज्य विधि में उपबंधित प्राधिकारी को प्रस्तुत निर्वाचन याचिका द्वारा","केवल सर्वोच्च न्यायालय में रिट द्वारा","राज्यपाल को आवेदन द्वारा","राज्य निर्वाचन आयोग में अपील द्वारा"],"a":0,"e":"अनु. 243-O(b) — चुनाव केवल राज्य विधि में बताए प्राधिकारी को प्रस्तुत निर्वाचन याचिका से प्रश्नगत। 243-O(a) के अनुसार परिसीमन संबंधी विधि को न्यायालय में चुनौती नहीं दी जा सकती।"},
    {"q":"अनुच्छेद 243ZD के संबंध में निम्नलिखित कथनों पर विचार कीजिए —<br>1. ज़िला योजना समिति के अध्यक्ष के चयन की रीति राज्य विधानमंडल विधि द्वारा निर्धारित करता है।<br>2. ज़िला योजना समिति केवल ग्रामीण क्षेत्र की योजनाओं को समेकित करती है।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":0,"e":"कथन 1 सही — अनु. 243ZD(2)(d)।<br>कथन 2 गलत — समिति पंचायतों और नगरपालिकाओं दोनों की योजनाओं को समेकित कर पूरे ज़िले की विकास योजना का प्रारूप बनाती है।"},
    {"q":"निम्नलिखित में से किस राज्य के क्षेत्र पेसा अधिनियम 1996 के अंतर्गत नहीं आते?","o":["हिमाचल प्रदेश","गुजरात","तेलंगाना","असम"],"a":3,"e":"पेसा 10 राज्यों के पाँचवीं अनुसूची क्षेत्रों पर — आंध्र प्रदेश, तेलंगाना, छत्तीसगढ़, गुजरात, हिमाचल प्रदेश, झारखंड, मध्यप्रदेश, महाराष्ट्र, ओडिशा, राजस्थान। असम के जनजातीय क्षेत्र छठी अनुसूची में हैं।"},
    {"q":"संसद ने पेसा अधिनियम 1996 संविधान के किस प्रावधान के अंतर्गत प्राप्त शक्ति से बनाया?","o":["अनुच्छेद 243M(4)(b)","अनुच्छेद 368","अनुच्छेद 244A","अनुच्छेद 249"],"a":0,"e":"अनु. 243M(4)(b) — संसद विधि द्वारा भाग IX को अपवादों व उपांतरणों सहित अनुसूचित व जनजातीय क्षेत्रों पर विस्तारित कर सकती है; ऐसी विधि अनु. 368 के अधीन संशोधन नहीं मानी जाती।"},
    {"q":"पेसा (PESA) संक्षिप्त नाम में \"E\" किस शब्द के लिए है?","o":["Empowerment (सशक्तीकरण)","Election (निर्वाचन)","Extension (विस्तार)","Environment (पर्यावरण)"],"a":2,"e":"PESA = Panchayats (Extension to Scheduled Areas) Act, 1996 — पंचायत उपबंध (अनुसूचित क्षेत्रों पर विस्तार) अधिनियम।"},
    {"q":"पेसा अधिनियम की धारा 5 के अनुसार अनुसूचित क्षेत्रों में पंचायत संबंधी असंगत पूर्ववर्ती राज्य विधियाँ अधिकतम कितने समय तक प्रभावी रह सकती थीं?","o":["छह माह","दो वर्ष","पाँच वर्ष","एक वर्ष"],"a":3,"e":"धारा 5 — पेसा से असंगत विधियाँ संशोधित/निरसित होने तक, किंतु अधिनियम को राष्ट्रपति की अनुमति मिलने से अधिकतम एक वर्ष तक प्रभावी। यही अवधि अनु. 243N में है।"},
    {"q":"सूची-I (पेसा धारा 4 का खंड) को सूची-II (प्रावधान) से सुमेलित कीजिए —<br>(A) 4(h) (B) 4(j) (C) 4(k) (D) 4(o)<br>1. ज़िला स्तर पर छठी अनुसूची के प्रतिरूप पर प्रशासनिक व्यवस्था 2. लघु जलाशयों का नियोजन व प्रबंधन 3. गौण खनिजों के पूर्वेक्षण अनुज्ञप्ति/खनन पट्टे से पहले सिफ़ारिश 4. अप्रतिनिधित्व वाली जनजातियों का नामांकन","o":["A-4, B-3, C-2, D-1","A-4, B-2, C-3, D-1","A-1, B-2, C-3, D-4","A-2, B-4, C-1, D-3"],"a":1,"e":"4(h) — अप्रतिनिधित्व वाली जनजातियों का नामांकन (1/10 तक); 4(j) — लघु जलाशय; 4(k) — गौण खनिज पूर्वेक्षण/पट्टा; 4(o) — छठी अनुसूची प्रतिरूप।"},
    {"q":"पेसा अधिनियम का कौन-सा प्रावधान यह सुनिश्चित करता है कि उच्च स्तर की पंचायतें निचले स्तर की पंचायत या ग्राम सभा की शक्तियाँ न हथिया लें?","o":["धारा 4(n)","धारा 4(b)","धारा 4(g)","धारा 4(l)"],"a":0,"e":"धारा 4(n) — राज्य विधि में ऐसे रक्षोपाय हों कि उच्च स्तर की पंचायतें निचले स्तर या ग्राम सभा की शक्तियाँ ग्रहण न करें। 4(b) \"ग्राम\" की परिभाषा है।"},
    {"q":"पेसा अधिनियम के अंतर्गत अनुसूचित क्षेत्र की पंचायतों/ग्राम सभा को दी गई शक्तियों के संबंध में विचार कीजिए —<br>1. मादक पदार्थों के विक्रय व उपभोग का निषेध या नियमन<br>2. अनुसूचित जनजातियों को दिए जाने वाले साहूकारी ऋण पर नियंत्रण<br>3. राज्य के वृहत् (मुख्य) खनिजों के खनन पट्टे देने का अंतिम अधिकार<br>सही कथन हैं —","o":["केवल 1 और 2","केवल 2 और 3","केवल 1 और 3","1, 2 और 3"],"a":0,"e":"कथन 1 व 2 सही — धारा 4(m)(i) व 4(m)(v)।<br>कथन 3 गलत — पेसा केवल गौण खनिजों के पट्टे/नीलामी से पहले ग्राम सभा की सिफ़ारिश की बात करता है (4(k), 4(l)); मुख्य खनिज इसमें नहीं।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. पेसा के अनुसार अनुसूचित क्षेत्र की प्रत्येक पंचायत में अनुसूचित जनजातियों हेतु कम से कम आधे स्थान आरक्षित होंगे।<br>2. पेसा के अनुसार केवल ग्राम पंचायत के सरपंच का पद अनुसूचित जनजाति हेतु आरक्षित होगा; जनपद व ज़िला अध्यक्ष पद नहीं।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":0,"e":"कथन 1 सही — धारा 4(g)।<br>कथन 2 गलत — 4(g) के परंतुक के अनुसार सभी स्तरों की पंचायतों के अध्यक्ष पद ST हेतु आरक्षित।"},
    {"q":"पेसा अधिनियम की धारा 4(h) के अंतर्गत मध्यवर्ती या ज़िला स्तर पर अप्रतिनिधित्व वाली जनजातियों के नामांकित व्यक्तियों की संख्या की अधिकतम सीमा क्या है?","o":["निर्वाचित सदस्यों का 1/5","निर्वाचित सदस्यों का 1/3","निर्वाचित सदस्यों का 1/10","अधिकतम दो व्यक्ति"],"a":2,"e":"राज्य सरकार ऐसी जनजातियों के व्यक्तियों को नामांकित कर सकती है, पर संख्या उस पंचायत के निर्वाचित सदस्यों के 1/10 से अधिक नहीं।"},
    {"q":"अभिकथन (A): पेसा अधिनियम पारित होने से पहले 73वें संशोधन के प्रावधान अनुसूचित क्षेत्रों पर स्वतः लागू नहीं थे।<br>कारण (R): अनुच्छेद 243M(1) के अनुसार भाग IX अनुसूचित क्षेत्रों और जनजातीय क्षेत्रों पर लागू नहीं होता।","o":["A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है, R गलत है","A और R दोनों सही हैं तथा R, A की सही व्याख्या है","A गलत है, R सही है"],"a":2,"e":"A सही — 1996 तक अनुसूचित क्षेत्रों में भाग IX लागू नहीं था।<br>R सही और A की व्याख्या — 243M(1) की छूट के कारण ही पेसा द्वारा \"विस्तार\" करना पड़ा।"},
    {"q":"पेसा अधिनियम की धारा 4(i) के अनुसार अनुसूचित क्षेत्रों में विकास परियोजनाओं हेतु भूमि अधिग्रहण से पूर्व क्या आवश्यक है?","o":["राज्यपाल की अनुमति","उपयुक्त स्तर पर ग्राम सभा या पंचायत से परामर्श","जनजाति सलाहकार परिषद का अनुमोदन","राष्ट्रीय अनुसूचित जनजाति आयोग की सहमति"],"a":1,"e":"धारा 4(i) — भूमि अधिग्रहण और प्रभावितों के पुनर्वास से पहले ग्राम सभा/उपयुक्त पंचायत से परामर्श; परियोजना का वास्तविक नियोजन राज्य स्तर पर समन्वित होता है।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. पेसा के अनुसार ग्राम सभा रूढ़िगत रीति से विवाद निपटान की रक्षा करने में सक्षम है।<br>2. पेसा के अनुसार \"ग्राम\" का अर्थ अनिवार्यतः राजस्व अभिलेख में दर्ज राजस्व ग्राम ही है।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":0,"e":"कथन 1 सही — धारा 4(d)।<br>कथन 2 गलत — धारा 4(b): ग्राम सामान्यतः एक बसाहट/बसाहटों का समूह या टोला/टोलों का समूह है, जहाँ समुदाय परंपरा अनुसार कार्य चलाता है।"},
    {"q":"अनुसूचित क्षेत्र की ग्राम सभा की तुलना में सामान्य क्षेत्र की ग्राम सभा के संबंध में छत्तीसगढ़ पंचायत राज अधिनियम के अनुसार सुमेलित कीजिए —<br>(A) सामान्य क्षेत्र — गणपूर्ति (B) अनुसूचित क्षेत्र — गणपूर्ति (C) सामान्य क्षेत्र — अध्यक्षता (D) अनुसूचित क्षेत्र — अध्यक्षता<br>1. सरपंच, अनुपस्थिति में उप-सरपंच 2. ST सदस्य जो सरपंच/उप-सरपंच/पंच न हो 3. 1/10 4. 1/3","o":["A-4, B-3, C-1, D-2","A-3, B-4, C-2, D-1","A-3, B-4, C-1, D-2","A-1, B-2, C-3, D-4"],"a":2,"e":"सामान्य ग्राम सभा — कोरम 1/10, अध्यक्ष सरपंच (धारा 6); अनुसूचित क्षेत्र — कोरम 1/3, अध्यक्ष ऐसा ST सदस्य जो कोई पंचायत पदाधिकारी न हो (धारा 129-ख)। दोनों में 1/3 महिलाएँ आवश्यक।"},
    {"q":"पाँचवीं अनुसूची के संशोधन के संबंध में सही कथन कौन-सा है?","o":["केवल अनु. 368 की विशेष प्रक्रिया द्वारा, आधे राज्यों के अनुसमर्थन सहित","संसद साधारण विधि द्वारा संशोधन कर सकती है और यह अनु. 368 के अधीन संशोधन नहीं माना जाता","राज्यपाल अधिसूचना द्वारा","जनजाति सलाहकार परिषद के प्रस्ताव द्वारा"],"a":1,"e":"पाँचवीं अनुसूची का पैरा 7 — संसद विधि द्वारा इसमें परिवर्धन/परिवर्तन/निरसन कर सकती है; यह अनु. 368 का संशोधन नहीं माना जाता। छठी अनुसूची (पैरा 21) में भी ऐसा ही है।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. राष्ट्रपति संबंधित राज्यपाल से परामर्श के बाद किसी अनुसूचित क्षेत्र का क्षेत्रफल बढ़ा सकता है।<br>2. किसी क्षेत्र को अनुसूचित क्षेत्र घोषित करने की शक्ति राज्य विधानसभा को है।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":0,"e":"कथन 1 सही — पाँचवीं अनुसूची का पैरा 6(2)।<br>कथन 2 गलत — अनुसूचित क्षेत्र राष्ट्रपति के आदेश द्वारा घोषित होते हैं (पैरा 6(1))।"},
    {"q":"सूची-I (अनुच्छेद) को सूची-II (विषय) से सुमेलित कीजिए —<br>(A) 244(1) (B) 244(2) (C) 244A (D) 339(1)<br>1. असम में स्वायत्त राज्य का गठन 2. अनुसूचित क्षेत्रों के प्रशासन व ST कल्याण पर आयोग 3. पाँचवीं अनुसूची 4. छठी अनुसूची","o":["A-3, B-4, C-1, D-2","A-4, B-3, C-1, D-2","A-3, B-4, C-2, D-1","A-3, B-1, C-4, D-2"],"a":0,"e":"244(1) — पाँचवीं अनुसूची (अनुसूचित क्षेत्र); 244(2) — छठी अनुसूची (असम, मेघालय, त्रिपुरा, मिज़ोरम); 244A — असम में स्वायत्त राज्य (22वाँ संशोधन 1969); 339(1) — राष्ट्रपति द्वारा आयोग।"},
    {"q":"अनुच्छेद 339(1) के अंतर्गत अनुसूचित क्षेत्रों के प्रशासन व अनुसूचित जनजातियों के कल्याण पर रिपोर्ट हेतु 1960 में गठित प्रथम आयोग के अध्यक्ष कौन थे?","o":["दिलीप सिंह भूरिया","यू.एन. ढेबर","बी.डी. शर्मा","वेरियर एल्विन"],"a":1,"e":"यू.एन. ढेबर आयोग (1960–61) प्रथम आयोग था। दूसरा आयोग 2002 में दिलीप सिंह भूरिया की अध्यक्षता में बना।"},
    {"q":"अनुसूचित जनजातियों के कल्याण व अनुसूचित क्षेत्रों के प्रशासन स्तर को ऊँचा करने हेतु भारत की संचित निधि से राज्यों को विशेष अनुदान का प्रावधान किस अनुच्छेद में है?","o":["अनुच्छेद 282","अनुच्छेद 280","अनुच्छेद 275(1)","अनुच्छेद 266"],"a":2,"e":"अनु. 275(1) का प्रथम परंतुक — ST कल्याण योजनाओं और अनुसूचित क्षेत्रों के प्रशासन हेतु विशेष सहायता-अनुदान।"},
    {"q":"निम्नलिखित में से कौन-सा राज्य छठी अनुसूची के अंतर्गत नहीं आता?","o":["मेघालय","त्रिपुरा","मिज़ोरम","मणिपुर"],"a":3,"e":"छठी अनुसूची केवल असम, मेघालय, त्रिपुरा और मिज़ोरम के जनजातीय क्षेत्रों पर लागू है। मणिपुर के पहाड़ी क्षेत्रों में ज़िला परिषदें राज्य विधि से हैं।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. पाँचवीं अनुसूची के अनुसार राज्यपाल अनुसूचित क्षेत्रों में ST सदस्यों द्वारा या उनके बीच भूमि हस्तांतरण को प्रतिषिद्ध या निर्बंधित करने हेतु विनियम बना सकता है।<br>2. ऐसे विनियम राष्ट्रपति को प्रस्तुत किए बिना ही प्रभावी हो जाते हैं।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":0,"e":"कथन 1 सही — पैरा 5(2)(a); साहूकारी व भूमि आवंटन के विनियमन की भी शक्ति।<br>कथन 2 गलत — पैरा 5(4): विनियम राष्ट्रपति की अनुमति के बाद ही प्रभावी होते हैं; पैरा 5(5) के अनुसार पहले जनजाति सलाहकार परिषद से परामर्श आवश्यक।"},
    {"q":"अभिकथन (A): छत्तीसगढ़ में जनजाति सलाहकार परिषद का गठन अनिवार्य है।<br>कारण (R): पाँचवीं अनुसूची के अनुसार अनुसूचित क्षेत्रों वाले प्रत्येक राज्य में जनजाति सलाहकार परिषद होगी, जिसके लगभग तीन-चौथाई सदस्य विधानसभा के ST प्रतिनिधि होंगे।","o":["A और R दोनों सही हैं तथा R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है, R गलत है","A गलत है, R सही है"],"a":0,"e":"A सही — छत्तीसगढ़ में अनुसूचित क्षेत्र हैं।<br>R सही और A की व्याख्या — पैरा 4: अधिकतम 20 सदस्य, लगभग 3/4 ST विधायक।"},
    {"q":"अनुसूचित जनजाति और अन्य परंपरागत वन निवासी (वन अधिकारों की मान्यता) अधिनियम, 2006 के अंतर्गत वन अधिकारों के निर्धारण की प्रक्रिया आरंभ करने वाला प्राधिकारी कौन है?","o":["ज़िला कलेक्टर","वन मंडलाधिकारी","ग्राम सभा","उपखंड स्तरीय समिति"],"a":2,"e":"अधिनियम की धारा 6(1) — ग्राम सभा व्यक्तिगत/सामुदायिक वन अधिकारों के दावों की प्रक्रिया आरंभ करती है; फिर उपखंड व ज़िला स्तरीय समितियाँ विचार करती हैं।"},
    {"q":"वन अधिकार अधिनियम 2006 के अंतर्गत वन अधिकारों की मान्यता हेतु वन भूमि पर काबिज़ होने की अंतिम तिथि (कट-ऑफ़ तिथि) क्या है?","o":["31 दिसंबर 2007","24 दिसंबर 1996","1 जनवरी 2008","13 दिसंबर 2005"],"a":3,"e":"13 दिसंबर 2005 से पूर्व काबिज़ वनवासी पात्र। अधिनियम 31 दिसंबर 2007 से प्रभावी हुआ और नियम 1 जनवरी 2008 से लागू हुए।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. वन अधिकार अधिनियम 2006 के अनुसार \"अन्य परंपरागत वन निवासी\" को कट-ऑफ़ तिथि से पहले कम से कम तीन पीढ़ियों (75 वर्ष) से वन में निवास करना आवश्यक है।<br>2. व्यक्तिगत वन अधिकार के अंतर्गत अधिकतम 4 हेक्टेयर तक भूमि मान्य की जा सकती है।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":2,"e":"कथन 1 सही — धारा 2(o): 13 दिसंबर 2005 से पहले तीन पीढ़ी (प्रत्येक पीढ़ी 25 वर्ष) से निवास।<br>कथन 2 सही — धारा 4(6): वास्तविक कब्ज़े की भूमि, अधिकतम 4 हेक्टेयर।"},
    {"q":"ग्राम न्यायालय अधिनियम, 2008 के अनुसार ग्राम न्यायालय सामान्यतः किस स्तर पर स्थापित किया जाता है?","o":["ग्राम पंचायत स्तर","ज़िला मुख्यालय","मध्यवर्ती पंचायत (जनपद/खंड) मुख्यालय","तहसील न्यायालय परिसर में अनिवार्यतः"],"a":2,"e":"धारा 3 — प्रत्येक मध्यवर्ती पंचायत या ऐसे पंचायत-समूह हेतु ग्राम न्यायालय; मुख्यालय मध्यवर्ती पंचायत मुख्यालय पर। अधिनियम 2 अक्टूबर 2009 से लागू।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. ग्राम न्यायालय का पीठासीन अधिकारी \"न्यायाधिकारी\" कहलाता है, जो प्रथम श्रेणी न्यायिक मजिस्ट्रेट बनने हेतु पात्र होना चाहिए।<br>2. न्यायाधिकारी की नियुक्ति ग्राम सभा अपने सदस्यों में से करती है।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":0,"e":"कथन 1 सही — ग्राम न्यायालय अधिनियम 2008 की धारा 5–6।<br>कथन 2 गलत — न्यायाधिकारी की नियुक्ति राज्य सरकार उच्च न्यायालय के परामर्श से करती है; ग्राम न्यायालय चलित (mobile) न्यायालय के रूप में भी कार्य कर सकता है।"},
    {"q":"पंचायती राज के अंतर्गत \"न्याय पंचायतों\" को विकास पंचायतों से अलग रखकर योग्य न्यायाधीश की अध्यक्षता में रखने की सिफ़ारिश किस समिति ने की थी?","o":["अशोक मेहता समिति","बलवंत राय मेहता समिति","के. संथानम समिति","जी.वी.के. राव समिति"],"a":0,"e":"अशोक मेहता समिति ने न्याय पंचायतों को पृथक निकाय रखने का सुझाव दिया। एल.एम. सिंघवी समिति (1986) ने भी न्याय पंचायतों की स्थापना की सिफ़ारिश की।"},
    {"q":"निम्नलिखित को कालक्रमानुसार व्यवस्थित कीजिए —<br>1. पेसा अधिनियम का लागू होना<br>2. 74वें संविधान संशोधन का लागू होना<br>3. केंद्र में पंचायती राज मंत्रालय का गठन<br>4. 73वें संविधान संशोधन का लागू होना","o":["4, 2, 1, 3","2, 4, 1, 3","4, 1, 2, 3","4, 2, 3, 1"],"a":0,"e":"73वाँ — 24 अप्रैल 1993; 74वाँ — 1 जून 1993; पेसा — 24 दिसंबर 1996; पंचायती राज मंत्रालय — 27 मई 2004।"},
    {"q":"निम्नलिखित को कालक्रमानुसार व्यवस्थित कीजिए —<br>1. नागौर में पंचायती राज का उद्घाटन<br>2. सामुदायिक विकास कार्यक्रम<br>3. राष्ट्रीय विस्तार सेवा<br>4. बलवंत राय मेहता समिति की रिपोर्ट","o":["2, 3, 1, 4","3, 2, 4, 1","2, 3, 4, 1","2, 4, 3, 1"],"a":2,"e":"सामुदायिक विकास कार्यक्रम — 2 अक्टूबर 1952; राष्ट्रीय विस्तार सेवा — 1953; मेहता समिति रिपोर्ट — नवंबर 1957; नागौर उद्घाटन — 2 अक्टूबर 1959।"},
    {"q":"\"लोकतांत्रिक विकेंद्रीकरण\" (Democratic Decentralisation) शब्द का प्रयोग पंचायती राज के संदर्भ में किस समिति ने किया?","o":["अशोक मेहता समिति","एल.एम. सिंघवी समिति","बलवंत राय मेहता समिति","पी.के. थुंगन समिति"],"a":2,"e":"बलवंत राय मेहता समिति (1957) ने त्रिस्तरीय \"लोकतांत्रिक विकेंद्रीकरण\" की योजना सुझाई जिसे बाद में पंचायती राज कहा गया।"},
    {"q":"सूची-I (योजना/अभियान) को सूची-II (शुभारंभ स्थल) से सुमेलित कीजिए —<br>(A) मनरेगा (B) श्यामा प्रसाद मुखर्जी रूर्बन मिशन (C) प्रधानमंत्री आवास योजना — ग्रामीण (D) राष्ट्रीय ग्राम स्वराज अभियान<br>1. आगरा 2. मंडला 3. अनंतपुर 4. कुरुभाट","o":["A-3, B-4, C-2, D-1","A-4, B-3, C-1, D-2","A-3, B-1, C-4, D-2","A-3, B-4, C-1, D-2"],"a":3,"e":"मनरेगा — अनंतपुर (आं.प्र.), 2 फ़रवरी 2006; रूर्बन — कुरुभाट (राजनांदगाँव), 21 फ़रवरी 2016; PMAY-G — आगरा, 20 नवंबर 2016; RGSA — मंडला, 24 अप्रैल 2018।"},
    {"q":"निम्नलिखित ग्रामीण विकास योजनाओं को उनके आरंभ के कालक्रम में व्यवस्थित कीजिए —<br>1. जल जीवन मिशन<br>2. राष्ट्रीय ग्रामीण आजीविका मिशन<br>3. प्रधानमंत्री ग्राम सड़क योजना<br>4. श्यामा प्रसाद मुखर्जी रूर्बन मिशन","o":["3, 2, 1, 4","3, 2, 4, 1","2, 3, 4, 1","3, 4, 2, 1"],"a":1,"e":"PMGSY — 25 दिसंबर 2000; NRLM — जून 2011; रूर्बन — 21 फ़रवरी 2016; जल जीवन मिशन — 15 अगस्त 2019।"},
    {"q":"स्वामित्व (SVAMITVA) योजना के अंतर्गत ग्रामीण आबादी क्षेत्र का ड्रोन सर्वेक्षण करने वाला तकनीकी भागीदार कौन है?","o":["भारतीय सर्वेक्षण विभाग (Survey of India)","इसरो","राष्ट्रीय सूचना विज्ञान केंद्र","भारतीय भूवैज्ञानिक सर्वेक्षण"],"a":0,"e":"पंचायती राज मंत्रालय की योजना; सर्वेक्षण भारतीय सर्वेक्षण विभाग करता है और ग्रामीणों को संपत्ति कार्ड मिलते हैं। शुभारंभ 24 अप्रैल 2020।"},
    {"q":"ग्राम पंचायत विकास योजना (GPDP) तैयार करने हेतु 2 अक्टूबर 2018 से चलाए गए \"जन योजना अभियान\" का नारा क्या है?","o":["मेरा गाँव मेरी धरोहर","सबकी योजना सबका विकास","ग्राम स्वराज से राष्ट्र स्वराज","हमारा गाँव हमारी योजना"],"a":1,"e":"\"सबकी योजना सबका विकास\" अभियान में ग्राम सभाओं में GPDP तैयार किया जाता है। GPDP का आधार अनु. 243G (आर्थिक विकास व सामाजिक न्याय की योजनाएँ) है।"},
    {"q":"पंचायती राज मंत्रालय द्वारा सर्वश्रेष्ठ ग्राम सभा को दिया जाने वाला पुरस्कार किसके नाम पर है?","o":["दीनदयाल उपाध्याय","महात्मा गांधी","नानाजी देशमुख","जयप्रकाश नारायण"],"a":2,"e":"नानाजी देशमुख राष्ट्रीय गौरव ग्राम सभा पुरस्कार ग्राम सभा हेतु; दीनदयाल उपाध्याय पंचायत सशक्तीकरण पुरस्कार पंचायतों के तीनों स्तरों हेतु।"},
    {"q":"अभिकथन (A): छत्तीसगढ़ के अनुसूचित क्षेत्रों में ग्राम सभा की अध्यक्षता सरपंच नहीं करता।<br>कारण (R): पेसा की भावना के अनुरूप ग्राम सभा को पंचायत के निर्वाचित पदाधिकारियों से स्वतंत्र, पारंपरिक सामुदायिक मंच बनाया गया है।","o":["A सही है, R गलत है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A गलत है, R सही है","A और R दोनों सही हैं तथा R, A की सही व्याख्या है"],"a":3,"e":"A सही — धारा 129-ख के अनुसार अध्यक्षता ऐसा ST सदस्य करता है जो सरपंच/उप-सरपंच/पंच न हो।<br>R सही और A की व्याख्या — इससे ग्राम सभा पंचायत की कार्यपालिका से अलग स्वतंत्र निकाय बनी रहती है।"},
    {"q":"निम्नलिखित में से कौन-सा युग्म (पेसा प्रावधान — धारा) सही सुमेलित नहीं है?","o":["लघु वनोपज का स्वामित्व — 4(m)(ii)","ग्राम बाज़ारों का प्रबंधन — 4(m)(iv)","अनुसूचित जनजाति हेतु कम से कम आधे स्थान — 4(g)","गौण खनिजों के पट्टे से पूर्व सिफ़ारिश — 4(o)"],"a":3,"e":"गौण खनिजों के पूर्वेक्षण अनुज्ञप्ति/खनन पट्टे से पहले सिफ़ारिश 4(k) में है; 4(o) ज़िला स्तर पर छठी अनुसूची प्रतिरूप की बात करता है।"},
    {"q":"पेसा अधिनियम की धारा 4(m)(iii) के अंतर्गत पंचायतों/ग्राम सभा को कौन-सी शक्ति दी गई है?","o":["अनुसूचित क्षेत्रों में भूमि के हस्तांतरण को रोकना और अवैध रूप से हस्तांतरित भूमि वापस दिलाना","पुलिस थाने खोलना","राज्य विधानसभा हेतु प्रत्याशी नामित करना","आयकर में छूट देना"],"a":0,"e":"4(m)(iii) — भूमि हस्तांतरण रोकना व अवैध हस्तांतरित भूमि की वापसी; 4(m)(vi) व (vii) — सामाजिक क्षेत्र की संस्थाओं तथा जनजातीय उप-योजना सहित स्थानीय योजनाओं पर नियंत्रण।"},
    {"q":"पाँचवीं अनुसूची के अनुसार अनुसूचित क्षेत्रों के प्रशासन के संबंध में राज्यपाल अपनी रिपोर्ट किसे भेजता है?","o":["राज्य विधानसभा","प्रधानमंत्री","राष्ट्रीय अनुसूचित जनजाति आयोग","राष्ट्रपति"],"a":3,"e":"पैरा 3 — राज्यपाल प्रतिवर्ष या राष्ट्रपति के माँगने पर रिपोर्ट राष्ट्रपति को देता है; संघ की कार्यपालिका राज्य को प्रशासन संबंधी निर्देश दे सकती है।"},
    {"q":"भारत में छावनी बोर्ड (Cantonment Board) किस मंत्रालय के प्रशासनिक नियंत्रण में कार्य करते हैं?","o":["आवासन एवं शहरी कार्य मंत्रालय","गृह मंत्रालय","पंचायती राज मंत्रालय","रक्षा मंत्रालय"],"a":3,"e":"छावनी बोर्ड छावनी अधिनियम, 2006 के अंतर्गत केंद्र सरकार के रक्षा मंत्रालय के अधीन होते हैं। ये 74वें संशोधन वाली नगरपालिकाओं से भिन्न हैं।"},
    {"q":"छावनी बोर्ड का पदेन अध्यक्ष सामान्यतः कौन होता है?","o":["ज़िला कलेक्टर","स्टेशन का सैन्य कमांडर (Station Commander)","निर्वाचित उपाध्यक्ष","राज्य का नगरीय प्रशासन मंत्री"],"a":1,"e":"छावनी बोर्ड में निर्वाचित और पदेन/मनोनीत सदस्य होते हैं; स्टेशन कमांडर पदेन अध्यक्ष और निर्वाचित सदस्यों में से उपाध्यक्ष चुना जाता है।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. टाउनशिप (उद्योग नगरी) के प्रशासन हेतु निवासियों द्वारा निर्वाचित सदस्य होते हैं।<br>2. अधिसूचित क्षेत्र समिति (Notified Area Committee) के सभी सदस्य, अध्यक्ष सहित, राज्य सरकार द्वारा मनोनीत होते हैं।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":1,"e":"कथन 1 गलत — टाउनशिप का प्रशासन संबंधित सार्वजनिक उपक्रम द्वारा नियुक्त टाउनशिप प्रशासक करता है; कोई निर्वाचित सदस्य नहीं।<br>कथन 2 सही — अधिसूचित क्षेत्र समिति पूर्णतः मनोनीत निकाय है।"},
    {"q":"सूची-I (नगरीय स्थानीय निकाय का प्रकार) को सूची-II (विशेषता) से सुमेलित कीजिए —<br>(A) छावनी बोर्ड (B) अधिसूचित क्षेत्र समिति (C) टाउनशिप (D) पत्तन न्यास (Port Trust)<br>1. संसद के अधिनियम द्वारा बंदरगाह क्षेत्र हेतु 2. रक्षा मंत्रालय के अधीन 3. बड़े सार्वजनिक उपक्रम द्वारा अपने कर्मचारियों की बस्ती हेतु 4. राज्य सरकार द्वारा मनोनीत सदस्य","o":["A-2, B-3, C-4, D-1","A-2, B-4, C-1, D-3","A-4, B-2, C-3, D-1","A-2, B-4, C-3, D-1"],"a":3,"e":"छावनी बोर्ड — रक्षा मंत्रालय; अधिसूचित क्षेत्र समिति — मनोनीत सदस्य; टाउनशिप — सार्वजनिक उपक्रम (जैसे भिलाई इस्पात संयंत्र की टाउनशिप); पत्तन न्यास — संसद के अधिनियम से बंदरगाह क्षेत्र हेतु।"},
    {"q":"अमृत (AMRUT), स्मार्ट सिटी मिशन और प्रधानमंत्री आवास योजना (शहरी) — तीनों का शुभारंभ एक साथ किस तिथि को हुआ?","o":["2 अक्टूबर 2014","15 अगस्त 2015","1 अप्रैल 2016","25 जून 2015"],"a":3,"e":"तीनों नगरीय मिशन 25 जून 2015 को आरंभ हुए। स्वच्छ भारत मिशन (शहरी) 2 अक्टूबर 2014 को शुरू हुआ था।"},
    {"q":"नगरीय योजना \"AMRUT\" का पूरा नाम क्या है?","o":["अटल मिशन फ़ॉर रिजुवेनेशन एंड अर्बन ट्रांसफ़ॉर्मेशन","अर्बन मिशन फ़ॉर रिन्यूअल एंड अर्बन टेक्नोलॉजी","अटल मिशन फ़ॉर रूरल-अर्बन ट्रांज़िशन","ऑल-इंडिया मिशन फ़ॉर रोड्स एंड अर्बन ट्रांसपोर्ट"],"a":0,"e":"AMRUT — Atal Mission for Rejuvenation and Urban Transformation; जल आपूर्ति, सीवरेज, हरित क्षेत्र आदि पर केंद्रित। इसका दूसरा चरण AMRUT 2.0 है।"},
    {"q":"महिला स्व-सहायता समूहों (\"स्वच्छता दीदी\") द्वारा घर-घर कचरा संग्रहण पर आधारित \"ठोस एवं तरल संसाधन प्रबंधन\" (SLRM) मॉडल के लिए छत्तीसगढ़ का कौन-सा नगर राष्ट्रीय स्तर पर प्रसिद्ध है?","o":["जगदलपुर","अंबिकापुर","कोरबा","धमतरी"],"a":1,"e":"अंबिकापुर नगर निगम का SLRM मॉडल कचरे को स्रोत पर अलग कर पुनर्चक्रण करता है और स्वच्छ सर्वेक्षण में बार-बार सराहा गया। ठोस अपशिष्ट प्रबंधन 12वीं अनुसूची का विषय है।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. अनुच्छेद 243Q के अनुसार \"वृहत्तर नगरीय क्षेत्र\" हेतु नगर पालिका परिषद का गठन होता है।<br>2. किसी क्षेत्र को संक्रमणशील या नगरीय क्षेत्र विनिर्दिष्ट करते समय राज्यपाल गैर-कृषि कार्यों में नियोजन का प्रतिशत भी ध्यान में रखता है।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":1,"e":"कथन 1 गलत — वृहत्तर नगरीय क्षेत्र हेतु नगर निगम; लघुतर हेतु नगर पालिका परिषद।<br>कथन 2 सही — अनु. 243Q(2): जनसंख्या, घनत्व, स्थानीय राजस्व, गैर-कृषि नियोजन का प्रतिशत, आर्थिक महत्त्व।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. अनुच्छेद 243S के अनुसार 3 लाख या अधिक जनसंख्या वाली नगरपालिका में वार्ड समितियाँ गठित होंगी।<br>2. यदि वार्ड समिति एक ही वार्ड की हो, तो उस वार्ड का प्रतिनिधित्व करने वाला नगरपालिका सदस्य समिति का अध्यक्ष होगा।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":2,"e":"कथन 1 सही — अनु. 243S(1)।<br>कथन 2 सही — अनु. 243S(4); अनेक वार्डों वाली समिति का अध्यक्ष उन सदस्यों में से चुना जाता है।"},
    {"q":"संविधान के अनुसार \"महानगर क्षेत्र\" को लोक अधिसूचना द्वारा कौन विनिर्दिष्ट करता है?","o":["राष्ट्रपति","आवासन एवं शहरी कार्य मंत्रालय","राज्य निर्वाचन आयोग","राज्यपाल"],"a":3,"e":"अनु. 243P(c) — 10 लाख या अधिक जनसंख्या वाला, एक या अधिक ज़िलों और दो या अधिक नगरपालिकाओं/पंचायतों से बना क्षेत्र, जिसे राज्यपाल अधिसूचित करे।"},
    {"q":"नगरपालिकाओं की वित्तीय स्थिति का पुनर्विलोकन करने वाला वित्त आयोग (अनु. 243Y) कौन-सा होता है?","o":["केंद्रीय वित्त आयोग","नगरपालिकाओं हेतु पृथक नगरीय वित्त आयोग","अनुच्छेद 243-I के अंतर्गत गठित राज्य वित्त आयोग ही","नीति आयोग"],"a":2,"e":"अनु. 243Y(1) — 243-I के अधीन गठित वित्त आयोग ही नगरपालिकाओं की वित्तीय स्थिति का भी पुनर्विलोकन करता है; अर्थात् पंचायत व नगरीय निकाय दोनों के लिए एक ही राज्य वित्त आयोग।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. 97वें संविधान संशोधन (2011) द्वारा सहकारी समितियों हेतु भाग IXख जोड़ा गया।<br>2. इसी संशोधन द्वारा सहकारी समितियों के संवर्धन संबंधी नीति-निदेशक तत्त्व अनुच्छेद 43B जोड़ा गया।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":2,"e":"कथन 1 सही — भाग IXख (अनु. 243ZH से 243ZT)।<br>कथन 2 सही — अनु. 43B जोड़ा गया और अनु. 19(1)(c) में \"सहकारी समितियाँ\" शब्द जोड़ा गया।"},
    {"q":"सूची-I (प्रक्रिया) को सूची-II (समय-सीमा) से सुमेलित कीजिए — छत्तीसगढ़ नगर पालिक निगम अधिनियम के अनुसार<br>(A) महापौर-परिषद का गठन (B) वार्ड समितियों का गठन (C) सभापति का निर्वाचन<br>1. निर्वाचन अधिसूचना से 15 दिन में 2. सभापति के निर्वाचन से 7 दिन में 3. सभापति के निर्वाचन से 30 दिन में","o":["A-2, B-1, C-3","A-3, B-2, C-1","A-1, B-3, C-2","A-2, B-3, C-1"],"a":3,"e":"महापौर-परिषद — 7 दिन (धारा 37(1)); वार्ड समितियाँ — 30 दिन (धारा 48-क); सभापति — निर्वाचन अधिसूचना से 15 दिन (धारा 18(1))।"},
    {"q":"सूची-I (पदाधिकारी) को सूची-II (हटाने/पद पर बने रहने का आधार) से सुमेलित कीजिए — छत्तीसगढ़ नगर पालिक निगम अधिनियम के अनुसार<br>(A) निर्वाचित पार्षद (B) महापौर (C) निगम आयुक्त (D) महापौर-परिषद का सदस्य<br>1. महापौर का प्रसादपर्यंत 2. संभागायुक्त द्वारा हटाया जाना 3. कुल निर्वाचित पार्षदों के 3/4 के मत से निगम द्वारा हटाया जाना 4. राज्य सरकार द्वारा हटाया जाना","o":["A-2, B-4, C-3, D-1","A-4, B-2, C-3, D-1","A-2, B-4, C-1, D-3","A-2, B-3, C-4, D-1"],"a":0,"e":"पार्षद — संभागायुक्त (धारा 19); महापौर — राज्य सरकार (धारा 19-ख); आयुक्त — 3/4 निर्वाचित पार्षदों के मत से (धारा 54(2)); महापौर-परिषद सदस्य — महापौर के प्रसादपर्यंत (धारा 37(3))।"},
    {"q":"अभिकथन (A): छत्तीसगढ़ में किसी नगर निगम के महापौर पद का SC/ST आरक्षण केवल उसी निगम की SC/ST जनसंख्या पर आधारित नहीं होता।<br>कारण (R): महापौर पदों का आरक्षण राज्य के सभी नगर निगम क्षेत्रों की कुल जनसंख्या में SC व ST के अनुपात में किया जाता है।","o":["A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A और R दोनों सही हैं तथा R, A की सही व्याख्या है","A सही है, R गलत है","A गलत है, R सही है"],"a":1,"e":"A सही और R उसकी सीधी व्याख्या — धारा 11-क के अनुसार आरक्षण की इकाई \"राज्य के सभी नगर निगम\" हैं, अलग-अलग निगम नहीं।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. नगर निगम सभापति के विरुद्ध अविश्वास प्रस्ताव उसके पद ग्रहण से दो वर्ष तक नहीं लाया जा सकता।<br>2. सभापति के विरुद्ध अविश्वास प्रस्ताव की बैठक महापौर बुलाता है और उसकी अध्यक्षता करता है।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":0,"e":"कथन 1 सही — धारा 23-क।<br>कथन 2 गलत — ऐसी बैठक कलेक्टर बुलाता है और उसकी अध्यक्षता भी कलेक्टर करता है।"},
    {"q":"निम्नलिखित में से कौन-सा युग्म (छत्तीसगढ़ नगर पालिक निगम अधिनियम) सही सुमेलित नहीं है?","o":["महापौर हेतु न्यूनतम आयु — 25 वर्ष","पार्षद हेतु न्यूनतम आयु — 21 वर्ष","राज्य सरकार द्वारा मनोनीत सदस्य — वार्डों की संख्या के 15% तक","महापौर-परिषद में महापौर के अतिरिक्त अधिकतम सदस्य — 15"],"a":3,"e":"महापौर-परिषद में महापौर के अतिरिक्त कम से कम 5 और अधिकतम 10 सदस्य होते हैं (धारा 37(2))। शेष युग्म सही हैं।"},
    {"q":"नगर निगम आयुक्त के संबंध में निम्नलिखित कथनों पर विचार कीजिए —<br>1. आयुक्त निगम की बैठकों में प्रस्ताव रख सकता है और मत दे सकता है।<br>2. राज्य सरकार आयुक्त की नियुक्ति अधिकतम पाँच वर्ष की अवधि के लिए करती है, जिसे बढ़ाया जा सकता है।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":1,"e":"कथन 1 गलत — धारा 55: आयुक्त बैठक में भाग ले सकता है, बोल सकता है, पर न प्रस्ताव रख सकता है न मत दे सकता है।<br>कथन 2 सही — धारा 54(1)।"},
    {"q":"महापौर को वापस बुलाने (Recall) के संबंध में निम्नलिखित कथनों पर विचार कीजिए —<br>1. वापसी का प्रस्ताव कम से कम आधे निर्वाचित पार्षदों के हस्ताक्षर से प्रस्तुत किया जा सकता है।<br>2. महापौर के पद ग्रहण से दो वर्ष तक वापसी की प्रक्रिया आरंभ नहीं की जा सकती।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":1,"e":"कथन 1 गलत — कम से कम 3/4 निर्वाचित पार्षदों के हस्ताक्षर आवश्यक (धारा 24)।<br>कथन 2 सही — पद ग्रहण से 2 वर्ष तक प्रक्रिया नहीं, और पूरे कार्यकाल में केवल एक बार।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. महापौर का पद रिक्त होने पर उपचुनाव तक नगर निगम आयुक्त महापौर के रूप में कार्य करता है।<br>2. महापौर पद रिक्त होने पर, यदि शेष अवधि छह माह से कम हो, तो उपचुनाव नहीं कराया जाता।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":1,"e":"कथन 1 गलत — धारा 21(2): राज्य सरकार किसी निर्वाचित पार्षद (आरक्षित पद हो तो उसी वर्ग का) को मनोनीत करती है।<br>कथन 2 सही — शेष अवधि 6 माह से कम हो तो उपचुनाव नहीं।"},
    {"q":"नगर निगम की वार्ड समितियों के संबंध में निम्नलिखित कथनों पर विचार कीजिए —<br>1. महापौर द्वारा वार्ड समिति में मनोनीत निवासियों को समिति में मताधिकार होता है।<br>2. किसी निगम में वार्ड समितियों की संख्या निगम क्षेत्र की जनसंख्या को 1 लाख से भाग देकर निकाली जाती है।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":1,"e":"कथन 1 गलत — मनोनीत दो निवासियों को मताधिकार नहीं (धारा 48-क(5))।<br>कथन 2 सही — धारा 48-क(2), आधी या अधिक भिन्न को अगली पूर्ण संख्या माना जाता है।"},
    {"q":"छत्तीसगढ़ नगर पालिक निगम अधिनियम के संबंध में निम्नलिखित कथनों पर विचार कीजिए —<br>1. किसी नगर निगम में वार्डों की संख्या 30 से कम और 60 से अधिक नहीं हो सकती।<br>2. महापौर पद के प्रत्याशी की न्यूनतम आयु 21 वर्ष है।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":3,"e":"कथन 1 गलत — वार्ड 40 से कम और 70 से अधिक नहीं (धारा 10(1))।<br>कथन 2 गलत — महापौर हेतु 25 वर्ष; 21 वर्ष पार्षद हेतु है।"},
    {"q":"सरपंच को वापस बुलाने (धारा 21-क) के संबंध में विचार कीजिए —<br>1. वापसी ग्राम सभा के कुल सदस्यों के आधे से अधिक बहुमत से होती है।<br>2. इसके लिए गुप्त मतदान होता है।<br>3. यह प्रक्रिया सरपंच के पद ग्रहण से एक वर्ष बाद कभी भी आरंभ की जा सकती है।<br>सही कथन हैं —","o":["1, 2 और 3","केवल 2 और 3","केवल 1 और 3","केवल 1 और 2"],"a":3,"e":"कथन 1 व 2 सही — धारा 21-क।<br>कथन 3 गलत — पद ग्रहण से ढाई वर्ष तक वापसी की प्रक्रिया आरंभ नहीं हो सकती; 1 वर्ष की सीमा अविश्वास प्रस्ताव की है।"},
    {"q":"छत्तीसगढ़ पंचायत राज अधिनियम के संबंध में निम्नलिखित कथनों पर विचार कीजिए —<br>1. ग्राम पंचायत की बैठक प्रत्येक तीन माह में कम से कम एक बार होना पर्याप्त है।<br>2. ग्राम पंचायत की बैठक की गणपूर्ति कुल सदस्यों का एक-तिहाई है।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":3,"e":"कथन 1 गलत — धारा 44: पंचायत की बैठक प्रति माह कम से कम एक बार; तीन माह की सीमा ग्राम सभा की है।<br>कथन 2 गलत — ग्राम पंचायत की गणपूर्ति 1/2; 1/3 जनपद व ज़िला पंचायत की है।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. छत्तीसगढ़ में सरपंच को ग्राम पंचायत का पंच भी माना जाता है।<br>2. सरपंच के विधायक या सांसद बन जाने पर उसका सरपंच पद रिक्त हो जाता है।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":2,"e":"कथन 1 सही — धारा 17 के अनुसार सरपंच पंचायत का सदस्य (पंच) माना जाता है।<br>कथन 2 सही — सांसद/विधायक या सहकारी समिति अध्यक्ष/उपाध्यक्ष सरपंच नहीं रह सकते; ऐसा होने पर पद रिक्त।"},
    {"q":"सूची-I (कर/उद्ग्रहण) को सूची-II (छत्तीसगढ़ पंचायत राज अधिनियम में स्थिति) से सुमेलित कीजिए —<br>(A) भूमि/भवन पर संपत्ति कर (B) नाट्य प्रदर्शन व सार्वजनिक मनोरंजन पर कर (C) चराई शुल्क (D) भू-राजस्व पर उपकर<br>1. अनुसूची II का वैकल्पिक कर 2. धारा 74 — 50 पैसे प्रति रुपया 3. ग्राम पंचायत का अनिवार्य कर 4. जनपद पंचायत का अनिवार्य कर","o":["A-3, B-4, C-1, D-2","A-4, B-3, C-1, D-2","A-3, B-4, C-2, D-1","A-1, B-4, C-3, D-2"],"a":0,"e":"संपत्ति कर — अनुसूची I-क (ग्राम पंचायत अनिवार्य); मनोरंजन कर — अनुसूची I-ख (जनपद अनिवार्य); चराई शुल्क — अनुसूची II (वैकल्पिक); भू-राजस्व उपकर — धारा 74।"},
    {"q":"सूची-I (प्रावधान) को सूची-II (समय-सीमा) से सुमेलित कीजिए — छत्तीसगढ़ पंचायत राज अधिनियम के अनुसार<br>(A) सरपंच को वापस बुलाने पर प्रारंभिक रोक (B) सरपंच के विरुद्ध अविश्वास पर प्रारंभिक रोक (C) निलंबन आदेश की पुष्टि (D) धारा 40 में हटाए जाने पर निर्वाचन हेतु अयोग्यता<br>1. 6 वर्ष 2. 90 दिन 3. ढाई वर्ष 4. एक वर्ष","o":["A-4, B-3, C-2, D-1","A-3, B-4, C-1, D-2","A-3, B-4, C-2, D-1","A-3, B-2, C-4, D-1"],"a":2,"e":"वापसी — ढाई वर्ष (21-क); अविश्वास — एक वर्ष (21(3)); निलंबन पुष्टि — 90 दिन (39(2)); हटाए जाने पर अयोग्यता — 6 वर्ष (40(2))।"},
    {"q":"सूची-I (पद) को सूची-II (आरक्षण की इकाई) से सुमेलित कीजिए — छत्तीसगढ़ में<br>(A) सरपंच (B) जनपद पंचायत अध्यक्ष (C) ज़िला पंचायत अध्यक्ष (D) नगर निगम महापौर<br>1. ज़िला स्तर 2. राज्य के सभी नगर निगम क्षेत्रों की कुल जनसंख्या 3. खंड (ब्लॉक) स्तर 4. राज्य स्तर (सभी ज़िला पंचायतें)","o":["A-3, B-4, C-1, D-2","A-1, B-3, C-4, D-2","A-3, B-1, C-2, D-4","A-3, B-1, C-4, D-2"],"a":3,"e":"सरपंच — खंड (धारा 17); जनपद अध्यक्ष — ज़िला (धारा 25); ज़िला अध्यक्ष — राज्य (धारा 32); महापौर — सभी नगर निगम मिलाकर (नगर पालिक निगम अधिनियम धारा 11-क)।"},
    {"q":"छत्तीसगढ़ पंचायत राज से जुड़ी निम्नलिखित घटनाओं को कालक्रमानुसार व्यवस्थित कीजिए —<br>1. पंचायतों में महिलाओं हेतु 50% आरक्षण का संशोधन<br>2. अधिनियम में \"एक चक्रानुक्रम\" की परिभाषा जोड़ा जाना<br>3. राज्य गठन के बाद प्रथम त्रिस्तरीय पंचायत आम चुनाव<br>4. पंचायत राज अधिनियम 1993 को राज्यपाल की अनुमति","o":["4, 3, 2, 1","3, 4, 1, 2","4, 1, 3, 2","4, 3, 1, 2"],"a":3,"e":"अनुमति — 24 जनवरी 1994 (मूल म.प्र. अधिनियम); प्रथम पंचायत चुनाव (छत्तीसगढ़) — 2005; 50% महिला आरक्षण — 2008; \"एक चक्रानुक्रम\" — 2015।"},
    {"q":"निम्नलिखित में से कौन-सा युग्म (बैठक — गणपूर्ति) सही सुमेलित नहीं है?","o":["ग्राम पंचायत की बैठक — कुल सदस्यों का 1/2","जनपद पंचायत की बैठक — कुल सदस्यों का 1/3","सामान्य क्षेत्र की ग्राम सभा — कुल सदस्यों का 1/10","नगर निगम की महापौर-परिषद — कुल सदस्यों का 1/3"],"a":3,"e":"महापौर-परिषद की गणपूर्ति कुल सदस्यों का आधा है (नगर पालिक निगम अधिनियम धारा 49)। शेष तीनों युग्म सही हैं।"},
    {"q":"अभिकथन (A): छत्तीसगढ़ में जनपद पंचायत अध्यक्ष के विरुद्ध पारित अविश्वास प्रस्ताव पर विवाद कलेक्टर को भेजा जाता है।<br>कारण (R): सरपंच के विरुद्ध पारित अविश्वास प्रस्ताव पर विवाद 7 दिन के भीतर कलेक्टर को भेजा जाता है।","o":["A और R दोनों सही हैं तथा R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है, R गलत है","A गलत है, R सही है"],"a":3,"e":"A गलत — जनपद अध्यक्ष का विवाद 10 दिन में संचालक, पंचायत को (धारा 28(4))।<br>R सही — सरपंच का विवाद 7 दिन में कलेक्टर को (धारा 21(4))।"},
    {"q":"अभिकथन (A): छत्तीसगढ़ में कोई राज्यसभा सदस्य भी ज़िला पंचायत का सदस्य हो सकता है।<br>कारण (R): जिस राज्यसभा सदस्य का नाम ज़िले की किसी ग्राम पंचायत की मतदाता सूची में दर्ज हो, वह उस ज़िला पंचायत का सदस्य होता है।","o":["A और R दोनों सही हैं तथा R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है, R गलत है","A गलत है, R सही है"],"a":0,"e":"A सही — धारा 29 में राज्यसभा सदस्य भी सम्मिलित।<br>R सही और A की व्याख्या — सदस्यता की शर्त ज़िले की ग्राम पंचायत मतदाता सूची में नाम होना है।"},
    {"q":"अभिकथन (A): छत्तीसगढ़ में जनपद पंचायत अध्यक्ष पदों के आरक्षण की इकाई ज़िला है।<br>कारण (R): जनपद पंचायत अध्यक्ष का चुनाव ज़िले के सभी मतदाता प्रत्यक्ष रूप से करते हैं।","o":["A और R दोनों सही हैं तथा R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है, R गलत है","A गलत है, R सही है"],"a":2,"e":"A सही — धारा 25: ज़िले की SC/ST जनसंख्या के अनुपात में ज़िले के जनपद अध्यक्ष पद आरक्षित।<br>R गलत — जनपद अध्यक्ष निर्वाचित सदस्यों द्वारा अपने में से चुना जाता है।"},
    {"q":"अभिकथन (A): छत्तीसगढ़ में ग्राम सभा की वार्षिक बैठक में ग्राम पंचायत का वार्षिक लेखा-विवरण और प्रशासन प्रतिवेदन रखा जाता है।<br>कारण (R): ग्राम सभा की बैठक प्रत्येक तीन माह में कम से कम एक बार होनी अनिवार्य है।","o":["A सही है, R गलत है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A और R दोनों सही हैं तथा R, A की सही व्याख्या है","A गलत है, R सही है"],"a":1,"e":"A सही — धारा 7(2), वार्षिक बैठक अगले वित्त वर्ष से 3 माह पहले।<br>R सही — धारा 6(1); पर त्रैमासिक बैठक का नियम वार्षिक बैठक की विषय-सूची की व्याख्या नहीं करता।"},
    {"q":"अभिकथन (A): छत्तीसगढ़ में जनपद पंचायत में खंड के कुछ सरपंच भी सदस्य होते हैं।<br>कारण (R): छत्तीसगढ़ में पंचायत चुनाव राजनीतिक दलों के चुनाव-चिह्नों पर नहीं होते।","o":["A और R दोनों सही हैं तथा R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है, R गलत है","A गलत है, R सही है"],"a":1,"e":"A सही — धारा 22: खंड के 1/5 सरपंच, एक वर्ष हेतु लॉटरी से चक्रानुक्रम में।<br>R सही — पर गैर-दलीय चुनाव का सरपंचों की सदस्यता से कोई संबंध नहीं।"},
    {"q":"अभिकथन (A): नगर निगम में राज्य सरकार द्वारा मनोनीत सदस्य महापौर-परिषद के निर्णयों पर मत दे सकते हैं।<br>कारण (R): मनोनीत सदस्यों को नगर निगम की बैठकों में मत देने का अधिकार नहीं होता।","o":["A और R दोनों सही हैं तथा R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है, R गलत है","A गलत है, R सही है"],"a":3,"e":"A गलत — महापौर-परिषद के सदस्य महापौर द्वारा निर्वाचित पार्षदों में से ही मनोनीत होते हैं; राज्य द्वारा मनोनीत सदस्य उसमें नहीं।<br>R सही — धारा 9(3) व अनु. 243R(2)(a)।"},
    {"q":"अभिकथन (A): छत्तीसगढ़ में ग्राम पंचायत सचिव किसी पंचायत पदाधिकारी का संबंधी नहीं हो सकता।<br>कारण (R): ग्राम पंचायत सचिव की नियुक्ति ग्राम सभा अपने सदस्यों में से करती है।","o":["A और R दोनों सही हैं तथा R, A की सही व्याख्या है","A गलत है, R सही है","A सही है, R गलत है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है"],"a":2,"e":"A सही — धारा 69 का प्रतिबंध।<br>R गलत — सचिव की नियुक्ति राज्य सरकार या विहित प्राधिकारी करता है, ग्राम सभा नहीं।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. छत्तीसगढ़ में जनपद पंचायत का प्रत्येक निर्वाचन क्षेत्र लगभग 50,000 जनसंख्या का होता है।<br>2. ज़िला पंचायत में निर्वाचन क्षेत्रों की अधिकतम संख्या 25 है।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":3,"e":"कथन 1 गलत — जनपद में ~5,000 पर एक; 50,000 ज़िला पंचायत हेतु है।<br>कथन 2 गलत — ज़िला पंचायत में अधिकतम 35; 25 जनपद पंचायत की सीमा है।"},
    {"q":"नगरपालिकाओं में किसके प्रतिनिधित्व का उपबंध राज्य विधानमंडल अनुच्छेद 243R(2) के अंतर्गत कर सकता है?","o":["केवल राज्यपाल द्वारा मनोनीत व्यक्ति","ज़िला न्यायाधीश","उच्च न्यायालय के न्यायाधीश","वार्ड समितियों के अध्यक्ष (समिति-अध्यक्ष)"],"a":3,"e":"अनु. 243R(2)(a) — विशेष ज्ञान वाले व्यक्ति (बिना मताधिकार), क्षेत्र के लोकसभा/विधानसभा सदस्य, पंजीकृत राज्यसभा/विधान परिषद सदस्य और 243S(5) की समितियों के अध्यक्ष।"},
    {"q":"संविधान के अनुसार राज्य निर्वाचन आयुक्त की सेवा-शर्तें और पदावधि कौन निर्धारित करता है?","o":["राष्ट्रपति","भारत निर्वाचन आयोग","राज्य का मुख्य न्यायाधीश","राज्यपाल, राज्य विधानमंडल की विधि के अधीन रहते हुए"],"a":3,"e":"अनु. 243K(2) — सेवा-शर्तें और पदावधि राज्यपाल नियम द्वारा तय करता है (विधानमंडल की विधि के अधीन)। नियुक्ति के बाद इन्हें उसके अहित में नहीं बदला जा सकता।"},
    {"q":"के. संथानम समिति (1963) की एक प्रमुख सिफ़ारिश क्या थी?","o":["पंचायती राज वित्त निगम की स्थापना","मंडल पंचायतों का गठन","राजनीतिक दलों की प्रत्यक्ष भागीदारी","ज़िला विकास आयुक्त का पद"],"a":0,"e":"संथानम समिति ने पंचायतों को भू-राजस्व व गृह कर पर विशेष कर लगाने की शक्ति, सभी अनुदानों को एकमुश्त देने और पंचायती राज वित्त निगम बनाने का सुझाव दिया।"},
    {"q":"महात्मा गांधी राष्ट्रीय ग्रामीण रोज़गार गारंटी अधिनियम के अंतर्गत कार्यों का सामाजिक अंकेक्षण (Social Audit) कौन करता है?","o":["ज़िला कलेक्टर","ग्राम सभा","नियंत्रक-महालेखापरीक्षक","जनपद पंचायत की सामान्य प्रशासन समिति"],"a":1,"e":"मनरेगा की धारा 17 — ग्राम सभा ग्राम पंचायत में होने वाले सभी कार्यों का सामाजिक अंकेक्षण करती है।"},
    {"q":"मनरेगा के अंतर्गत कार्य हेतु आवेदन करने के कितने दिनों के भीतर रोज़गार न मिलने पर बेरोज़गारी भत्ता देय होता है?","o":["7 दिन","30 दिन","15 दिन","60 दिन"],"a":2,"e":"धारा 7 — आवेदन के 15 दिन में काम न मिलने पर आवेदक बेरोज़गारी भत्ते का हकदार। कार्यस्थल 5 किमी से अधिक दूर हो तो 10% अतिरिक्त मज़दूरी।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. मनरेगा के अनुसार कम से कम एक-तिहाई लाभार्थी महिलाएँ होनी चाहिए।<br>2. मनरेगा के अनुसार लागत की दृष्टि से कम से कम 50% कार्य ग्राम पंचायतों के माध्यम से कराए जाने चाहिए।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":2,"e":"कथन 1 सही — अनुसूची II के अनुसार कम से कम 1/3 लाभार्थी महिलाएँ।<br>कथन 2 सही — धारा 16(5): लागत के अनुसार कम से कम 50% कार्य ग्राम पंचायतों को।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. मनरेगा के अंतर्गत कार्य निवास से 5 किमी के बाहर दिया जाए तो 25% अतिरिक्त मज़दूरी देय होती है।<br>2. मनरेगा की योजनाओं के अंतर्गत सृजित कार्यों का सामाजिक अंकेक्षण ग्राम सभा करती है।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":1,"e":"कथन 1 गलत — 5 किमी के बाहर कार्य पर अतिरिक्त मज़दूरी 10% है।<br>कथन 2 सही — धारा 17।"},
    {"q":"अभिकथन (A): मनरेगा में ग्राम सभा कार्यों का सामाजिक अंकेक्षण करती है।<br>कारण (R): मनरेगा में लागत की दृष्टि से कम से कम आधे कार्य ग्राम पंचायतों द्वारा कराए जाते हैं।","o":["A और R दोनों सही हैं तथा R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है, R गलत है","A गलत है, R सही है"],"a":1,"e":"दोनों सही — A धारा 17, R धारा 16(5)। पर सामाजिक अंकेक्षण का उद्देश्य पारदर्शिता व जवाबदेही है, न कि कार्य-आवंटन का अनुपात; अतः R, A की व्याख्या नहीं।"},
    {"q":"प्रधानमंत्री ग्राम सड़क योजना (मूल) के अंतर्गत पाँचवीं अनुसूची वाले जनजातीय तथा पहाड़ी क्षेत्रों में न्यूनतम कितनी जनसंख्या वाली असंबद्ध बसाहटें पात्र थीं?","o":["100","500","1,000","250"],"a":3,"e":"मैदानी क्षेत्रों में 500+ और पहाड़ी, मरुस्थलीय व पाँचवीं अनुसूची (जनजातीय) क्षेत्रों में 250+ जनसंख्या वाली बसाहटें (जनगणना 2001 के आधार पर)।"},
    {"q":"श्यामा प्रसाद मुखर्जी रूर्बन मिशन के अंतर्गत देश में कितने \"रूर्बन क्लस्टर\" विकसित करने का लक्ष्य रखा गया?","o":["100","300","500","1,000"],"a":1,"e":"तीन वर्षों में 300 रूर्बन क्लस्टर का लक्ष्य था। राष्ट्रीय शुभारंभ 21 फ़रवरी 2016 को कुरुभाट (राजनांदगाँव) से हुआ।"},
    {"q":"प्रधानमंत्री आवास योजना — ग्रामीण के लाभार्थियों की पहचान किस आँकड़े के आधार पर, ग्राम सभा द्वारा सत्यापन के साथ, की गई?","o":["जनगणना 2001","BPL सूची 2002","सामाजिक-आर्थिक एवं जाति जनगणना (SECC) 2011","राष्ट्रीय परिवार स्वास्थ्य सर्वेक्षण"],"a":2,"e":"PMAY-G में SECC 2011 के आवास-वंचना मानदंडों से सूची बनाकर ग्राम सभा सत्यापन करती है। यह इंदिरा आवास योजना का पुनर्गठित रूप है।"},
    {"q":"जल जीवन मिशन के अंतर्गत ग्राम पंचायत की उप-समिति \"ग्राम जल एवं स्वच्छता समिति\" (पानी समिति) में कम से कम कितनी महिला सदस्य होनी चाहिए?","o":["एक-तिहाई","25%","50%","कोई अनिवार्यता नहीं"],"a":2,"e":"JJM दिशानिर्देश — पानी समिति में कम से कम 50% महिलाएँ और कमज़ोर वर्गों का आनुपातिक प्रतिनिधित्व; यह ग्राम कार्य योजना बनाकर गाँव की जल आपूर्ति का संचालन करती है।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. चौदहवें वित्त आयोग ने ग्राम पंचायतों के अनुदान को मूल (basic) और निष्पादन (performance) अनुदान में 90 : 10 के अनुपात में बाँटा।<br>2. पंद्रहवें वित्त आयोग के बद्ध अनुदान स्वच्छता और पेयजल से जुड़े थे।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":2,"e":"कथन 1 सही — 14वें वित्त आयोग (2015–20) में ग्राम पंचायतों हेतु 90% मूल व 10% निष्पादन अनुदान।<br>कथन 2 सही — 15वें आयोग के 60% बद्ध अनुदान स्वच्छता/ODF और पेयजल/जल संचयन हेतु।"},
    {"q":"निम्नलिखित ग्रामीण विकास योजनाओं को उनके शुभारंभ के कालक्रम में व्यवस्थित कीजिए —<br>1. सांसद आदर्श ग्राम योजना<br>2. दीनदयाल उपाध्याय ग्रामीण कौशल्य योजना<br>3. श्यामा प्रसाद मुखर्जी रूर्बन मिशन<br>4. स्वामित्व योजना","o":["1, 2, 3, 4","2, 1, 4, 3","2, 1, 3, 4","1, 3, 2, 4"],"a":2,"e":"DDU-GKY — 25 सितंबर 2014; SAGY — 11 अक्टूबर 2014; रूर्बन — 21 फ़रवरी 2016; स्वामित्व — 24 अप्रैल 2020।"},
    {"q":"निम्नलिखित को कालक्रमानुसार व्यवस्थित कीजिए —<br>1. 97वाँ संविधान संशोधन (सहकारी समितियाँ)<br>2. 74वाँ संविधान संशोधन (नगरपालिकाएँ)<br>3. 22वाँ संविधान संशोधन (अनु. 244A)<br>4. 64वाँ संविधान संशोधन विधेयक (पंचायतें)","o":["3, 4, 1, 2","4, 3, 2, 1","3, 2, 4, 1","3, 4, 2, 1"],"a":3,"e":"22वाँ संशोधन — 1969; 64वाँ विधेयक — 1989 (राज्यसभा में गिरा); 74वाँ संशोधन — 1992 (1 जून 1993 से लागू); 97वाँ संशोधन — 2011।"},
    {"q":"सूची-I (अनुच्छेद) को सूची-II (विषय) से सुमेलित कीजिए —<br>(A) 243F (B) 243-I (C) 243K (D) 243N<br>1. पूर्ववर्ती विधियों और पंचायतों का बने रहना 2. राज्य निर्वाचन आयोग 3. सदस्यता हेतु अयोग्यताएँ 4. वित्त आयोग","o":["A-3, B-2, C-4, D-1","A-3, B-4, C-2, D-1","A-1, B-4, C-2, D-3","A-3, B-4, C-1, D-2"],"a":1,"e":"243F — अयोग्यताएँ; 243-I — राज्य वित्त आयोग; 243K — राज्य निर्वाचन आयोग; 243N — पूर्ववर्ती विधियाँ अधिकतम 1 वर्ष तक और विद्यमान पंचायतें अवधि पूरी होने तक।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. राज्य निर्वाचन आयुक्त की नियुक्ति के बाद उसकी सेवा-शर्तों में उसके लिए अलाभकारी परिवर्तन किया जा सकता है।<br>2. पंचायतों की मतदाता सूची तैयार कराने का अधीक्षण, निर्देशन व नियंत्रण राज्य निर्वाचन आयोग में निहित है।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":1,"e":"कथन 1 गलत — अनु. 243K(2) का परंतुक ऐसा परिवर्तन वर्जित करता है।<br>कथन 2 सही — अनु. 243K(1); छत्तीसगढ़ पंचायत राज अधिनियम धारा 42 में भी यही।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. अनुच्छेद 243D(4) के अनुसार प्रत्येक स्तर पर पंचायत अध्यक्षों के कुल पदों में से कम से कम एक-तिहाई महिलाओं हेतु आरक्षित होंगे।<br>2. संविधान स्वयं पंचायत अध्यक्ष पदों का SC हेतु 15% और ST हेतु 7.5% निश्चित आरक्षण निर्धारित करता है।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":0,"e":"कथन 1 सही — अनु. 243D(4)।<br>कथन 2 गलत — अध्यक्ष पदों का आरक्षण राज्य विधानमंडल विधि द्वारा, राज्य की SC/ST जनसंख्या के अनुपात में तय करता है; कोई निश्चित प्रतिशत नहीं।"},
    {"q":"निम्नलिखित में से कौन-सा युग्म (योजना — आरंभ) सही सुमेलित नहीं है?","o":["प्रधानमंत्री ग्राम सड़क योजना — 25 दिसंबर 2000","दीनदयाल उपाध्याय ग्रामीण कौशल्य योजना — 25 सितंबर 2014","जल जीवन मिशन — 15 अगस्त 2019","राष्ट्रीय ग्रामीण आजीविका मिशन — अप्रैल 2020"],"a":3,"e":"राष्ट्रीय ग्रामीण आजीविका मिशन जून 2011 में आरंभ हुआ (छत्तीसगढ़ में \"बिहान\")। अप्रैल 2020 में स्वामित्व योजना शुरू हुई थी।"},
    {"q":"निम्नलिखित में से कौन-सा युग्म (समिति — विषय) सही सुमेलित नहीं है?","o":["के. संथानम समिति — पंचायतों का वित्त","एम.एल. दांतवाला समिति — प्रखंड स्तरीय नियोजन","सी.एच. हनुमंत राव समिति — ज़िला स्तरीय नियोजन","पी.के. थुंगन समिति — पंचायत चुनावों में राजनीतिक दलों की भागीदारी"],"a":3,"e":"राजनीतिक दलों की भागीदारी की सिफ़ारिश अशोक मेहता समिति ने की थी। थुंगन समिति (1988) ने पंचायतों को संवैधानिक मान्यता और कलेक्टर को ज़िला परिषद का CEO बनाने का सुझाव दिया।"},
    {"q":"अभिकथन (A): प्रधानमंत्री ग्राम सड़क योजना में जनजातीय (पाँचवीं अनुसूची) क्षेत्रों हेतु पात्र बसाहट का जनसंख्या मानदंड मैदानी क्षेत्रों से कम रखा गया।<br>कारण (R): जनजातीय व पहाड़ी क्षेत्रों में बसाहटें छोटी और बिखरी हुई होती हैं।","o":["A और R दोनों सही हैं तथा R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है, R गलत है","A गलत है, R सही है"],"a":0,"e":"A सही — मैदानी 500+, जनजातीय/पहाड़ी 250+।<br>R सही और A की व्याख्या — बिखरी व छोटी बसाहटों को जोड़ने के लिए ही कम मानदंड रखा गया।"},
    {"q":"बारहवीं अनुसूची के संबंध में विचार कीजिए — निम्न में से कौन-से विषय उसमें सम्मिलित हैं?<br>1. अग्निशमन सेवाएँ<br>2. सार्वजनिक वितरण प्रणाली<br>3. नगरीय गरीबी उन्मूलन<br>सही उत्तर चुनिए —","o":["केवल 1 और 3","केवल 1 और 2","केवल 2 और 3","1, 2 और 3"],"a":0,"e":"अग्निशमन सेवाएँ (7वाँ विषय) और नगरीय गरीबी उन्मूलन — 12वीं अनुसूची में।<br>सार्वजनिक वितरण प्रणाली 11वीं अनुसूची (28वाँ विषय) में है, 12वीं में नहीं।"},
    {"q":"छत्तीसगढ़ पंचायत राज अधिनियम के वित्तीय प्रावधानों के संबंध में निम्नलिखित कथनों पर विचार कीजिए —<br>1. ज़िला पंचायत द्वारा बढ़ाए गए भू-राजस्व उपकर की आधी राशि ग्राम पंचायतों को मिलती है।<br>2. खंड के भीतर अचल संपत्ति हस्तांतरण पर लगने वाले 1% अतिरिक्त स्टाम्प शुल्क की राशि जनपद पंचायतों को अनुदान रूप में दी जाती है।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":2,"e":"कथन 1 सही — धारा 76-क: 50% ग्राम, 25% जनपद, 25% ज़िला पंचायत।<br>कथन 2 सही — धारा 75।"},
    {"q":"ग्राम पंचायत की स्थायी समितियों के संबंध में निम्नलिखित कथनों पर विचार कीजिए —<br>1. ग्राम पंचायत अधिकतम पाँच स्थायी समितियाँ गठित कर सकती है।<br>2. समितियों में सहयोजित विशेषज्ञों को मत देने का अधिकार होता है।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":0,"e":"कथन 1 सही — धारा 46।<br>कथन 2 गलत — सहयोजित दो विशेषज्ञों को मताधिकार नहीं होता; कोई सदस्य दो से अधिक समितियों में नहीं रह सकता।"},
    {"q":"राष्ट्रीय ग्रामीण आजीविका मिशन (NRLM) का नाम बदलकर क्या रखा गया?","o":["दीनदयाल अंत्योदय योजना — राष्ट्रीय ग्रामीण आजीविका मिशन","प्रधानमंत्री आजीविका मिशन","ग्राम स्वराज आजीविका योजना","स्वर्णजयंती ग्राम स्वरोज़गार योजना"],"a":0,"e":"NRLM (जून 2011) अब DAY-NRLM कहलाता है। इसकी पूर्ववर्ती योजना स्वर्णजयंती ग्राम स्वरोज़गार योजना (1999) थी; छत्तीसगढ़ में इसका नाम \"बिहान\" है।"},
    {"q":"अनुच्छेद 243-I के अनुसार राज्य वित्त आयोग की संरचना, सदस्यों की अर्हताएँ और चयन की रीति कौन निर्धारित करता है?","o":["केंद्रीय वित्त आयोग","राज्य विधानमंडल, विधि द्वारा","राष्ट्रपति","नियंत्रक-महालेखापरीक्षक"],"a":1,"e":"अनु. 243-I(2) — संरचना, अर्हताएँ और चयन की रीति राज्य विधानमंडल विधि द्वारा तय करता है; आयोग का गठन राज्यपाल करता है।"},
    {"q":"संविधान के अनुसार पंचायत के लेखाओं की संपरीक्षा (ऑडिट) के संबंध में उपबंध कौन करता है?","o":["नियंत्रक-महालेखापरीक्षक, अनिवार्यतः","राज्य वित्त आयोग","राज्य विधानमंडल, विधि द्वारा","ज़िला कलेक्टर"],"a":2,"e":"अनु. 243J — लेखा रखने और उनकी संपरीक्षा का उपबंध राज्य विधानमंडल विधि द्वारा करता है। छत्तीसगढ़ में धारा 129 के अंतर्गत पृथक अंकेक्षण संगठन है।"},
    {"q":"अभिकथन (A): छत्तीसगढ़ में ज़िला पंचायत अध्यक्ष का चुनाव ज़िले के मतदाता प्रत्यक्ष रूप से नहीं करते।<br>कारण (R): अनुच्छेद 243C(5)(b) के अनुसार मध्यवर्ती और ज़िला स्तर की पंचायत का अध्यक्ष उसके निर्वाचित सदस्यों द्वारा अपने में से चुना जाएगा।","o":["A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है, R गलत है","A गलत है, R सही है","A और R दोनों सही हैं तथा R, A की सही व्याख्या है"],"a":3,"e":"A सही — धारा 32(3)।<br>R सही और A की व्याख्या — संविधान ही मध्यवर्ती व ज़िला अध्यक्षों के अप्रत्यक्ष चुनाव को अनिवार्य करता है; ग्राम स्तर पर यह राज्य पर छोड़ा गया है।"},
    {"q":"अभिकथन (A): छत्तीसगढ़ में सरपंच का चुनाव ग्राम पंचायत क्षेत्र के मतदाता प्रत्यक्ष रूप से करते हैं।<br>कारण (R): संविधान सभी स्तरों की पंचायतों के अध्यक्षों का प्रत्यक्ष चुनाव अनिवार्य करता है।","o":["A और R दोनों सही हैं तथा R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A गलत है, R सही है","A सही है, R गलत है"],"a":3,"e":"A सही — धारा 17 के अनुसार सरपंच प्रत्यक्ष निर्वाचित।<br>R गलत — ग्राम स्तर के अध्यक्ष का चुनाव राज्य विधि पर छोड़ा गया है (243C(5)(a)), जबकि मध्यवर्ती व ज़िला अध्यक्ष अप्रत्यक्ष चुने जाते हैं।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. पेसा अधिनियम का क्रमांक 1996 का अधिनियम संख्या 40 है।<br>2. पेसा अधिनियम 24 दिसंबर 1996 से लागू हुआ।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":2,"e":"कथन 1 सही — अधिनियम सं. 40, 1996।<br>कथन 2 सही — 24 दिसंबर 1996।"},
    {"q":"छत्तीसगढ़ के अनुसूचित क्षेत्र किस राष्ट्रपति आदेश द्वारा विनिर्दिष्ट हैं?","o":["अनुसूचित क्षेत्र (भाग क राज्य) आदेश, 1950","अनुसूचित क्षेत्र (मध्यप्रदेश) आदेश, 1977","अनुसूचित क्षेत्र (छत्तीसगढ़, झारखंड और मध्यप्रदेश राज्य) आदेश, 2003","अनुसूचित क्षेत्र (छत्तीसगढ़) आदेश, 2000"],"a":2,"e":"राज्य पुनर्गठन (2000) के बाद 2003 के राष्ट्रपति आदेश से तीनों नए/पुनर्गठित राज्यों के अनुसूचित क्षेत्र पुनः विनिर्दिष्ट हुए।"},
    {"q":"अनुसूचित क्षेत्रों वाले राज्य की जनजाति सलाहकार परिषद में अधिकतम कितने सदस्य हो सकते हैं?","o":["10","15","25","20"],"a":3,"e":"पाँचवीं अनुसूची पैरा 4 — अधिकतम 20 सदस्य, जिनमें से यथासंभव 3/4 राज्य विधानसभा के ST प्रतिनिधि।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. अनुसूचित क्षेत्र की ग्राम सभा, ग्राम पंचायत के माध्यम से ग्राम बाज़ारों और पशु मेलों सहित मेलों का प्रबंधन करती है।<br>2. छत्तीसगढ़ में अनुसूचित क्षेत्र की ग्राम सभा की गणपूर्ति में महिलाओं की कोई न्यूनतम संख्या आवश्यक नहीं है।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":0,"e":"कथन 1 सही — अध्याय 14-क (पेसा 4(m)(iv) के अनुरूप)।<br>कथन 2 गलत — गणपूर्ति कुल सदस्यों का 1/3, जिसमें कम से कम 1/3 महिलाएँ।"}
  ]
});
